window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-endocrinologia-end-1"]={"block":"medcurso:medcurso-endocrinologia-end-1","label":"Medcurso · END 1","count":433,"questions":[{"id":"medcurso-endocrinologia-end-1-345467","number":"345467","sourceNumber":"345467","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 65 anos apresenta quadro de fadiga e fraqueza nas últimas 2 semanas. Ela\ntem histórico de hipertensão, diabete tipo 2 e artrite reumatoide, em uso de metotrexato e\nprednisona. Por causa do controle inadequado, o etanercepte foi adicionado há 2 semanas,\nocasião em que ela decidiu descontinuar a prednisona devido ao aumento de hematomas em sua\npele. Além de metrotexato e etanercepte, ela está em uso de ácido fólico, metformina e aspirina em\nbaixas doses. Ao exame físico: pressão arterial: 110 x 68 mmHg sentada e 90 x 64 mmHg em pé;\nfrequência cardíaca: 102 bpm sentada e 110 bpm em pé; observa-se edema sinovial simétrico nas\narticulações metacarpofalângicas e punhos bilateralmente. Exames laboratoriais mostram um nível\nde cortisol às 8h00 de 2 µg/dL (normal: 5 a 25). O manejo inicial de escolha é:","options":{"A":"Tomografia de adrenais.","B":"Hidrocortisona.","C":"Teste de estimulação com ACTH após administração de dexametasona.","D":"Teste de estimulação de hormônio adrenocorticotrófico (ACTH)."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-345515","number":"345515","sourceNumber":"345515","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação ao preparo do paciente com hipertireoidismo para uma cirurgia de urgência\nnão tireoidiana, assinale a alternativa\nINCORRETA:","options":{"A":"O metimazol inibe a conversão periférica de T4 (tiroxina) em T3 (triiodotironina).","B":"Iodo inorgânico impede a liberação de T4 e T3 da tireoide.","C":"O propiltiouracil inibe a síntese de hormônios tireoidianos.","D":"O uso de betabloqueadores beta-adrenérgicos visa antagonizar as manifestações periféricas da\ntereotoxicose."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-343853","number":"343853","sourceNumber":"343853","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre a Hipercalcemia é CORRETO afirmar:","options":{"A":"Iatrogenia e efeitos colaterais medicamentosos são superiores na incidência desta alteração em\nrelação ao Hiperparatireoidismo primário e às neoplasias.","B":"O tratamento é focado no estímulo direto da excreção do cálcio pelo receptor específico na Alça\nde Henle, com a acidificação do fluído urinário.","C":"Entre os bifosfonados, o Clodronato é o que tem ação mais rápida, contudo é principal causa de\nnecrose de mandíbula.","D":"Hemodiálise é uma opção terapêutica avaliada."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-291765","number":"291765","sourceNumber":"291765","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Homem, 45 anos de idade, morador de zona rural, procurou atendimento médico por\nqueixa de úlcera dolorosa em dorso do pé esquerdo há seis meses. No interrogatório sistemático,\nqueixou-se, também, de astenia e tosse seca. Tabagista de 25 anos/maço, sem outras\ncomorbidades. Ao exame físico, regular estado geral, afebril. Apresentava úlcera com 20 mm de\ndiâmetro, com bordas elevadas, eritematosas e fundo com pontilhado hemático. Realizada biópsia\nda lesão, evidenciou processo granulomatoso, com presença de células leveduriformes com\nbrotamento em roda de leme. Radiografia de tórax com infiltrado retículo-nodular difuso. Paciente\nperdeu seguimento e, três meses depois, voltou a procurar atendimento médico com quadro de\nhipotensão, apresentando exames laboratoriais com Na = 119 mEq/L; e K = 6,1mEq/L,\nnecessitando de internação hospitalar. Diante do caso, Indique a hipótese diagnóstica principal\ndiante da complicação apresentada posteriormente.","options":{"A":"Doença de Addison.","B":"Síndrome de Cushing.","C":"Síndrome perdedora de sal.","D":"Síndrome de secreção inapropriada de hormônio antidiurético."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-283281","number":"283281","sourceNumber":"283281","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 28 anos apresenta Síndrome de Cushing associada a carcinoma de adrenal\nsecretor de cortisol. Dos abaixo, os achados MENOS prováveis são:","options":{"A":"Osteopenia e fraqueza muscular.","B":"Hisurtismo e ganho de peso.","C":"Intolerância a glicose e acne.","D":"Hipercalemia e hiperpigmentação cutânea."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-281104","number":"281104","sourceNumber":"281104","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Das patologias endócrinas citadas nas alternativas abaixo, a que NÃO faz parte da\nNEM tipo 1 (neoplasia endócrina tipo 1) é:","options":{"A":"Hiperparatireoidismo primário.","B":"Gastrinoma.","C":"Insulinoma.","D":"Acromegalia.","E":"Carcinoma medular de tireoide."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-281109","number":"281109","sourceNumber":"281109","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 26 anos de idade é admitido na unidade de terapia intensiva em\npósoperatório de excisão transesfenoidal de\ntumor de hipófise. Evolui no pós-operatório imediato\ncom polidipsia e poliúria. Neste momento a glicemia capilar foi de 152mg/dl. Levando em\nconsideração a hipótese diagnóstica principal, o tratamento seria:","options":{"A":"insulina regular conforme a glicemia capilar.","B":"restrição de água oral.","C":"desmopressina.","D":"dexametasona.","E":"metformina."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-291775","number":"291775","sourceNumber":"291775","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Indique a principal suspeita diagnóstica para o nódulo cervical.","options":{"A":"Metástase linfonodal.","B":"Carcinoma papilífero de tireoide.","C":"Cisto tireoidiano.","D":"Lipoma de subcutâneo."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/291775.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-291776","number":"291776","sourceNumber":"291776","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Determine a conduta mais adequada para confirmar o diagnóstico.","options":{"A":"Realizar tomografia computadorizada de cabeça, pescoço e tórax.","B":"Orientar a paciente que se trata de doença benigna e que não há necessidade de outro exame\ncomplementar.","C":"Realizar punção aspirativa, com agulha fina, do nódulo.","D":"Indicar exérese do nódulo."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/291776.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-291777","number":"291777","sourceNumber":"291777","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Caso indicado tratamento cirúrgico para o nódulo, determine, dentre as opções\napresentadas, a principal preocupação do cirurgião nas primeiras 48 horas do pós-operatório.","options":{"A":"Infecção do sítio cirúrgico.","B":"Hipotireoidismo.","C":"Hemorragia.","D":"Hipocalcemia."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/291777.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-283293","number":"283293","sourceNumber":"283293","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A triagem neonatal ou teste do pezinho é uma estratégia de prevenção, sendo o\nhipotireoidismo congênito uma das doenças triadas, considerando essa alteração marque a\nalternativa CORRETA:","options":{"A":"É a principal causa de déficit cognitivo tratável na infância.","B":"Não é uma condição grave na infância.","C":"Fazem parte da clínica no neonato letargia, constipação e queda de cabelo.","D":"O tratamento somente é indicado na presença do quadro clínico, geralmente, a partir do 2º mês\nde vida."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-281113","number":"281113","sourceNumber":"281113","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 28 anos do sexo feminino procura o consultório para avaliação de rotina.\nAo exame físico foi observado nódulo de\ntireoide confirmado por ultrassonografia, sólido, de 1,1 cm.\nVocê solicitou exames de função tireoidiana que demonstraram TSH reduzido e T4 livre normal.\n\nNeste caso, a conduta adequada em relação ao nódulo é:","options":{"A":"Monitoramento com ultrassonografia.","B":"Punção aspirativa por agulha fina.","C":"Tratamento com iodo radioativo.","D":"Cintilografia da tireoide.","E":"Tireoidectomia."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-283316","number":"283316","sourceNumber":"283316","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Durante a cirurgia de tireoidectomia a principal estrutura nervosa a ser identificada e\npreservada é o nervo laríngeo recorrente. Estes são responsáveis, entre outras, pela abertura\nglótica decorrente da inervação da seguinte estrutura muscular:","options":{"A":"mm. Tireohioideo.","B":"mm. Cricoaritenóideo.","C":"mm. Cricofaringeo.","D":"mm. Cricotireoideo."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-251859","number":"251859","sourceNumber":"251859","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente feminina com 65 anos apresenta fadiga, intolerância ao frio, ganho de peso,\ndepressão, menorragia, rouquidão, pele seca e áspera, bradicardia e reflexos tendinosos profundos\nlentos. Assinale as mais prováveis alterações laboratoriais encontradas:","options":{"A":"TSH diminuído e T4 elevado.","B":"TSH aumentado e T4 diminuído.","C":"TSH normal e T4 aumentado.","D":"TSH diminuído e T4 diminuído."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-247176","number":"247176","sourceNumber":"247176","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino, 53 anos, apresenta queixa de pele seca, fadiga,\nconstipação e ganho de peso nos últimos seis\nmeses. Trabalha em mercado de frutos do mar,\nrelata internação prévia para realização de histerectomia há 18 meses e faz uso ocasional de\n\nanti-inflamatório para alívio de dorsalgia. A dosagem de TSH é de 39 uIU/L. Assinale a alternativa\nCORRETA, que apresenta o diagnóstico mais provável.","options":{"A":"Hipotireoidismo pós-cirúrgico.","B":"Hipotireoidismo terciário.","C":"Hipotireoidismo secundário à intoxicação por iodo.","D":"Hipotireoidismo medicamentoso.","E":"Hipotireoidismo primário."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-217681","number":"217681","sourceNumber":"217681","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 70 anos de idade, portadora de doença de Graves, em uso irregular de\nmetimazol, evoluiu no pós-operatório imediato de endarterectomia com dispneia súbita, associada à\ntaquicardia (FC de 128 bpm e pulso irregular), à febre (38 graus), à PA de 100 x 80 mmHg e à\nagitação psicomotora. O eletrocardiograma mostrou fibrilação atrial de alta resposta ventricular\n(prévio em ritmo sinusal) e o ecocardiograma transtorácico, o dímero D e a troponina estavam\nnormais. Com base nesse caso hipotético, assinale a alternativa que apresenta o diagnóstico mais\nprovável.","options":{"A":"Tempestade tireoidiana.","B":"Tromboembolismo pulmonar.","C":"Dissecção de carótida.","D":"Síndrome coronariana aguda."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-217683","number":"217683","sourceNumber":"217683","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente sexo feminino, 32 anos, refere que apresenta ataques de cefaleia,\npalpitações, tremores, palidez e sudorese com\nelevação da pressão arterial. Foi aventada a\nhipótese de feocromocitoma e confirmada com a dosagem elevada de metanefrinas urinárias e\ndetecção de nódulo de 2,5 cm em adrenal direita. Foi indicado adrenalectomia direita. Qual o\npreparo necessário no pré-operatório?","options":{"A":"Uso de bloqueador ?-1 adrenérgico para evitar crise hipertensiva no intraoperatório.","B":"Uso de bloqueador ?-1 adrenérgico para evitar crise hipertensiva no pós-operatório.","C":"Uso de bloqueador ß-1 adrenérgico para evitar crise hipertensiva no intraoperatório.","D":"Uso de bloqueador ?-1 e ß-1 adrenérgico para evitar crise hipertensiva no intraoperatório."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-217694","number":"217694","sourceNumber":"217694","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo masculino com 42 anos com história de nódulo tireoidiano visível à\nultrassonografia, medindo 1,5 cm, único, com microcalcificações, vascularização central maior que\nperiférica e halo incompleto. Qual é a melhor conduta?","options":{"A":"Tireoidectomia total.","B":"Observação e reposição de levotiroxina para supressão hormonal.","C":"Cintilografia de corpo inteiro com 131-iodo.","D":"PAAF e provas de função tireoidiana."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-217696","number":"217696","sourceNumber":"217696","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 43 anos foi submetida à Tireoidectomia total por nódulo suspeito de\ncarcinoma papilífero. No 1º dia de pós-operatório apresentou sintomas de parestesia de língua e\nperioral. O médico residente que está passando a visita observa que durante a conversa, a\npaciente apresenta espasmos da musculatura facial. Assinale a alternativa que corresponda ao\nprovável diagnóstico e a devida terapêutica a ser instituída.","options":{"A":"A paciente está evoluindo bem e pode receber alta.","B":"Hipoparatireoidismo. Tratar com cloreto de cálcio por via endovenosa.","C":"Pode ser um AVC. Devem ser instituídas medidas de suporte avançado de vida.","D":"Hipotireoidismo. Iniciar reposição de levotiroxina oral, imediatamente."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-183153","number":"183153","sourceNumber":"183153","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Das patologias endócrinas citadas nas alternativas abaixo, a que NÃO faz parte da\nNEM tipo 1 (Neoplasia Endócrina tipo 1) é:","options":{"A":"Acromegalia.","B":"Insulinoma.","C":"Gastrinoma.","D":"Carcinoma medular de tireoide.","E":"Hiperparatireoidismo primário."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-182629","number":"182629","sourceNumber":"182629","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente com diagnóstico de hipotireoidismo subclínico deve necessariamente ter as\nseguintes alterações nos exames de função da tireóide:","options":{"A":"T4 livre normal e TSH elevado.","B":"T4 livre baixo e TSH elevado.","C":"T4 livre baixo e TSH normal.","D":"T4 livre normal e TSH baixo."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-182633","number":"182633","sourceNumber":"182633","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente masculino, 24 anos, foi submetido à PAAF em nódulo de 2 cm em lobo direito\nda tireoide. O resultado foi \"presença de\ncélulas foliculares\". Qual a conduta?","options":{"A":"Apena observação, provavelmente trata-se de um nódulo benigno.","B":"Indicar tireoidectomia, grande possibilidade de nódulo maligno.","C":"Solicitar cintilografia de tireoide.","D":"Realizar \"core biopsy\"."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-182628","number":"182628","sourceNumber":"182628","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente feminino, 63 anos, submetida à tireoidectomia total há 30 dias por bócio\nmultinodular, refere que ao cantar durante os cultos de sua igreja sua voz \"falha\". Qual a hipótese\ndiagnóstica?","options":{"A":"Lesão do nervo laríngeo superior.","B":"Lesão unilateral do nervo recorrente.","C":"Hipoparatireoidismo.","D":"Hipotireoidismo."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-159062","number":"159062","sourceNumber":"159062","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Não se considera como causa fisiológica da hiperprolactinemia:","options":{"A":"Sono.","B":"Ovulação.","C":"Coito.","D":"Manipulação mamária."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-159126","number":"159126","sourceNumber":"159126","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Para confirmar a principal causa de hipertireoidismo primário com captação aumentada\ne difusa na tireóide de Iodo radioativo na\ncintilografia, devemos solicitar:","options":{"A":"TSH.","B":"Anti TPO.","C":"Anti microssomal.","D":"TRAB."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-159103","number":"159103","sourceNumber":"159103","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Assinale a alternativa que, na avaliação de um nódulo tireóideo por USG, reúne\nrespectivamente três sinais sugestivos de uma lesão benigna (B) e três de maligna (M):","options":{"A":"(B) Limites regulares, halo irregular, microcalcificações / (M) áreas císticas, calcificações\ngrosseiras, hipervascularização.","B":"(B) Halo presente, hipoecogênico, calcificações em \"casca de ovo\" / (M) hiperecogênico,\nvascularização periférica e microcalcificação.","C":"(B) Hiperecogênico, microcalcificações, vascularização periférica / (M) halo irregular ou\nausente,\nhipoecogênico, sólido.","D":"(B) Hiperecogênico, calcificações em \"casca de ovo\", vascularização periférica / (M)\nhipoecogênico, microcalcificações, hipervascularização."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-159112","number":"159112","sourceNumber":"159112","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A respeito das neoplasias malignas da glândula tireóide, podemos afirmar que:","options":{"A":"O carcinoma papilífero na criança, na maioria dos casos, é sintomático e se manifesta com\ndisfonia, disfagia ou massa cervical central, endurecida e fixa.","B":"O carcinoma papilífero na criança é uma doença rara, com disseminação linfonodal frequente e\ncom baixo índice de mortalidade.","C":"O diagnóstico citopatológico (PAAF) para variante de células altas do carcinoma folicular\nraramente é diagnóstico.","D":"Geralmente se manifestam ecograficamente como nódulos hiperecóicos e com acentuada\nvascularização central."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-159075","number":"159075","sourceNumber":"159075","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No 1° dia de pós-operatório de uma paciente submetida a tireoidectomia total, ela\napresenta formigamento perioral, parestesias em extremidades e sinais de Trousseau e Chvostek\npositivos. Qual o diagnóstico?","options":{"A":"Hipocalemia.","B":"Lesão do nervo laríngeo recorrente.","C":"Hipocalcemia.","D":"Lesão do nervo laríngeo superior."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-135954","number":"135954","sourceNumber":"135954","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente com aumento doloroso da tireóide, febre, calafrios, sudorese e mal estar geral.\nO exame da tireóide revela uma glândula\nextremamente sensível à palpação, modestamente\naumentada e dura como madeira, além de níveis de T4 livre e VHS aumentados no sangue. A\ncaptação de radioiodo tipicamente é menor do que 2% em 24 horas. Apresenta provavelmente o\ndiagnóstico de:","options":{"A":"Câncer de tireóide;","B":"Tireoidite de Hashimoto;","C":"Tireoidite Subaguda (de Quervain);","D":"Doença de Graves"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-108659","number":"108659","sourceNumber":"108659","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente veio encaminhada sem queixas, mas com os seguintes exames: T4 e T3 total\nelevados, T3 e T4 livre normais, antitireoglobulina e anti-TPO normais. Qual a sua impressão sobre\na paciente e possível causa?","options":{"A":"Hipertireoidismo/doença de Graves.","B":"Hipotireoidismo/tireoidite Hashimoto.","C":"Eutireoidismo/aumento da TBG.","D":"Hipertireoidismo/uso de medicamentos."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-84541","number":"84541","sourceNumber":"84541","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Neoplasia que deriva das células parafoliculares C da Tireoide. É responsável por\nmenos de 5% de todos os cânceres de\ntireoide. Pode ocorrer como um componente das síndromes\nNEM 2a ou NEM 2b. Qual o câncer de tireoide possui as características descritas acima?","options":{"A":"Carcinoma papilar.","B":"Carcinoma medular.","C":"Carcinoma anaplásico.","D":"Linfoma.","E":"Carcinoma pequenas células."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-66929","number":"66929","sourceNumber":"66929","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"CASO CLÍNICO 3 - Em uma unidade básica de saúde você atende um lactente de seis\nmeses de idade que foi levado à unidade por apresentar uma virose, febre baixa há um dia e coriza\nnasal. Durante o exame foi constatado que a criança se encontrava em bom estado geral, porém\nera hipotônica, sustentou a cabeça com cinco meses e ainda não rolava. Apresentava ainda uma\nfácies, infiltrada, mixedema, pele seca, obstipação e déficit de crescimento que foram notados pela\nmãe desde os dois meses de vida. As vacinas estavam em dia e a criança não realizou a triagem\nneonatal. Qual a MELHOR CONDUTA neste caso?","options":{"A":"Tranquilizar a mãe dizendo que se trata de uma virose e logo a criança melhora;","B":"Realizar orientações com relação ao quadro viral e investigar os demais sintomas com exames\ncomplementares: hemograma, eletrólitos, função renal e função tireoidiana;","C":"Solicitar exames: hemograma, eletrólitos e encaminhar para internação;","D":"Realizar orientações com relação ao quadro viral e encaminhar para avaliação com especialista;"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-66941","number":"66941","sourceNumber":"66941","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em uma unidade básica de saúde você atende um lactente de seis meses de idade que\nfoi levado à unidade por apresentar uma virose, febre baixa há um dia e coriza nasal. Durante o\nexame foi constatado que a criança se encontrava em bom estado geral, porém era hipotônica,\nsustentou a cabeça com cinco meses e ainda não rolava. Apresentava ainda uma fácies, infiltrada,\nmixedema, pele seca, obstipação e déficit de crescimento que foram notados pela mãe desde os\ndois meses de vida. As vacinas estavam em dia e a criança não realizou a triagem neonatal. Qual a\nhipótese diagnóstica mais provável?","options":{"A":"Desnutrição proteicocalórica.","B":"Síndrome Nefrótica.","C":"Fenilcetonúria.","D":"Hipotireoidismo congênito."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-66995","number":"66995","sourceNumber":"66995","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente com nódulo tireoidiano de 12 mm, níveis diminuídos de TSH e cintilografia\ncom área localizada de hipercaptação de\nsubstância radioativa. A conduta preferencial a ser\ntomada será:","options":{"A":"Levotiroxina;","B":"Observação e US seriados;","C":"PAAF (Punção Aspirativa com Agulha Fina);","D":"Ablação com radioiodo."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-50055","number":"50055","sourceNumber":"50055","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente feminino, 32 anos, gesta II para II, refere aumento de volume em região\ncervical anterior. Ao exame físico apresenta\ntireoide palpável, globalmente aumentada e nodular. O\nultrassom demonstrou múltiplos nódulos heterogêneos e hiperecogênicos. As dosagens de T4 livre\ne THS eram normais. Estará indicado o tratamento cirúrgico se:","options":{"A":"A dosagem de anticorpos antitireoidianos for positiva;","B":"A frequência cardíaca for superior a 120 bpm;","C":"Apresenta disfonia;","D":"Apresenta sinais de hipotireoidismo."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-37060","number":"37060","sourceNumber":"37060","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente feminina, 32 anos, gesta II para II, refere aumento de volume em região\ncervical anterior. Ao exame físico apresenta\ntireoide palpável globalmente aumentada e nodular. O\nultrassom demonstrou múltiplos nódulos heterogêneos e hiperecogênicos. As dosagens de T4 livre\ne TSH eram normais. Qual a indicação de tratamento cirúrgico?","options":{"A":"Se a dosagem de T3 for normal.","B":"Se a dosagem de anticorpos antitireoidianos for positiva.","C":"Se a frequência cardíaca for superior a 120 bpm.","D":"Se apresentar disfonia.","E":"Se apresentar sinais de hipotireoidismo."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-29384","number":"29384","sourceNumber":"29384","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No 1° dia de pós-operatório de uma paciente submetida a tireoidectomia total ela\napresenta sensação de formigamento peri-oral,\nparestesias em extremidades e sinais de Trosseau\ne Chvostek positivos. Qual a melhor conduta:","options":{"A":"reposição oral de cálcio","B":"reposição parenteral de cálcio","C":"reposição de vitamina D parenteral","D":"reposição de vitamina D por via oral","E":"reposição parenteral de cálcio e vitamina D"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-372069","number":"372069","sourceNumber":"372069","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente feminina, 32 anos, procura atendimento médico queixando de palpitações há\n60 dias. Relata que se iniciam em repouso,\nsubitamente, sem relação com esforços físicos ou\nalterações emocionais. Nega dor torácica, nega dispneia. Nega perda de consciência. Associa as\ncrises de palpitações com cefaleia importante e aumento da pressão arterial. Tem antecedentes de\ntireoidectomia total com esvaziamento cervical por câncer de tireoide na infância. Exame físico\nrealizado durante uma crise: estável hemodinamicamente, em bom estado geral, sudoreica, corada,\nhidratada, eupneica, anictérica, acianótica, afebril. Bulhas cardíacas rítmicas, taquicárdicas, sem\nsopros. Ausculta pulmonar normal. Abdome sem alterações. Cicatriz cervical prévia sem alterações\ndignas de nota. Ausência de linfonodomegalias atípicas. Pulsos cheios, amplos, simétricos.\n\nAusência de edema de membros inferiores. Foi submetida aos exames abaixo. Assinale a principal\nhipótese diagnóstica.","options":{"A":"Fibrilação atrial de alta resposta.","B":"Neoplasia endócrina múltipla.","C":"Síndrome coronariana aguda.","D":"Transtorno de ansiedade generalizada."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/372069.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-372048","number":"372048","sourceNumber":"372048","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente feminina, 32 anos, procura atendimento médico queixando de palpitações há\n60 dias. Relata que se iniciam em repouso,\nsubitamente, sem relação com esforços físicos ou\nalterações emocionais. Nega dor torácica, nega dispneia. Nega perda de consciência. Associa as\ncrises de palpitações com cefaleia importante e aumento da pressão arterial. Tem antecedentes de\ntireoidectomia total com esvaziamento cervical por câncer de tireoide na infância. Exame físico\nrealizado durante uma crise: estável hemodinamicamente, em bom estado geral, sudoreica, corada,\nhidratada, eupneica, anictérica, acianótica, afebril. Bulhas cardíacas rítmicas, taquicárdicas, sem\nsopros. Ausculta pulmonar normal. Abdome sem alterações. Cicatriz cervical prévia sem alterações\ndignas de nota. Ausência de linfonodomegalias atípicas. Pulsos cheios, amplos, simétricos.\n\nAusência de edema de membros inferiores. Foi submetida aos exames abaixo. Assinale a opção\nterapêutica mais adequada para o caso.","options":{"A":"Devido a estabilidade hemodinâmica e quadro não agudo, o objetivo é controle da frequência\ncardíaca com alfa-bloqueadores e\nanticoagulação sistêmica.","B":"Solicitar marcadores de injúria miocárdica e trombólise.","C":"Acompanhamento psicoterápico e inibidores da recaptação de serotonina.","D":"Adrenalectomia esquerda."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/372048.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-343190","number":"343190","sourceNumber":"343190","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O câncer de tireoide que acomete mulheres jovens e tem melhor prognóstico é:","options":{"A":"Carcinoma folicular","B":"Carcinoma mucoepidermoide","C":"Carcinoma papilífero","D":"Carcinoma estromal"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-315205","number":"315205","sourceNumber":"315205","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Os principais sintomas do feocromocitoma são:","options":{"A":"Bradicardia, hipotensão e tremor.","B":"Bradicardia, hipertensão e sonolência.","C":"Taquicardia, hipotensão e sonolência.","D":"Taquicardia, hipertensão e ansiedade.","E":"Bradicardia, hipotensão e ansiedade."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-275977","number":"275977","sourceNumber":"275977","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente com 55 anos de idade apresenta, ao exame físico, nódulo na tireóide de 4,5\ncm que movimenta-se à deglutição. Que exames devem ser solicitados para o diagnóstico?","options":{"A":"Ultrassonografia da tireóide e punção guiada por ultrassom.","B":"T3, T4, livre e TSH.","C":"Exames pré-operatórios de rotina e Rx de tórax.","D":"Não é necessário nenhum exame, somente acompanhamento clínico.","E":"Ultrassonografia da tireóide."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-283730","number":"283730","sourceNumber":"283730","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Indique a principal suspeita diagnóstica para o nódulo cervical.","options":{"A":"Metástase linfonodal.","B":"Carcinoma papilífero de tireoide.","C":"Cisto tireoidiano.","D":"Lipoma de subcutâneo."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/283730.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-283731","number":"283731","sourceNumber":"283731","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2 cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Determine a conduta mais adequada para confirmar o diagnóstico.","options":{"A":"Realizar tomografia computadorizada de cabeça, pescoço e tórax.","B":"Orientar a paciente que se trata de doença benigna e que não há necessidade de outro exame\ncomplementar.","C":"Realizar punção aspirativa, com agulha fina, do nódulo.","D":"Indicar exérese do nódulo."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/283731.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-283732","number":"283732","sourceNumber":"283732","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, é encaminhada ao ambulatório de cirurgia\npor apresentar nódulo palpável em região cervical\nanterior. A paciente nega comorbidades ou uso\nde medicações. Ao exame, bom estado geral, presença de nódulo palpável na topografia da\nglândula tireoide, medindo cerca de 1,2 cm no maior diâmetro. Foi realizada uma ultrassonografia\nda região cervical. Caso indicado tratamento cirúrgico para o nódulo, determine, dentre as opções\napresentadas, a principal preocupação do cirurgião nas primeiras 48 horas do pós-operatório.","options":{"A":"Infecção do sítio cirúrgico.","B":"Hipotireoidismo.","C":"Hemorragia.","D":"Hipocalcemia."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/283732.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-278116","number":"278116","sourceNumber":"278116","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O sítio mais comum de drenagem venosa da glândula adrenal esquerda é para:","options":{"A":"Veia renal.","B":"Veia gonadal esquerda.","C":"Veia ilíaca comum.","D":"Veia cava inferior."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-231376","number":"231376","sourceNumber":"231376","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente com 45 anos de idade, assintomática, apresenta no exame físico nódulo na\ntireóide medindo aproximadamente 4,0 cm de diâmetro, que se movimenta com a deglutição. Que\nexames devem ser solicitados como propedêutica de diagnóstico e estadiamento?","options":{"A":"Ultrassom da tireóide e a punção por agulha fina dirigida por ultrassom do nódulo da tireoide.","B":"T3, T4, TSH e T4Live.","C":"Exames pré-operatórios de rotina e Rx de tórax.","D":"Avaliação cardiológica de rotina pré-operatório.","E":"Não faria nenhum exame de laboratório, somente exame clínico físico."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-249418","number":"249418","sourceNumber":"249418","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 26 anos procura pronto-socorro queixando-se de forte mialgia e cãibras\nconstantes que pioraram há 1 semana. Nega febre. Nega trauma. Vem apresentando crises\nhipertensivas recorrentes, já em uso de losartana 100 mg/dia, anlodipino 10 mg/dia e bisoprolol 5\nmg/dia, sem melhora. Após coleta de rotina laboratorial em pronto-socorro foi internada por\nhipocalemia. Submeteu-se à tomografia de abdome abaixo. O provável diagnóstico é:","options":{"A":"Leptospirose.","B":"Paraganglioma.","C":"Adenoma adrenal.","D":"Hipoaldosteronismo ? NEM 1."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/249418.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-249421","number":"249421","sourceNumber":"249421","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O tratamento curativo do carcinoma medular de tireoide é a tireoidectomia importante\npara ressecção de possíveis lesões metastáticas.\nNa tireoidectomia total por carcinoma medular de\ntireoide, mesmo de forma profilática, deve-se esvaziar o nível cervical:","options":{"A":"II","B":"III","C":"V","D":"VI"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-249423","number":"249423","sourceNumber":"249423","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 56 anos procura atendimento médico ambulatorial queixando-se de diarreia\nde início há 3 meses, perda de peso,\ncalafrios e tremores sem causa aparente. Nega febre aferida.\nQueixa-se também de baixa acuidade visual. Nega alteração de hábitos rotineiros, alimentares e\nintrodução/suspensão de drogas de uso contínuo. Notou que há aumento de seu pescoço, relatado\ncomo ?inchaço?. Na investigação apresentou tireóide aumentada difusamente à palpação, níveis\nde T4 elevado, TSH suprimido e anticorpos anti-tireoideanos não detectáveis. Ecografia de tireóide\nevidenciou glândula difusamente aumentada. A cintilografia com iodo 131 evidenciou uma área\nautônoma funcional bem localizada e restante da glândula suprimida (não captante). A principal\nhipótese diagnóstica é:","options":{"A":"Doença de Plummer.","B":"Doença de Graves.","C":"Doença de Paget.","D":"Arterite de Takayasu."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-249233","number":"249233","sourceNumber":"249233","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A lesão tireoidiana que é associada a um aumento dos níveis de calcitonina é:","options":{"A":"Tireoidite de Hashimoto.","B":"Carcinoma papilífero.","C":"Carcinoma medular.","D":"Tireoidite esclerosante."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-219853","number":"219853","sourceNumber":"219853","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"VBK, 42 anos, sexo masculino, morador de rua, foi submetido a cirurgia para\ntratamento de trauma abdominal por arma\nbranca. À admissão no pronto-socorro apresentava\nhálito etílico e sinais indiscutíveis de alcoolismo crônico. No segundo dia de pós operatório\ncomeçou com tremores acompanhado de taquicardia, rubor facial e hiperreflexia. Evoluiu com\nataxia, confusão mental e oftalmoplegia. Em relação a este caso assinale a alternativa\nINCORRETA:","options":{"A":"Tem indicação de uso contínuo de benzodiazepínico.","B":"Tem risco aumentado de apresentar arritmias e isquemia miocárdica.","C":"Tem risco elevado de apresentar insuficiência suprarrenal, com diminuição dos níveis séricos e\nurinários de catecolaminas","D":"Tinha indicação do uso de tiamina na tentativa de prevenção deste quadro."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-219863","number":"219863","sourceNumber":"219863","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"FSP, sexo masculino, 47 anos, casado, eletricista, queixa-se de cefaleia, sudorese e\npalpitações que surgiram há cerca de 6 meses e que vêm se tornando mais intensas. Informa\nhipertensão arterial de difícil controle com administração de losartana e anlodipino. Ao exame,\napresentava PA de 160 x 100 mmHg e pulso de 96 bpm. Exames laboratoriais de rotina estavam\nnormais. Foi solicitada a dosagem plasmática de metanefrinas livres, que se mostrava elevada.\nProsseguindo na propedêutica foi realizada a dosagem do nível sérico de catecolaminas e seus\nmetabólitos na urina de 24 horas, ambas elevadas. Exames de imagem revelaram nódulo solitário\nem suprarrenal direita (figura abaixo), sendo indicado tratamento cirúrgico. Sobre o perioperatório\nem pacientes nesta situação, assinale alternativa INCORRETA:","options":{"A":"Deve ser realizada biópsia de congelação no peroperatório, pois o critério de malignidade é\nessencialmente histopatológico.","B":"Deve-se administrar bloqueador alfa-adrenérgico logo após estabelecido o diagnóstico.","C":"Na presença de taquicardia persistente pode-se administrar betabloqueadores após bloqueio\nalfa-adrenérgico adequado.","D":"Pode ocorrer hipotensão grave no período pós-operatório devido à vasodilatação arteriolar\nperiférica e aumento da capacitância venosa, após a remoção do tumor."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/219863.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-219874","number":"219874","sourceNumber":"219874","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"D.N.E., sexo masculino, 26 anos, mecânico, notou massa palpável na região cervical\nanterior que teve crescimento relativamente\nrápido nos últimos 2 meses, sem outros sinais ou\nsintomas. Não sabe precisar casos semelhantes na família. Exames laboratoriais de rotina estão\nnormais e dosagem de calcitonina elevada. Foram solicitados alguns exames de marcadores\ntumorais e de função tireoidiana. A PAAF com imuno-histoquímica confirmou carcinoma medular da\ntireoide. Sobre este paciente e seu tumor, assinale alternativa INCORRETA:","options":{"A":"A ausência de antecedentes familiares direciona o diagnóstico para a forma esporádica, que é\nmais rara e tem melhor prognóstico a longo prazo.","B":"As células deste tipo de tumor não concentram iodo radioativo e não são sensíveis ao hormônio\ntireoestimulante (TSH).","C":"Entre os marcadores tumorais que podem estar elevados nesta situação está o antígeno\ncarcinoembrionário (CEA).","D":"Tem indicação de tireoidectomia total com linfadenectomia (dissecção linfonodal)."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-219851","number":"219851","sourceNumber":"219851","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"FDR, 61 anos, sexo feminino, secretária aposentada, relata fraqueza muscular, fadiga,\ndepressão, náuseas e poliúria. O exame físico detectou linfonodos aumentados nas cadeias\ncervicais à esquerda. A dosagem de PTHi foi bem elevada, assim como a de cálcio (15 mg/dl).\n\nOcorreu captação significativa à cintilografia com sestamibi na região cervical anterior esquerda. A\nultrassonografia mostrou perda de planos de clivagem entre as paratireoides e a glândula tireoide,\nque estava normal. Em relação à doença desta paciente e seu tratamento cirúrgico, assinale\nalternativa INCORRETA:","options":{"A":"A abordagem cirúrgica deve envolver o tumor em bloco associado a lobectomia da tireoide\nipsilateral e tecidos moles adjacentes com suspeita de invasão.","B":"A biopsia de congelação para confirmação de malignidade não deve ser realizada antes da\nressecção em bloco.","C":"A grande maioria se deve à malignização de um adenoma.","D":"Esta paciente tem maior risco de desenvolver doença óssea ou renal associada do que os\nportadores de adenomas."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-216284","number":"216284","sourceNumber":"216284","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre o Hiperparatiroidismo Primário, é INCORRETO que","options":{"A":"a causa mais comum é a doença uniglandular, denominada Adenoma de Paratireoide.","B":"o Carcinoma de Paratireoide é raro.","C":"nas formas familiares têm maior associação com a NEM tipo 2.","D":"são manifestações clínicas: dor óssea, nefrolitíase, anorexia e depressão."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-216289","number":"216289","sourceNumber":"216289","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"São manifestações clínicas encontradas no Hiperparatiroidismo Primário, EXCETO","options":{"A":"fraqueza muscular.","B":"osteoporose.","C":"coma.","D":"hipervolemia"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-215257","number":"215257","sourceNumber":"215257","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"São causas de Hipocalcemia, EXCETO:","options":{"A":"Hiperparatiroidismo.","B":"Múltiplas transfusões sanguíneas.","C":"Pancreatite aguda.","D":"Sepse."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-215538","number":"215538","sourceNumber":"215538","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação aos nódulos tireoideanos em crianças.","options":{"A":"Cerca de70% dos nódulos tireoideanos em crianças são neoplasias malignas.","B":"De modo geral, a primeira manifestação clínica é a presença de massa tumoral no pescoço, o\nque motiva a consulta ao pediatra.","C":"Em caso de dúvida diagnóstica após a punção aspirativa, indica-se cirurgia para biópsia, com\nexame do tumor sob congelação, para que se\npossa tomar conduta no mesmo ato.","D":"A biópsia aspirativa da massa com agulha fina, para análise citológica do material obtido,\napresenta sensibilidade de apenas 20% para confirmação diagnóstica."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-219893","number":"219893","sourceNumber":"219893","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Com relação ao hipotireoidismo é INCORRETO afirmar que:","options":{"A":"A presença de lesão nodular na hipófise, aos métodos de imagem, favorece o diagnóstico de\nhipotireoidismo secundário.","B":"Hipotireoidismo subclínico é definido pelo encontro de concentrações séricas elevadas de TSH,\nna presença de concentrações séricas reduzidas\nde T4 livre e de T3.","C":"Pacientes eutireoidianos com doença sistêmica podem apresentar elevação transitória do TSH\ndurante a recuperação da doença não tireoidiana.","D":"Tireoidite crônica autoimune (tireoidite de Hashimoto) é a causa mais comum de hipotireoidismo\nprimário nas áreas onde não há deficiência de\niodo."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-181412","number":"181412","sourceNumber":"181412","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A história natural do bócio é crescimento progressivo. Os tratamentos não cirúrgicos\nsão muitas vezes imperfeitos e incompletos. A\nsupressão hormonal tireoidiana tem eficácia variável,\nespecialmente em grandes bócios. Também requer tratamento vitalício porque está associado a\ntaxas de recaída muito altas após a descontinuação, e seus efeitos podem apresentar recaída pelo\nseu descumprimento. Com relação ao bócio, é correto afirmar:","options":{"A":"o bócio subesternal suscita preocupação com a compressão progressiva das estruturas\nvasculares e das vias aéreas e torna a glândula menos acessível à vigilância. Assim, é um\nproblema comum que requer regularmente tratamento cirúrgico.","B":"o iodo radioativo normalmente está indicado na maioria dos casos e não tem relação com outras\ncomplicações, resolvendo o problema de forma diferente do tratamento cirúrgico.","C":"a história natural do bócio é de crescimento com pouco aumento do volume da glândula e,\nsendo assim, sem repercussões locais importantes.","D":"o tratamento cirúrgico não controla efetivamente os sintomas regionais, porém fornece tecido\npara análises histológicas.","E":"a avaliação pré-operatória não necessita de estudo da função da laringe e de imagem da região\ncervical."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-187820","number":"187820","sourceNumber":"187820","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação aos nódulos tireoidianos, assinale alternativa ERRADA:","options":{"A":"A malignidade de um nódulo pode ser definida com base na captação de radioisótopos","B":"A Punção Aspirativa por Agulha Fina (PAAF) não é eficiente para confirmação de câncer folicular","C":"Presença de coloiode e macrófagos dentro do aspirado -Punção Aspirativa por Agulha Fina\n(PAAF)- é altamente sugestivo de benignidade","D":"Todo paciente com nódulo tireoidiano deve ser submetido a teste da função tireoidiana"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-181408","number":"181408","sourceNumber":"181408","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino refere que há 4 meses apresenta um quadro de fraqueza,\npele seca, cabelos secos e quebradiços, rarefação\ndo terço distal das sobrancelhas, ganho de\npeso, intolerância ao frio e constipação intestinal. Em relação à principal hipótese diagnóstica,\nassinale a alternativa CORRETA.","options":{"A":"TSH suprimido associado à elevação de T4 livre.","B":"A forma secundária representa a maioria dos casos.","C":"A tireoidite de Hashimoto não é uma causa comum em nosso meio.","D":"A hipercolesterolemia e a hipertrigliceridemia são achados clássicos.","E":"Pode ocorrer em qualquer idade, mais comum em mulheres mais jovens."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-182763","number":"182763","sourceNumber":"182763","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O manejo da crise hipercalcêmica envolve medidas clínicas e cirúrgicas em caráter de\nurgência. São condutas adequadas, EXCETO","options":{"A":"hidratação com cristaloides.","B":"diuréticos de alça..","C":"bifosfonados","D":"bloqueador da angiotensina."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-183076","number":"183076","sourceNumber":"183076","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente em pós-operatório imediato de tireoidectomia total apresenta estridor laríngeo\nlogo após a extubação e insuficiência\nrespiratória. Qual é a principal hipótese diagnóstica?","options":{"A":"Lesão do nervo vago.","B":"Lesão da traqueia.","C":"Lesão da laringe.","D":"Lesão do nervo laríngeo recorrente bilateral."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-161379","number":"161379","sourceNumber":"161379","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O Hiperparatiroidismo é a terceira alteração endócrina mais comum após diabetes e\ndoença tireoidea. Assinale a alternativa CORRETA\nem relação ao metabolismo do cálcio.","options":{"A":"São diagnósticos diferenciais de hipercalcemia-hiperparatiroidismo primário, tireotoxicose,\ninsuficiência adrenal aguda, feocromocitoma, tumores,\nhistoplasmose, sarcoidose, hanseníase,\nmedicamentos como diuréticos tiazídicos e lítio, nutrição parenteral.","B":"Para o manejo da crise hipercalcêmica é indicado hiper-hidratação com solução salina\nhipertônica e diuréticos de alça.","C":"As manifestações clínicas mais comuns do hiperparatiroidismo são adormecimento perioral,\ntremores, ansiedade, confusão mental, alcalose respiratória, tetania, convulsões.","D":"Os bifosfonados apresentam ação rápida (24 à 48h) para reduzir os níveis séricos de cálcio,\nsendo mais efetivas quando associados aos glicorticoides e tem atividade potente contra os\nosteoclastos, em média, por 1 semana."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-161403","number":"161403","sourceNumber":"161403","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"As glândulas adrenais foram primeiramente descritas pelo anatomista italiano\nBartolomeo Eustachi em 1563. Thomas Addison\ndescreveu as características clínicas da\ninsuficiência adrenal primária em 1855, somente quase um século mais tarde os hormônios\nadrenais foram totalmente isolados e caracterizados. Sobre a Insuficiência Adrenal, marque a\nopção CORRETA.","options":{"A":"A Insuficiência Adrenal Primária se apresenta com fraqueza, fadiga, anorexia, náuseas ou\nvômitos, perda de peso, hiperpigmentação, hipotensão, hipernatremia e hipocalemia.","B":"A Insuficiência Adrenal Secundária é um distúrbio relativamente comum, resultante da\ndeficiência do ACTH e muitas vezes causada pela\nretirada de esteroides farmacológicos. Outras\ncausas menos comuns incluem o pan-hipopituitarismo secundário à lesão neoplásica, doenças\ngranulomatosas e hemorragia ou infarto hipofisário.","C":"A Insuficiência Adrenal Aguda, ou crise adrenal, é uma condição potencialmente fatal, os\nachados clínicos incluem dor abdominal,\nchoque, febre, náuseas, hipoglicemia. A Síndrome de\nWaterhouse-Friederichsen é caracterizada pelo infarto adrenal em casos de hemorragia puerperal\ngrave.","D":"O diagnóstico se baseia na concentração de cortisol sérico matinal maior que 15 µg/dL ou\nconcentração salivar de cortisol maior que 5,8 µg/dL."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-161408","number":"161408","sourceNumber":"161408","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No Hiperaldosteronismo Primário ocorre a liberação desregulada de aldosterona, de\numa ou ambas glândulas adrenais. Indique a\nalternativa INCORRETA.","options":{"A":"O hiperaldosteronismo primário apresenta-se classicamente por hipercalemia e hipertensão\narterial resistente.","B":"As causas mais comuns de hiperaldosteronismo primário são adenomas unilaterais produtores\nde aldosterona e hiperplasia adrenal bilateral.","C":"Uma boa resposta à espironolactona é considerada uma característica preditiva de boa resposta\nao tratamento cirúrgico.","D":"As taxas de cura globais pós-tratamento cirúrgico variam de 75 a 95%."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-161339","number":"161339","sourceNumber":"161339","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Durante a primeira metade do século XX, a taxa de mortalidade perioperatória no\ntratamento do feocromocitoma variava de 26\na 50%. Atualmente, a taxa de mortalidade em centros\nespecializados é de aproximadamente 1%. Em relação aos cuidados operatórios nos pacientes\nportadores de feocromocitoma, assinale a alternativa INCORRETA:","options":{"A":"As alterações hemodinâmicas adversas mais comuns são hipertensão intraoperatória e\nhipotensão pós-operatória.","B":"Entre os princípios dos cuidados perioperatórios está o bloqueio alfa-adrenérgico por pelo menos\nduas semanas.","C":"Os betabloqueadores podem ser utilizados como monoterapia para os pacientes com taquicardia\npersistente.","D":"A expansão do volume pré-operatório com fluidos isotônicos é reduzida significativamente\nquando o bloqueio alfa pré-operatório é atingido."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-161298","number":"161298","sourceNumber":"161298","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre as alterações nos níveis de hormônios tireoidianos na doença aguda grave,\nassinale a alternativa INCORRETA.","options":{"A":"Na fase aguda da doença, os níveis de T3 e de T3 livre diminuem as concentrações\nextremamente baixas.","B":"A diminuição nos níveis circulantes de T3 resulta de um aumento na conversão de T3 para T4,\nao passo que a depuração do T3 permanece preservada.","C":"Em contraste com os baixos níveis de T3, os níveis de rT3 aumentam na fase aguda da doença\ndevido à redução na depuração e a um aumento na atividade da via deiodinase iodotironina tipo III.","D":"Durante a fase tardia da doença grave, a secreção hipofisária de TSH está diminuída, com o\ndeclínio concomitante das concentrações séricas de T4."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-161334","number":"161334","sourceNumber":"161334","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Os efeitos adversos dos corticosteroides surgem por uso prolongado e/ou doses\nelevadas, ou seja, são doses dependentes. Entre os principais efeitos adversos destacam-se,\nEXCETO:","options":{"A":"o ganho de peso.","B":"a hipotensão arterial.","C":"a osteoporose.","D":"a miopatia aguda."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-161376","number":"161376","sourceNumber":"161376","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A dexametasona tem potente atividade glicocorticoide com mínima a nenhuma\natividade mineralocorticoide. Além disso, ela é\nresponsável por todas as ações a seguir, com\nEXCEÇÃO de:","options":{"A":"estabilizar membranas celulares e lisossomais.","B":"aumentar a síntese de surfactante.","C":"Melhorar a imunidade em altas doses.","D":"Inibir prostaglandinas e citocinas pró-inflamatórias."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-134837","number":"134837","sourceNumber":"134837","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Durante tratamento de tireotoxicose, qual medicação poderá ser utilizada para diminuir\na conversão de T4 a T3 na periferia?","options":{"A":"IECA.","B":"Propranolol.","C":"Anlodipina.","D":"Furosemida."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-131415","number":"131415","sourceNumber":"131415","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente com 45 anos de idade, sem queixas clinicas, vai ao especialista, este, ao\nexaminar o pescoço da paciente, detecta uma nodulação na topografia da tireoide, medindo\nclinicamente aproximadamente 3,0 cm de diâmetro, que se movimenta com a deglutição. Responda\nà questão abaixo, com uma alternativa certa. Ao examinar a paciente, você confirma os achados do\nexame clínico descritos acima. Em termos de exames laboratoriais para uma propedêutica de\nestadiamento e diagnóstico, da patologia, quais os exames que você solicitaria?","options":{"A":"Ultrassom cervical e da tireoide com Doppler colorido, mais a punção por agulha fina dirigida por\nultrassom do nódulo da tireoide.","B":"T3, T4, TSH e T4 livre.","C":"Exames pré-operatórios de rotina e Rx de tórax.","D":"Avaliação cardiológica de rotina.","E":"Não faria nenhum exame de laboratório, somente exame clínico físico."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-131325","number":"131325","sourceNumber":"131325","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente com 45 anos de idade, sem queixas clinicas, vai ao especialista. Este, ao\nexaminar o pescoço da paciente, detecta uma nodulação na topografia da tireoide medindo\nclinicamente, aproximadamente, 3,0 cm de diâmetro, que se movimenta com a deglutição.\n\nResponda a questão abaixo com uma alternativa certa. Caso se realizasse a punção e o resultado\nfosse carcinoma papilar da tireoide, como deve\nser tratado?","options":{"A":"Realizaria tireoidectomia parcial.","B":"Realizaria lobectomia mais istmectomia.","C":"Realizaria tireoidectomia total.","D":"Realizaria tireoidectomia total mais esvaziamento cervical níveis II, III e IV, ipsilateral.","E":"Acompanharia com ultrassons seriados."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-109972","number":"109972","sourceNumber":"109972","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em qual dos tipos de carcinomas citados abaixo, o carcinoma papilífero pode se\ntransformar?","options":{"A":"Medular.","B":"Linfocítico.","C":"Hürtle.","D":"Anaplásico."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-110550","number":"110550","sourceNumber":"110550","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente com 60 anos de idade, vai ao médico para avaliação de rotina. Esse,\nao examinar fisicamente a paciente, detecta uma\nnodulação, medindo aproximadamente 5,0\ncm, que se movimenta ao deglutir. Responda às questões abaixo com uma alternativa certa.\nQuais os exames que devem ser solicitados para o diagnóstico correto?","options":{"A":"Ultrassom e a punção por ultrassom.","B":"T3, T4, TSH e T4Live.","C":"Exames pré-operatórios de rotina e RX de tórax.","D":"Avaliação cardiológica de rotina.","E":"Ultrassom e a punção sem ultrassom."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-110577","number":"110577","sourceNumber":"110577","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente com 60 anos de idade, vai ao médico para avaliação de rotina. Esse\nao examinar fisicamente a paciente, detecta uma\nnodulação, medindo aproximadamente 5,0\ncm, que se movimenta ao deglutir. Responda às questões abaixo com uma alternativa certa.\nApós a análise dos resultados de exames na paciente acima, concluído o diagnóstico de\ncarcinoma papilar, qual a conduta?","options":{"A":"Tireoidectomia parcial.","B":"Lobectomia mais istmectomia.","C":"Tireoidectomia total podendo optar também com esvaziamento profilático central.","D":"Tireoidectomia total mais esvaziamento jugular profilático.","E":"Seguiria com ultrassons mensalmente."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-86682","number":"86682","sourceNumber":"86682","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Analise as afirmativas abaixo e marque a alternativa que melhor define o quadro de\ncrise tireotóxica. I ? TSH suprimido, T4 livre\nbastante elevado, taquicardia, hipertensão, dor\nabdominal e sudorese excessiva. II ? TSH elevado, T4 livre diminuído, taquiarritmia, febre,\ntaquicardia, e febre. III ? disfunção termorregulatória grave, alteração de estado mental,\nevidências\nde disfunção de múltiplos órgãos, crise adrenérgica, hipermotilidade intestinal.","options":{"A":"Somente afirmativa I está correta.","B":"Somente afirmativa II está correta.","C":"Somente afirmativa II e III estão corretas.","D":"Somente afirmativa III está correta.","E":"Todas as afirmativas estão erradas."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-86794","number":"86794","sourceNumber":"86794","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"As intoxicações agudas Exógenas são situações em que todo Médico de Família e\nComunidade deve estar preparado para atuar. No caso de intoxicação aguda por uso de\nbetabloqueadores, qual é o antídoto para esta condição?","options":{"A":"Flumazenil;","B":"Glucagon;","C":"Bicarbonato de Cálcio;","D":"Atropina;","E":"N-acetilcisteína"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-86681","number":"86681","sourceNumber":"86681","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo masculino apresenta nódulo tireóideo único, de aproximadamente 2\ncm, acompanhado por adenomegalia cervical, ipsilateral. Calcitonina normal. Qual dos diagnósticos\nabaixo é o mais compatível?","options":{"A":"Adenocarcinoma papilífero.","B":"Adenocarcinoma folicular.","C":"Adenocarcinoma medular.","D":"Adenocarcinoma anaplásico.","E":"Metástase em tireoide."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-158411","number":"158411","sourceNumber":"158411","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Homem de 43 anos vem com queixa de anorexia, náusea, perda de 8 kg e fadiga\nintensa há 2 anos. Refere tratamento para\ntuberculose pulmonar há 5 anos com esquema tríplice\npor 6 meses. Exame clínico: letárgico; PA = 90 x 50 mmHg; FC = 98 bpm; peso = 63 kg (IMC = 21\nkg/m²) com hiperpigmentação cutânea e em mucosa oral. Exames laboratoriais: hemoglobina =\n10,2 g/dl; sódio = 129 mEq/L; potássio = 5,7 mEq/L; creatinina = 0,9 mg/dl; ureia = 60 mg/dl;\nalbumina = 3,1 g/dl. Qual a principal hipótese diagnóstica?","options":{"A":"Hipotireoidismo.","B":"Síndrome de Cushing.","C":"Insuficiência Adrenal.","D":"Tuberculose miliar.","E":"Paracoccidioidomicose."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-158437","number":"158437","sourceNumber":"158437","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um recém-nascido foi convocado ao serviço médico por apresentar teste do pezinho\nalterado. O exame mostra TSH = 30 ?g/ml. Qual a conduta indicada?","options":{"A":"Iniciar imediatamente tratamento de reposição hormonal com tiroxina.","B":"Repetir teste do pezinho e reavaliar clinicamente em 1 semana.","C":"Dosar TSH sérico e reavaliar clinicamente em 1 semana.","D":"Dosar T4 sérico e reavaliar clinicamente em 1 semana.","E":"Dosar TSH sérico e iniciar tratamento com tiroxina enquanto aguarda o resultado."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-362478","number":"362478","sourceNumber":"362478","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 34 anos, sexo feminino, apresentou-se ao Departamento de Emergência\ncom confusão mental, letargia e episódios de\nsíncope ao permanecer de pé. Ela também teve\nepisódios de vômitos ao longo do dia. Glicemia capilar mensurada na entrada do Hospital era de\n55mg/dl, porém seu estado mental não melhorou após administração de glicose hipertônica EV\n(endovenosa) em bolus. Recentemente ficou sem usar certas medicações das quais fazia uso\ncrônico e não conseguia lembrar de nada da sua história patológica pregressa. Pa: 80/40mmhg\napesar do uso de 2 litros de solução isotônica EV, Fc: 80bpm, Fr: 12 ipm, Tax: 38,2ºc e saturação\nde O2 de 99% em ar ambiente. Sem rigidez de nuca. A pele das palmas das mãos e da mucosa\nbucal se mostravam escurecidas. Laboratório: Na+:128mmol/l, K+:5,8mmol/l, Cl:96mmol/l,\nBicarbonato: 20mmol/l, Glicose: 120mg/dl, Ca++: 10,4mg/dl, U: 38mg/dl, Cr: 1mg/dl. A análise de\nlíquido cefalorraquidiano após punção lombar revelou: WBC:03/mm³ (<5), RBC: 0/mm³ (0),\nProteínas: 30mg/dl (15- 45) e Glicose:75mg/dl (40-80). Qual a terapêutica poderia ser iniciada nesta\npaciente precocemente?","options":{"A":"Difenidramina.","B":"Hidrocortisona.","C":"Vancomicina.","D":"Propiltiouracil."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-362477","number":"362477","sourceNumber":"362477","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, sexo feminino, 36 anos de idade, recebeu diagnóstico de Doença de Graves\nhá dois anos. Na ocasião, apresentava\norbitopatia de Graves, proptose unilateral, bócio difuso,\ntaquicardia e tremor de extremidades. O laboratório revelava TSH suprimido e T4 livre três vezes o\nlimite superior da normalidade. Foi optado por iniciar tratamento com metimazol. Durante os últimos\n18 meses, a paciente vem em desmame da tionamida e, atualmente, está em uso de 5 mg/dia. Os\núltimos exames demonstraram função tireoidiana normal e TRAb 12,0 UI/L (VR: < 1,75). US de\ntireoide: glândula heterogênea, com volume total de 32,7 mL. Tabagista há oito anos; nega etilismo.\nAo exame: eupneica, FC 75 bpm e PA: 120 x 80 mmHg. Tireoide: bócio difuso. Ausculta cardíaca e\npulmonar sem alterações. Olhos: presença de orbitopatia de Graves, sem sinais de atividade,\nproptose unilateral. Em relação ao caso clínico, assinale a alternativa CORRETA:","options":{"A":"As tionamidas inibem a captação de iodo pela tireoide e afetam a liberação dos hormônios já\nsintetizados e estocados dentro da glândula.","B":"A paciente apresenta TRAb em títulos baixos, portanto, o uso do metimazol deve ser suspenso\ndevido à alta possibilidade de cura.","C":"A realização da tireoidectomia total levaria à resolução da doença de base, contribuindo para\nredução dos níveis do TRAb.","D":"A exoftalmia na Doença de Graves é unilateral em 10% dos casos e no contexto de um quadro\nclássico de hipertireoidismo torna- se desnecessário o diagnóstico diferencial com outras\npatologias."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-362476","number":"362476","sourceNumber":"362476","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 55 anos de idade, em amenorreia há 2 anos, foi encaminhada pelo clínico ao\nambulatório de endocrinologia por alteração da função tireoidiana e perda de campo visual.\n\nApresentava TSH 0,85 mUI/mL (VR: 0,4 a 4,0) e T4 livre 0,55 ng/dL (VR: 0,9 a 1,8). Foram\nsolicitados então os seguintes exames: T4\nlivre: 0,72 ng/dL TSH: 0,94 mUI/mL; FSH: 2,5 mUI/mL\n(VR: 3,6 a 16,6); LH: 2,0 mUI/mL (VR: 1,1 a 11,1); Cortisol: 7,0 mcg/dL (VR: 5,0 a 25); ACTH: 13,1\n\npg/mL (VR: < 46); IGF-1: 62 ng/mL (VR: 83 a 241); Prolactina: 88 ng/dL (VR: 5 a 25). Prosseguindo\na investigação, a ressonância magnética da sela\ntúrcica evidenciou lesão hipofisária de 4,0 x 2,5 x\n2,9 cm em região selar compatível com adenoma hipofisário. Assinale a alternativa CORRETA\nsobre o caso acima:","options":{"A":"A dosagem de prolactina diluída é obrigatória neste caso para a exclusão do efeito gancho.","B":"Trata-se de um caso de amenorreia secundária, quando há ausência de menstruação por 4\nmeses consecutivos ou mais em mulheres que já tenham menstruado previamente.","C":"A paciente apresenta macroprolactinemia e deve ser encaminhada para tratamento cirúrgico.","D":"Podemos excluir o diagnóstico de hipotireoidismo devido aos níveis normais de TSH."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-327237","number":"327237","sourceNumber":"327237","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre a avaliação por imagem de nódulo de Tireoide (NT), assinale a alternativa\nCORRETA:","options":{"A":"Ao diagnosticar um NT menor de 1,0cm em exame ultrassonográfico de rotina, deve-se\nprosseguir investigação com tomografia computadorizada\ncervical, uma vez que esta possibilita\nmelhor caracterização do nódulo quando comparada a ultrassonografia.","B":"Diante de paciente com NT no qual se observam níveis supressos de TSH, a recomendação é\nseguir investigação com cintilografia de tireoide.","C":"Os achados ultrassonográficos de NT associados a maior risco de malignidade incluem:\nhipoecogenicidade, bordas irregulares, diâmetro transverso maior que anteroposterior e presença\nde macrocalcificações.","D":"A tomografia por emissão de pósitrons é superior a tomografia computadorizada, ressonância\nnuclear magnética e cintilografia na avaliação de\nNT."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-327238","number":"327238","sourceNumber":"327238","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A hiperprolactinemia pode ser resultado de causas fisiológicas, farmacológicas e\npatológicas. Dessa forma, as alternativas a seguir figuram como possíveis causas de\nhiperprolactinemia, EXCETO:","options":{"A":"Hipertireoidismo","B":"Cirrose hepática","C":"Herpes zoster acometendo parede torácica","D":"Uso de domperidona e metoclopramida"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-327293","number":"327293","sourceNumber":"327293","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Recém-nascido apresenta ambiguidade genital caracterizada por hipospádia e\ncriptorquidia. O nível sérico de 17 hidroxiprogesterona encontra-se elevado. Qual a principal\ncomplicação?","options":{"A":"Infecção urinaria","B":"Esterilidade","C":"Distúrbio hidroeletrolítico Sódio e Potássio","D":"Malformação renal"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-298200","number":"298200","sourceNumber":"298200","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre o tratamento do hipertireoidismo, é CORRETO afirmar:","options":{"A":"O metimazol age inibindo a liberação de hormônios tireoidianos já sintetizados e estocados na\ntireoide; com isso, seu efeito terapêutico é mais rápido que o propiltiouracil, o que faz com que\nseja\na droga de escolha para tratamento do hipertireoidismo.","B":"No paciente em uso de metimazol que evolui com agranulocitose, a recomendação é a troca\nimediata da medicação pelo propiltiouracil.","C":"Na paciente com doença de Graves que engravida, a recomendação é suspender a tionamida\nem uso e submeter a paciente a terapia com\nI131, com o intuito de promover a remissão da doença\nde forma mais precoce possível.","D":"Por ser administrado por via oral, o iodo radioativo é considerado um método de fácil execução,\npodendo até mesmo ser empregado como\nterapia inicial nos pacientes com hipertireoidismo."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-286722","number":"286722","sourceNumber":"286722","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, vem à consulta porque palpou nodulação na\nregião anterior do pescoço. Nega dor local,\ndisfagia e disfonia. Nega histórico de neoplasias na\nfamília e de doenças cervicais prévias, porém refere discreta perda de peso e fadiga progressiva há\ncerca de 1 ano. Ao exame físico, a paciente apresenta-se ansiosa, emagrecida, taquicárdica e\nhipertensa. Apresenta pequeno nódulo sólido palpável em lobo direito da tireoide, que é móvel à\ndeglutição. Não há linfadenomegalia cervical palpável. Solicitada a dosagem dos hormônios\ntireoidianos, observou-se elevados níveis de T3 e T4 livre e baixos níveis de TSH. Sobre a\ncondução deste caso, assinale a alternativa CORRETA:","options":{"A":"Os dados acima nos permitem afirmar que a ultrassonografia provavelmente evidenciará nódulo\nhipoecogênico de margens irregulares com microcalcificações, confirmando a tireoidectomia total\ncomo próximo passo na conduta desta paciente.","B":"Caso a cintilografia confirme nodulação hipercaptante com tireoide hipocaptante, a lobectomia\ntireoidiana seria opção terapêutica adequada para o caso.","C":"A Punção Aspirativa por Agulha Fina (PAAF) guiada por ultrassom é contraindicada no caso\ndevido a possibilidade de carcinoma medular.","D":"A ressonância magnética cervical deve substituir a ultrassonografia neste caso, já que evidencia\ncom maior acurácia o envolvimento da\ntraqueia e esôfago na doença, além de apresentar maior\nsensibilidade para diagnósticos diferenciais."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-252210","number":"252210","sourceNumber":"252210","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação ao tratamento da doença de Graves, assinale a alternativa INCORRETA:","options":{"A":"Nos casos de doença de Graves associada a nódulos suspeitos, a tireoidectomia deve ser\nindicada como tratamento.","B":"A agranulocitose é um raro efeito colateral e está relacionada tanto ao propiltiouracil quanto ao\nmetimazol.","C":"As tionamidas utilizadas no tratamento da doença de Graves podem apresentar reações\nalérgicas de forma cruzada.","D":"No tratamento da doença de Graves, a indicação para o emprego terapêutico do iodo 131 deve\nsempre ser precedido do preparo prévio do paciente com betabloqueador e tionamidas."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-252213","number":"252213","sourceNumber":"252213","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"São considerados sinais e sintomas devido as alterações cardiovasculares do\nhipertireoidismo:","options":{"A":"Palpitações e dor torácica tipicamente muscular.","B":"Dispnéia e edema periférico.","C":"Bradicardia e dispneia.","D":"Bradicardia e hipertensão diastólica."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-256587","number":"256587","sourceNumber":"256587","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Qual das alternativas abaixo NÃO é considerada de alto risco para malignidade em\npacientes com nódulos tireoidianos diagnosticados ao ultrassom?","options":{"A":"Passado de exposição à radiação na infância ou adolescência.","B":"Nódulo sólido-cístico.","C":"Nódulo incidentalmente detectado no FDG-PET (captação focal).","D":"História familiar de câncer de tireoide."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-252227","number":"252227","sourceNumber":"252227","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No diagnóstico precoce do câncer de tireoide é importante a avaliação do nódulo\ntireoidiano de forma a estabelecer riscos. Para tal, devem ser utilizados métodos que sejam\nacurados, precisos, seguros e de baixo custo. Sabendo disso, qual o método que melhor se\nencaixa nessas características?","options":{"A":"Punção aspirativa por agulha fina (PAAF) do nódulo.","B":"Captação e cintilografia da tireoide com radioisótopo.","C":"Ultrassonografia de tireoide.","D":"Dosagem de TSH, calcitonina e tireoglobulina séricas."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-252230","number":"252230","sourceNumber":"252230","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente feminino, 32 anos, solteira, natural e procedente de Manacapuru. Há 3 meses\nem exames de controle com a ginecologista\nrealizou ultrassonografia de tireoide que evidenciou no\nlobo direito um nódulo de 1,2 cm, hipoecoico, bordas regulares, limites precisos, sem\nmicrocalcificação, vascularização apenas periférica (CHAMMAS II). Ao exame físico: PESCOÇO:\ntireoide não palpável e sem linfonodomegalia. Realizou a punção guiada por ultrassom e teve o\nresultado da citologia de Bethesda I. Qual o próximo passo?","options":{"A":"Repetir a punção da tireoide em 3 meses.","B":"Tireoidectomia total.","C":"Tireoidectomia parcial.","D":"Iodoterapia com 100 mCi."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-208453","number":"208453","sourceNumber":"208453","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação ao hipertireoidismo, assinale a resposta INCORRETA.","options":{"A":"A investigação do hipertireoidismo em idosos que apresentam Fibrilação Atrial (FA) sempre se\nfaz necessária ao diagnóstico diferencial, pelo fato de bócios nodulares tóxicos ocorrerem com\nrelativa frequência nessa faixa etária da população.","B":"A tireoidectomia total na doença de Graves é reservada aos casos que se associam a nódulos\nda tireoide ou na presença de exoftalmia\nacentuada.","C":"Na grávida com hipertireoidismo, a decisão pela droga de escolha sempre recai pelo metimazol,\nindependentemente do período gestacional, pois é a droga mais segura para a condição, pelo fato\nde não transpor a barreira transplacentária.","D":"Na exoftalmia decorrente da doença de Graves, são encontrados infiltrados de\nglicosaminoglicanos ou mucopolissacarídeos na\nmusculatura extrínseca do olho devido a ativação\nde fibroblastos, e consequente espessamento dessa musculatura."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-176061","number":"176061","sourceNumber":"176061","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Feminino, 50 anos, chega à consulta muito ansiosa devido a ?massa no pescoço?.\nHistórico familiar de irmão com câncer de tireoide. À palpação, nota-se nodulação em região\ncervical esquerda, de mais ou menos 2,0 cm, discretamente endurecida, móvel, indolor. Traz\ndosagem TSH = 0,11 (VR = 0,5-4,5 mUI/L) e T4 livre = 1,7 ng/dl (VR = 0,7-1,5 ng/dl). Qual o\npróximo passo na avaliação desta paciente?","options":{"A":"Solicitação de cintilografia de tireoide.","B":"Dosagem de tireoglobulina e calcitonina.","C":"Solicitação de Punção Aspirativa por Agulha Fina (PAAF) do nódulo.","D":"Solicitação de ultrassonografia de tireoide."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-176065","number":"176065","sourceNumber":"176065","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Feminino, 43 anos, submetida a tireoidectomia total devido bócio multinodular atóxico,\nevoluindo no pós-operatório imediato com astenia, cãibras musculares, parestesias, mialgia. Qual a\nprovável causa do quadro clínico apresentado?","options":{"A":"Hiperparatireoidismo pós-cirúrgico.","B":"Hipoparatireoidismo pós-cirúrgico.","C":"Hipotireoidismo pós-cirúrgico.","D":"Hipertireoidismo pós-cirúrgico."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-176082","number":"176082","sourceNumber":"176082","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mãe relata que criança do sexo feminino tem 6 meses de idade e está em sua primeira\nconsulta com pediatra, nunca realizou exames e vacinas, nasceu com peso e altura normais, porém\nficou ??amarelinho?? por quase dois meses, dificuldade para alimentar, sonolência e engasgos\ndurante alimentação já presente no primeiro mês de vida. Ao exame físico: língua espessa,\nhipotonia, hérnia umbilical, bradicardia, pele seca, atraso no desenvolvimento neuropsicomotor, não\nsustenta a cabeça, pega objetos, e não sorri quando estimulado. Diante deste caso, qual a\npatologia a ser investigada?","options":{"A":"Infecção congênita.","B":"Fenilcetonúria.","C":"Hipotireoidismo.","D":"Doença de xarope de bordo (MSUD)."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-151950","number":"151950","sourceNumber":"151950","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 57 anos foi internada para investigação de ascite referida há mais de seis\nmeses. Após avaliação clínica e depois de vários exames complementares, foram evidenciadas\nalterações nos exames de tireoide, com elevação de TSH e redução nos níveis de T4 e T3,\ncaracterizando ascite mixedematosa, manifestação incomum de apresentação clínica. Das\nmanifestações clínicas descritas abaixo, assinale a que não está ligada ao hipotireoidismo:","options":{"A":"Bradicardia, derrame pericárdico e redução no débito cardíaco.","B":"Anorexia, absorção intestinal aumentada devido à constipação intestinal.","C":"Hiporreflexia profunda, parestesias e alopecia.","D":"Ataxia cerebelar, depressão e apneia do sono."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-151957","number":"151957","sourceNumber":"151957","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Adolescente de 14 anos, sexo feminino, procura o Ambulatório Araújo Lima com história\nde perda de peso, apetite voraz, tremor dos\ndedos, aceleração na velocidade do crescimento,\nchora com facilidade devido labilidade emocional, tem sono agitado, os trabalhos escolares estão\nprejudicados pelo deficit de atenção e pouco sono. Ao exame físico, apresenta exoftalmia leve,\nretração de pálpebras, acuidade visual diminuída, pele lisa ruborizada, suor excessivo, taquicardia\ne palpitações. O diagnóstico provável:","options":{"A":"Transtorno de conversão.","B":"Hipertireoidismo.","C":"Tumor cerebral.","D":"Bulimia."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-152010","number":"152010","sourceNumber":"152010","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Recém-nascido, no 10º dia de vida, sexo masculino, nascido de parto a termo, pesando\n\n= 3.500 g, evolui com perda progressiva de peso, vômito, desidratação, fraqueza, hipotensão,\nhipoglicemia, hiponatremia, hipercalemia e\nhemograma sem alterações. Ausculta pulmonar:\nmurmúrio vesicular fisiológico, sem ruídos adventícios; FR = 48 irpm. Ausculta cardíaca: RCR 2T\nBNF. Abdome sem visceromegalia. O diagnóstico provável é:","options":{"A":"Hiperplasia adrenal congênita.","B":"Estenose hipertrófica do piloro.","C":"Refluxo gastroesofágico.","D":"Sepse neonatal."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-129769","number":"129769","sourceNumber":"129769","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No hiperparatireoidismo primário encontramos:","options":{"A":"Níveis aumentados de cálcio associado a níveis aumentados ou inapropriadamente normais do\nhormônio paratireóideo (PTH).","B":"Níveis aumentados de hormônio paratireóideo (PTH) e níveis baixos de cálcio sérico.","C":"Níveis baixos de hormônio paratireóideo (PTH) associado a níveis baixos de cálcio.","D":"Níveis baixos de hormônio paratireóideo (PTH) associado a níveis elevados de cálcio sérico."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-107780","number":"107780","sourceNumber":"107780","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação aos nódulos de tireoide, marque a afirmativa CORRETA:","options":{"A":"Os nódulos de tireoide incidem em maior frequência em homens, jovens, pessoas expostas à\nradiação ionizante ou oriundos de áreas endêmicas de excesso de iodo.","B":"Sintomas compressivos, hemorragias ou extensão intratorácica só acontecem nos nódulos\nmalignos.","C":"A maioria é assintomático, porém podem apresentar disfunções associadas como\nhipertireoidismo e hipotireoidismo.","D":"Presença de múltiplos nódulos é considerado fator preditivo de benignidade."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-107922","number":"107922","sourceNumber":"107922","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino, 20 anos, vem ao consultório queixando-se de pequena\nnodulação palpável, de cerca de 12 mm e\nconsistência firme, em região anterior do pescoço, em\ntopografia do lobo esquerdo da tireoide. A paciente nega dor, disfonia, disfagia e dispneia. Refere\nque uma tia apresentou quadro semelhante (diagnóstico ignorado pela paciente) com necessidade\nde tratamento cirúrgico. O médico que a examinou observou, ainda, linfonodo palpável em cadeia\ncervical esquerda. Analise as assertivas abaixo e assinale a alternativa CORRETA:\n\nI. O TSH sérico de valor normal não exclui a possibilidade de doença maligna;\n\nII. Já que não há queixa clínica de alerta (dor, disfagia, dispneia e disfonia), podemos afirmar\nque a\nmelhor conduta para o caso seria observação clínica sem maior investigação complementar;\n\nIII. A ultrassonografia da tireoide com Doppler tem maior sensibilidade para suspeita de\nmalignidade que a ressonância magnética cervical;\n\nIV. A Punção Aspirativa por Agulha Fina (PAAF), tanto do nódulo quanto do linfonodo, é o método\npadrão-ouro para o diagnóstico da possível malignidade do caso acima.","options":{"A":"Há apenas uma assertiva incorreta.","B":"Há apenas uma assertiva correta.","C":"As assertivas II e III são incorretas.","D":"As assertivas II e IV são corretas."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-80958","number":"80958","sourceNumber":"80958","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Doença de Graves, a forma mais comum de hipertireoidismo, quando acomete\nmulheres grávidas apresenta características e\ncuidados específicos. Assinale abaixo a resposta\nINCORRETA:","options":{"A":"A crise tireotóxica, decorrente do hipertireoidismo na gravidez, exige cuidados intensivos devido\nà extrema gravidade.","B":"O Propranolol pode ser usado, porém em baixas doses e por um curto período de tempo, para\nevitar efeitos prolongados sobre o feto, como bradicardia ou retardo de crescimento intrauterino.","C":"Propiltiouracil não deve ser indicado para o tratamento no primeiro trimestre, devido ao risco de\nembriopatia acentuada.","D":"A administração de Iodo 131, como forma definitiva de tratamento do hipertireoidismo, é\ncontraindicada durante a gravidez.","E":"hipertireoidismo materno não tratado pode causar prematuridade, baixo peso para a idade\ngestacional, retardo do crescimento intrauterino e aumento da morbimortalidade perinatal."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-61554","number":"61554","sourceNumber":"61554","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No Hipertireoidismo, assinale a alternativa ERRADA:","options":{"A":"A arritmia frequentemente encontrada é a Fibrilação Atrial.","B":"A terapia com Iodo 131 pode ser indicada na Doença de Graves e nos Adenomas tóxicos.","C":"Na presença de TSH suprimido e nódulo tireoidiano solitário, a cintilografia da tireoide deve ser\nefetuada.","D":"O Metimazol deve ser a droga de escolha no tratamento do hipertireoidismo grave ou\ntempestade tireoidiana, visto que em altas doses inibe a conversão de T4 para T3.","E":"Algumas alterações hematológicas e químicas são frequentes, como a leucopenia,\nhipercalciúria, hipercalcemia, hiperbilirrubinemia e redução do colesterol total."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-61480","number":"61480","sourceNumber":"61480","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação à avaliação do risco de malignidade dos nódulos de tireoide, são suspeitos,\nEXCETO:","options":{"A":"Nódulo de crescimento lento.","B":"Adenomegalia regional ipsilateral.","C":"Fixação a estruturas endurecidas.","D":"Paralisia de corda vocal ipsilateral.","E":"História familiar de câncer de tireoide ou neoplasia endócrina múltipla."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-49805","number":"49805","sourceNumber":"49805","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Taquicardia, arritmia, sudorese, pele quente, intolerância ao calor, emagrecimento,\nexoftalmia são achados frequentes em:","options":{"A":"Feocromocitoma;","B":"Sindrome de Sheehan;","C":"Ovários policísticos;","D":"Klinefelter;","E":"Basedow-Graves."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-46695","number":"46695","sourceNumber":"46695","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma mulher de 40 anos de idade, não fumante e sem histórico familiar de doenças\ncoronarianas, submeteu-se a exames de rotina que revelaram os seguintes resultados: Colesterol\ntotal = 290 mg/dl; Colesterol LDL = 210 mg/dl; Colesterol HDL = 45 mg/dl; Triglicerideos = 160\nmg/dl e Glicemia de jejum = 98 mg/dl. A paciente, cujo Índice de Massa Corpórea (IMC) era de 26\nkg/cm², foi orientada a seguir uma dieta hipolipídica e a aumentar sua atividade física. Três meses\napós, seu IMC era de 24,8 kg/cm² e novos exames mostraram: Colesterol total = 253 mg/dl;\nColesterol LDL = 180 mg/dl; Colesterol HDL = 45 mg/dl e Triglicerídeos = 140 mg/dl. Foi também\navaliada a função tireoidiana que mostra um TSH = 16 mcUI/ml (VN = 0,3-5) e T4 livre = 0,6 ng/dl\n(VN = 0,8-1,9). Qual a melhor conduta para este caso?","options":{"A":"Iniciar fenofibrato ou ciprofibrato.","B":"Iniciar L-tiroxina.","C":"Iniciar L-tiroxina + uma estatina.","D":"Apenas insistir nas medidas não farmacológicas.","E":"Iniciar uma estatina."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-34102","number":"34102","sourceNumber":"34102","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Presença de nódulo tireoidiano com crescimento rápido e/ou mudanças nas\ncaracterísticas ultrassonográficas com aparecimento de\nalgum sinal suspeito de malignidade são\nindicativos de (defina a melhor conduta):","options":{"A":"PAAF e cirurgia.","B":"PAAF e injeção de etanol.","C":"Injeção de etanol e cirurgia.","D":"Radioterapia e cirurgia.","E":"Propranolol e radioterapia."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-26443","number":"26443","sourceNumber":"26443","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"As drogas antitireoidianas (propiltiouracil e metimazol), agem inibindo a tireoperoxidase\ntireoidiana e a conversão de T4 em T3","B":"A agranulocitose é efeito colateral muito comum das drogas antitireoidianas e ocorre em cerca\nde 20% dos pacientes que a utilizam","C":"O diagnóstico de hipertireoidismo subclínico é confirmado pela presença de concentrações\nbaixas ou suprimidas de TSH associada a valores\nnormais dos hormônios tireoidianos","D":"Caso o paciente apresente agranulocitose com uma das drogas antitireoidianas, esta deverá ser\ntrocada pela outra","E":"Na gestação a droga de escolha é o metimazol"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-26597","number":"26597","sourceNumber":"26597","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Todas as patologias abaixo são causas de tireotoxicose, exceto:","options":{"A":"Tireoide de Riedel","B":"Tireoide subaguda","C":"Doença trofoblástica","D":"Ingesta excessiva de hormônio tireoidiano","E":"Doença de Basedow-Graves"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-7469","number":"7469","sourceNumber":"7469","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Entre as alterações laboratoriais abaixo, assinale aquela que NÂO ocorre em\nportadores de hipotireoidismo primário:","options":{"A":"TSH elevado.","B":"TSH baixo.","C":"Anticorpo anti-tireoperoxidase positivo.","D":"T4 livre baixo.","E":"Anemia."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-10000","number":"10000","sourceNumber":"10000","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Criança 2 anos de idade, com retardo psicomotor (não anda, fala mal), prisão de ventre\nconstante, hérnia inguinal, fácies inexpressivas, com protrusão de língua, cabelos secos e\nquebradiços, pele seca e áspera.","options":{"A":"Hipotireoidismo congênito avançado.","B":"Hipotireoidismo adquirido com bócio.","C":"Hipotireoidismo congênito.","D":"Hipotireoidismo sem bócio.","E":"Hipotireoidismo juvenil."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-7457","number":"7457","sourceNumber":"7457","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A fadiga vocal e a perda do timbre da voz após uma tireoidectomia levam à suspeição\nde:","options":{"A":"traqueomalácia.","B":"lesão do nervo recurrente.","C":"secção da cartilagem cricoide.","D":"lesão do nervo laríngeo superior.","E":"pólipo de cordas vocais associado."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-10017","number":"10017","sourceNumber":"10017","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Num paciente com sintomas de tireotoxicose, resultante de uma tireoidite sub-aguda,\nqual das medidas terapêuticas estaria indicada?","options":{"A":"Tireoidectomia sub-total.","B":"Propranolol 20-40mg, 2-3X/ dia.","C":"Propiltíouracil, 100-200mg, 2-3X/ dia.","D":"Terapia com Iodo radioativo.","E":"Solução saturada de iodeto de potássio, 5 gts, 3X/ dia."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-354406","number":"354406","sourceNumber":"354406","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 45 anos de idade, apresenta-se na UBS com queixas de fadiga, ganho de peso\nnão intencional, constipação e pele seca, há 3\nmeses. Refere sentir-se mais sensível ao frio nos\núltimos meses. Ao exame físico, observa-se FC: 50bpm, PA: 140x100mmHg. A palpação da\ntireoide revela aumento difuso da glândula, com textura granular e ausência de nódulos palpáveis.\nDemais exames segmentares sem alterações. Diante do quadro clínico, indique os níveis\nhormonais, mais provavelmente, encontrados neste caso:","options":{"A":"T4 livre baixo e TSH baixo.","B":"TSH elevado e T4 livre baixo.","C":"T3 reverso elevado e TSH baixo.","D":"TSH baixo e T3 total baixo."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-354407","number":"354407","sourceNumber":"354407","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 45 anos de idade, apresenta-se na UBS com queixas de fadiga, ganho de peso\nnão intencional, constipação e pele seca, há 3\nmeses. Refere sentir-se mais sensível ao frio nos\núltimos meses. Ao exame físico, observa-se FC: 50bpm, PA: 140x100mmHg. A palpação da\ntireoide revela aumento difuso da glândula, com textura granular e ausência de nódulos palpáveis.\nDemais exames segmentares sem alterações. Indique o exame complementar mais adequado para\no diagnóstico etiológico do quadro de base:","options":{"A":"Dosagem de anticorpos antiperoxidase tireoidiana (anti-TPO).","B":"Teste de supressão com levotiroxina.","C":"Ultrassonografia de tireoide.","D":"Dosagem de T3 total."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-354408","number":"354408","sourceNumber":"354408","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 45 anos de idade, apresenta-se na UBS com queixas de fadiga, ganho de peso\nnão intencional, constipação e pele seca, há 3\nmeses. Refere sentir-se mais sensível ao frio nos\núltimos meses. Ao exame físico, observa-se FC: 50bpm, PA: 140x100mmHg. A palpação da\ntireoide revela aumento difuso da glândula, com textura granular e ausência de nódulos palpáveis.\nDemais exames segmentares sem alterações. Indique a conduta terapêutica inicial mais apropriada\npara esta paciente:","options":{"A":"Iniciar levotiroxina em dose padrão e avaliar com exames laboratoriais após 6 semanas.","B":"Encaminhar para avaliação endocrinológica antes de iniciar qualquer intervenção terapêutica.","C":"Administrar levotiroxina em dose agressiva para normalizar os níveis hormonais em até uma\nsemana.","D":"Realizar biópsia da tireoide para confirmar o diagnóstico antes de iniciar o tratamento."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-35003","number":"35003","sourceNumber":"35003","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, refere episódios de inquietação,\nnervosismo, tremor, palpitações, taquicardia,\ntranspiração, sensação de calor, palidez, irritabilidade,\nfraqueza, confusão mental, amnésia e tontura há seis meses. Realizou ultrassonografia abdominal\nque foi normal. Tomografia axial computadorizada de abdome revelou nódulo sólido de 1,8 cm na\ncabeça pancreática. Nega história familiar de neoplasias. Sobre a principal suspeita diagnóstica, é\nincorreto afirmar:","options":{"A":"É representada clinicamente pela tríade de Whipple.","B":"O método laboratorial diagnóstico de escolha é a dosagem dos níveis de peptídeo C no plasma.","C":"O exame de imagem pré-operatório de escolha é a ultrassonografia endoscópica.","D":"O método diagnóstico mais sensível isoladamente é a ultrassonografia intraoperatória.","E":"É o tumor neuroendócrino pancreático mais comum."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-35006","number":"35006","sourceNumber":"35006","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, sexo feminino, 45 anos de idade, refere episódios de inquietação,\nnervosismo, tremor, palpitações, taquicardia,\ntranspiração, sensação de calor, palidez, irritabilidade,\nfraqueza, confusão mental, amnésia e tontura há seis meses. Realizou ultrassonografia abdominal,\nque foi normal. Tomografia axial computadorizada de abdome revelou nódulo sólido de 1,8 cm na\ncabeça pancreática. Nega história familiar de neoplasias. O paciente foi levado à laparotomia\nexploradora, que evidenciou nódulo subcapsular na cabeça pancreática. Realizando biópsia de\ncongelação, sem evidências de malignidade na lesão. Diante de tais achados, o tratamento de\nescolha é:","options":{"A":"gastroduodenopancreatectomia.","B":"cirurgia de Whipple modificada por Longmire-Traverso.","C":"enucleação do nódulo.","D":"pancreatectomia total.","E":"expectante, visto que se trata de lesão benigna."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-27476","number":"27476","sourceNumber":"27476","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, 17 anos de idade, vem à consulta de rotina, quando se evidencia o aumento\nda tireoide. O bócio é de volume moderado,\nsuperfície irregular, indolor. A punção aspirativa por\nagulha fina (PAAF) revelou a presença de infiltrado inflamatório linfocitário e hiperplasia de\nfolículos. O diagnóstico mais provável é:","options":{"A":"disormonogêneses.","B":"tireoidite de Hashimoto.","C":"carcinoma anaplásico.","D":"bócio endêmico.","E":"adenopatia cervical."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-13311","number":"13311","sourceNumber":"13311","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, 32 anos de idade, G1P0A0, com gestação de 31 semanas, vem ao pré-natal\nreferindo que apresentou palpitações, pele quente, insônia, perda de peso, aumento da tireoide e\nexoftalmia. Traz exames com Ht: 34%, Hb: 11g%, TSH: 0,001, T4 livre: aumentado.\n\nUltrassonografia obstétrica, IG: 31 semanas e 2 dias, ILA: 95 mm, placenta-grau 1, peso fetal de\n1000 g, apresenta aumento das medidas da\ntireoide fetal. Vem em uso de propiltiouracil (PTU) 400\nmg/dia. A etiologia mais provável para esse quadro clínico é:","options":{"A":"adenoma tóxico","B":"hipertireoidismo transitório gestacional","C":"doença de Graves","D":"tireoidite de Hashimoto","E":"bócio multinodular"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-343352","number":"343352","sourceNumber":"343352","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um dado do exame físico que levanta a suspeita de puberdade precoce periférica em\num menino de 4 anos com virilização é a\npresença de:","options":{"A":"Pubarca","B":"Ginecomastia","C":"Quadro neurológico","D":"Testículos de volume infantil"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-249998","number":"249998","sourceNumber":"249998","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Fazem parte da Neoplasia Endócrina Múltipla tipo 1:","options":{"A":"Hiperparatireoidismo primário, lesão pancreática e hipofisária.","B":"Hiperparatireoidismo primário, tumor estromal e hipofisário.","C":"Hipoparatireoidismo primário, tumor estromal e adrenal.","D":"Hipoparatireoidismo primário, gastrinoma e hábito marfanoide."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-250003","number":"250003","sourceNumber":"250003","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"É um marcador sensível e específico do carcinoma medular de tireóide, que pode ser\nmedido no sangue no estado basal ou após a administração de secretagogos como cálcio e\npentagastrina:","options":{"A":"Tireoglobulina.","B":"Gastrina.","C":"Hormônio Folículo Estimulante.","D":"Calcitonina."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-215590","number":"215590","sourceNumber":"215590","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação ao carcinoma indiferenciado ou\nanaplásico de tireoide.","options":{"A":"É o segundo tumor mais comum da tireoide e é considerado o mais agressivo.","B":"Incide em pacientes mais idosos, com mais de 60 anos e com frequência um pouco maior em\nmulheres.","C":"Há associação com bócios de longa duração, com alteração aguda do ritmo de crescimento.","D":"Sintomas clínicos associados à infiltração tumoral, como disfagia, dispneia, tosse, rouquidão e\ndor estão presentes."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-181174","number":"181174","sourceNumber":"181174","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A Crise Tiroidiana é uma emergência médica que ocorre em pacientes com\ntireotoxicose. Aponte a alternativa INCORRETA sobre esta síndrome:","options":{"A":"A mortalidade da crise tiroidiana é alta, variando de 20% para 50% se a crise não for\nreconhecida e tratada.","B":"Ocorre aumento dos níveis de TSH e aumento dos hormônios T3 e T4 circulantes.","C":"Clinicamente é caracterizada por hiperpirexia, taquicardia desproporcional a febre, desidratação,\nchoque e manifestações cardiovasculares,\ndisfunção do sistema nervoso central.","D":"O tratamento envolve inibição da síntese, diminuição da conversão periférica de T4 em T3 e\nbloqueio da ação dor hormônios tiroideanos, além da remoção extracorpórea destes hormônios."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-157601","number":"157601","sourceNumber":"157601","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação aos carcinomas da tiróide, aponte a alternativa em que a afirmação esteja\nCORRETA.","options":{"A":"O Carcinoma Papilífero é o mais comum, é mais frequente em mulheres entre terceira e quarta\ndécada de vida, é pouco agressivo, e em crianças e adolescentes não apresenta alto índice de\nmetástase.","B":"O Carcinoma Anaplásico é o mais raro, incide mais em idosos, e tem boa resposta à\nquimioterapia e radioterapia.","C":"O Carcinoma Medular pode estar associado à Neoplasia Endócrina Múltipla 2a, onde a doença é\nbilateral, e pode ser acompanhada por hiperparatiroidismo, feocromocitoma ou hiperplasia medular\nadrenal.","D":"Na associação NEM 2b, a doença pode ser familiar ou esporádica, há comprometimento\nglandular bilateral eganglioneuromas\n\nmucosos. Tem melhor prognóstico quando comparado ao NEM 2a."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-157675","number":"157675","sourceNumber":"157675","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"É indicação relativa de Tiroidectomia:","options":{"A":"a suspeita de malignidade pelo exame físico, ultrassonográfico e citológico.","B":"Os bócios pequenos com alteração estética importante.","C":"O bócio tóxico.","D":"O bócio de grande volume."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-162512","number":"162512","sourceNumber":"162512","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação às desordens da glândula tireoide, é CORRETO afirmar que:","options":{"A":"O seguimento do paciente com hipotireoidismo primário se dá através da dosagem do TSH, não\nestando indicada a dosagem de T4L no acompanhamento do tratamento desse paciente.","B":"As dosagens de TSH,T3 e T4L são necessárias para o diagnóstico do hipotireoidismo.","C":"A doença mais comum da tireoide é o hipertireoidismo, acomentendo mais as mulheres cima\ndos 60 anos.","D":"A causa mais comum de hipertireoidismo em indivíduos jovens é o bócio multinodular tóxico,\nque é a causa desse quadro em 60 a 80%.","E":"A anemia leve, a hiponatremia, a dislipidemia e as elevações da creatinofosfoquinase e da\nprolactina são alterações que podem estar associadas ao hipotireoidismo, sendo solicitação\ndesses exames parte da avaliação de rotina do paciente."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-350900","number":"350900","sourceNumber":"350900","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 55 anos foi investigada por ganho de peso e astenia, tendo sido constatadas\nas seguintes alterações laboratoriais:\nTSH=30mU/L, T4l=0,1ng/dL, Colesterol total=340mg/dL,\nHDL=30mg/dL, LDL=232mg/dL, Triglicerídeos=390mg/dL, Cr=1,1mg/dL. Foi prescrita levotiroxina\n50mcg pela manhã com reavaliação após 6 semanas. No retorno, a paciente relatou que ficou\npreocupada com o colesterol e optou por tomar remédio de sua mãe (rosuvastatina 20mg todos os\ndias), antes de iniciar o tratamento proposto inicialmente. Agora, relata intensas dores em\npanturrilhas e coxas e episódios de urina avermelhada. Novos exames mostram hemograma\nnormal, CPK=1.200U/L, Cr=2,5mg/dL, sumário de urina com Hb (++), sem hemácias no sedimento.\nOptou-se pelo internamento com hidratação e monitorização. Após 5 dias, exames normalizaram.\nQual deve ser a conduta medicamentosa após a alta desta paciente?","options":{"A":"Suspender rosuvastatina e iniciar levotiroxina.","B":"Reduzir dose de rosuvastatina e iniciar levotiroxina.","C":"Postergar início de levotiroxina e suspender rosuvastatina.","D":"Postergar início de levotiroxina e reduzir dose de rosuvastatina."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-350825","number":"350825","sourceNumber":"350825","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"RNT, sem intercorrências ao nascimento, encontra-se no 10º dia de vida, estável em ar\nambiente e apresentando icterícia por aumento de bilirrubina indireta. Ao exame físico, além da\nicterícia, apresentava abdome globoso sem megalias palpáveis e sem outras alterações ao exame\nfísico. Mãe com tipagem sanguínea \"O positiva\" e RN \"O\" positivo também. A que doença a icterícia\npoderia estar associada?","options":{"A":"Hepatite.","B":"Obstrução de vias biliares.","C":"Hipotireoidismo congênito.","D":"Hipoatividade da medula óssea."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-321283","number":"321283","sourceNumber":"321283","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 19 anos apresenta episódios de diarreia profusa com rubor facial e queixa de\nperda de 8 kg, atualmente seu peso é 43 kg, IMC 16. Na investigação, foi detectada uma elevação\nde cálcio sérico e calcitonina. Qual exame de imagem, inicialmente, deve ser solicitado para\nesclarecimento dessa condição?","options":{"A":"Colonoscopia.","B":"Radiografia do tórax.","C":"Ultrassonografia cervical.","D":"Tomografia do abdome."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-259711","number":"259711","sourceNumber":"259711","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Homem, 51 anos, hipertenso, fumante, realizou Ultrassonografia (US) Doppler de\ncarótidas sendo detectado nódulo tireoidiano.\nRealizou US da tireoide, que revelou a presença de\nnódulos em ambos os lobos da tireoide: Nódulo 1 (N1), misto, hiperecoico, medindo 1,1 x 0,7 cm\nem lobo esquerdo e Nódulo 2 (N2) sólido, hipoecoico, sem microcalcificações na transição do\nistmo/lobo direito 0,8 x 0,5 cm. Para prosseguir a investigação dos nódulos do paciente, qual o\npróximo exame a ser realizado?","options":{"A":"Cintilografia de tireoide.","B":"Dosagem de TSH sérico.","C":"Punção aspirativa de N1.","D":"Punção aspirativa de N2."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-234012","number":"234012","sourceNumber":"234012","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente masculino, 66 anos, procura atendimento com um cirurgião geral para uma\n\"segunda opinião\". Informa que há um mês\nprocurou atendimento de emergência por um quadro de\ndor abdominal inespeci?fica. Foi solicitada uma tomografia computadorizada do abdômen que\nevidenciou como único achado positivo uma lesão homogênea bem delimitada e com aparente\nbaixa captação de contraste em glândula adrenal esquerda, medindo 4 cm. O paciente nega\nhipertensão, doenças cardíacas e outras comorbidades. No momento da consulta, nega uso de\nmedicações regulares, está assintomático e apresenta exame fi?sico normal. Qual deve ser a\nconduta?","options":{"A":"Solicitar punc?a?o guiada por tomografia para coleta de amostra citolo?gica da massa.","B":"Encaminhar para a ressecc?a?o da massa (adrenalectomia) em decorre?ncia de alto risco de\nmalignizac?a?o.","C":"Por se tratar de lesa?o com aspecto tomogra?fico benigno, observar e realizar exames\ntomogra?ficos semestrais.","D":"Solicitar dosagem de catecolaminas urina?rias em 24h e teste de supressa?o com dose baixa de\ndexametasona."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-234034","number":"234034","sourceNumber":"234034","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 38 anos com evacuações frequentes há 3 meses, em qualquer hora do dia\nou da noite, volumosas, aquosas, sem\nsangue, dor, febre ou relação com as refeições. Relata\nperda de 2 kg, redução do apetite, náuseas e tonturas matinais. Nega etilismo, medicamentos de\nuso crônico ou habitual. Ao exame, apresenta hiperpigmentação cutânea e algumas lesões\nhipocrômicas sugestivas de vitiligo. Normocorada, anictérica e afebril, apresenta hipotensão\npostural e desidratação leve. IMC: 26 kg/m². Exame do abdome e demais sistemas sem\nanormalidades. Exames prévios: hemograma normal, sódio: 132 mEq/L (VR: 135?145 mEq/L),\npotássio: 5,6 mEq/L (VR: 3,5?5,0 mEq/L), pesquisa de sangue oculto nas fezes negativo, pesquisa\nde gordura fecal 3 g/dia (VR: 1,8?6 g/dia). LEGENDA: VR: Valor de Referência; IMC: Índice de\nMassa Corporal. Qual conduta mais apropriada e o diagnóstico provável?","options":{"A":"Pesquisar o antígeno da Giardia lamblia e tratar com metronidazol ? giardíase.","B":"Dosar cortisol e ACTH basal e repor glico e mineralocorticoide ? doença de Addison.","C":"Realizar teste terapêutico com antidepressivos tricíclicos ? síndrome do intestino irritável.","D":"Realizar teste terapêutico com restrição de leite e derivados na dieta ? intolerância à lactose."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-199750","number":"199750","sourceNumber":"199750","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma jovem de 23 anos, atendida pela equipe de saúde da família, apresenta um nódulo\nna porção anterior baixa do pescoço, móvel à\ndeglutição e com diâmetro aproximado de 1,5 cm.\n\nNão apresenta taquicardia, dor à palpação ou sinais flogísticos. Nega perda de peso ou\npalpitações. Qual o próximo exame na investigação diagnóstica?","options":{"A":"Cintilografia da tireoide.","B":"Punção com agulha fina e citologia.","C":"Ultrassonografia cervical com Doppler.","D":"Dosagem de hormônio tireoestimulante (TSH)."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-199773","number":"199773","sourceNumber":"199773","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 28 anos compareceu em consulta ambulatorial referindo ganho de peso há 8\nmeses, associado ao surgimento de acne, hirsutismo, irregularidade menstrual e fraqueza\nmuscular. Há 2 meses, refere sintomas depressivos e nega uso de outros medicamentos. Ao\nexame, PA = 150 x 100 mmHg, pulso = 92 bpm. Índice de massa corporal = 32 kg/m²; cintura = 98\ncm. Face arredondada e pletórica. Pele fina, com acne em face e dorso, estrias largas e arroxeadas\nabdominais e equimoses em membros. Fraqueza muscular proximal. Qual exame está indicado no\ninício da investigação para confirmar o diagnóstico clínico?","options":{"A":"Cortisol plasmático basal.","B":"Cortisol salivar domiciliar às 23:00.","C":"Cortisol livre urinário em amostra isolada.","D":"Cortisol pós-8 mg dexametasona às 23:00."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-172970","number":"172970","sourceNumber":"172970","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 35 anos comparece ao seu consultório com uma ultrassonografia e\nexames laboratoriais de rotina solicitados pelo ginecologista. A paciente gostaria de sua opinião\nsobre um nódulo que foi detectado na tireoide. A ultrassonografia mostra lesão de aspecto\n\ncístico-sólido de 1,4 cm. Os exames laboratoriais mostram TSH e T4 normais. Ao exame, o nódulo\né impalpável. A paciente nega história familiar de\nlesões semelhantes e qualquer tratamento\nradioterápico. Você, então, solicita um PAAF. Em qual das seguintes situações, referentes aos\nachados do PAAF, a paciente deve ser orientada a retornar para repetir a ultrassonografia no\nperíodo dos próximos 6 a 12 meses?","options":{"A":"Material amorfo de aspecto coloide com raros macrófagos.","B":"Células em arranjo folicular de característica indeterminada.","C":"Células em arranjo papilífero com anisocitose e mitoses atípicas.","D":"Células multiformes de contornos irregulares com mitoses atípicas e aberrantes."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-172958","number":"172958","sourceNumber":"172958","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 29 anos procurou assistência médica referindo há 3 meses perda de peso (3\nkg), irritabilidade, calor excessivo e palpitações. A paciente refere ainda amenorreia há 2 meses,\nnáuseas e vômitos. Ao exame, apresentava proptose ocular bilateral, bócio difuso e indolor, tremor\nfino de extremidades e taquicardia. Exames laboratoriais: TSH < 0,02 mUI/L (VR = 0,3-4,0 mUI/L);\nT4 livre = 2,17 ng/dl (VR = 0,7-1,5 ng/dl); TRAb = 5,4 U/L (positivo > 1,75 U/L); hCG = positivo.\n\nLegenda: TSH ? hormônio tireoestimulante; T4 ? tiroxina; TRAb ? anticorpo antirreceptor de TSH;\nhCG ? gonadotrofina coriônica humana; VR ? Valor de Referência. Qual a conduta terapêutica mais\nindicada?","options":{"A":"Hidratar.","B":"Iniciar metimazol.","C":"Iniciar propiltiouracila.","D":"Realizar tireoidectomia total."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-150825","number":"150825","sourceNumber":"150825","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 25 anos procura aconselhamento médico por ter sido tratada de carcinoma\nmedular da tireoide diagnosticado durante investigação de hipercalcemia. Foi submetida a teste\ngenético para Neoplasia Endócrina Múltipla (NEM), o qual apresentou mutação germinativa\npatogênica do gene RET. História familiar: pai com neoplasia neuroendócrina pancreática e tia\nfalecida por câncer de tireoide. Ela tem um filho de 4 anos e está preocupada com o risco de ele\ndesenvolver neoplasia. Qual a melhor orientação para o filho?","options":{"A":"Tireoidectomia total, se hipercalcemia.","B":"Dosagens periódicas do nível sérico de calcitonina.","C":"Monitorização com ultrassonografia cervical periódica.","D":"Teste genético para NEM e avaliação de mutação do gene RET."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-126994","number":"126994","sourceNumber":"126994","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 35 anos comparece para avaliação com história de febre não mensurada,\nperda de peso com apetite preservado,\nsudorese e palpitações. No exame físico, você observa\nfrequência cardíaca de 108 bpm, Pressão arterial 150x60 mmHg, mãos quentes e úmidas e leve\ntremor de extremidades. Qual dos itens abaixo representa a combinação de exames esperada\nnesse caso?","options":{"A":"TSH baixo e T4 livre baixo.","B":"TSH alto e T4 livre baixo.","C":"TSH alto e T4 livre alto.","D":"TSH baixo e T4 livre alto."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-81237","number":"81237","sourceNumber":"81237","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 55 anos, sexo feminino, é encaminhada ao ambulatório de cirurgia pelo\nendocrinologista, com uma massa palpável na região cervical anterior de aproximadamente 3 cm\nde diâmetro, com níveis de calcitonina basal de 600 pg/ml, sem outras alterações e sem casos\nsemelhantes na família. Qual o diagnóstico mais provável e qual o tratamento recomendado para\nessa paciente?","options":{"A":"Carcinoma folicular da tireoide e tireoidectomia total.","B":"Carcinoma medular da tireoide e tireoidectomia total.","C":"Carcinoma papilar da tireoide e tireoidectomia subtotal.","D":"Carcinoma de anaplásico da tireoide e tireoidectomia subtotal."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-51280","number":"51280","sourceNumber":"51280","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher jovem apresenta aumento homogêneo da porção anterior do pescoço, labilidade\nemocional, tremor de extremidades, taquicardia, sudorese profusa e perda de peso. Após\nconfirmação diagnóstica, a cirurgia deverá ser indicada se a paciente apresentar qual das\ncondições associadas?","options":{"A":"Gravidez.","B":"Exoftalmia.","C":"Rouquidão.","D":"Tireotoxicose."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-51287","number":"51287","sourceNumber":"51287","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 56 anos comparece para consulta com queixa de piora do quadro prévio de\nAngina pectoris. Vinha em uso de sinvastatina, aspirina e metoprolol. Exame físico: cabelos\nressecados, fala arrastada e edema facial (+/4+). Peso: 75 kg; pulso: 92 bpm. Além da doença\ncoronariana (para a qual se vale de Sinvastatina, Aspirina e Metoprolol), tem hipotireoidismo de\ndiagnóstico recente, em uso de 75 mcg de levotiroxina. Foi iniciado tratamento com isossorbida.\n\nCom relação ao tratamento do hipotireoidismo desse paciente, que conduta é recomendável?","options":{"A":"Suspender a levotiroxina.","B":"Manter a dose de levotiroxina.","C":"Reduzir a dose da levotiroxina para 25 mcg/dia.","D":"Aumentar a dose de levotiroxina para 112,5 mcg/dia."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-37376","number":"37376","sourceNumber":"37376","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Considere o quadro clínico e escolha a alternativa correta: Paciente feminina, branca,\n32 anos, balconista, refere fadiga e cansaço\nfísico. Nega dispneia. Apresenta também episódios de\nirritabilidade, ansiedade e insônia há cerca de três meses, associando os sintomas à mudança\nrecente de emprego. Relata que, apesar de aumento da ingesta alimentar, perdeu 8 kg no período.\nTambém apresenta palpitações e tremores finos em extremidades. No exame físico, foi evidenciado\nritmo cardíaco irregular, FC 110 bpm, aumento de volume em região cervical anterior e proptose\nocular bilateral.","options":{"A":"Trata-se de doença autoimune da tireoide, caracterizada por produção aumentada de\nimunoglobulinas tireoestimulantes, levando à secreção aumentada de hormônio tireoidiano e\naumento difuso da glândula. Deve ser solicitada dosagem de T4 livre e TSH para confirmação e\niniciado tratamento com levotiroxina e betabloqueador.","B":"Trata-se de doença autoimune da tireoide, caracterizada por destruição do tecido tireoidiano,\nlevando a hipofunção com infiltrado\nlinfocitário e fibrose da glândula. Deve ser solicitada dosagem\nde T4 livre e TSH para confirmação e iniciado tratamento com levotiroxina dose baixa, com\nposterior progressivo aumento da dose.","C":"Trata-se de doença autoimune da tireoide, caracterizada por produção aumentada de\nimunoglobulinas tireoestimulantes, levando à secreção aumentada de hormônio tireoidiano e\naumento difuso da glândula. Deve ser solicitada dosagem de T4 livre e TSH para confirmação e\niniciado tratamento com propiltiouracil e betabloqueador.","D":"Trata-se de doença autoimune da tireoide, caracterizada por destruição do tecido tireoidiano,\nlevando à hipofunção com infiltrado\nlinfocitário e fibrose da glândula. Deve ser solicitada dosagem\nde T4 livre e TSH para confirmação e iniciado tratamento com propiltiouracil e betabloqueador.","E":"Trata-se de doença autoimune da tireoide, caracterizada por produção aumentada de\nimunoglobulinas tireoestimulantes, levando à hipofunção tireoidiana com infiltrado linfocitário e\nfibrose da glândula. Deve ser solicitada dosagem de T4 livre e TSH para confirmação e iniciado\ntratamento com propiltiouracil e betabloqueador."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-37399","number":"37399","sourceNumber":"37399","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 45 anos lhe procura na atenção primária à saúde para realizar um\n\n?check up?. Durante o exame físico você suspeita de uma alteração na palpação da tireoide. Com\nrelação às possibilidades diagnósticas e terapêuticas dessa paciente, assinale a associação mais\ncorreta:","options":{"A":"Mediante exames de função tireoidiana normais ou\naumentados o próximo passo deve ser o ultrassom.","B":"Nódulos sólidos ao ultrassom devem ser tratados\nprimariamente por cirurgia.","C":"Produto de biópsia por aspiração de agulha fina\nrevelando células foliculares indica tratamento cirúrgico.","D":"Produto de biopsia por aspiração de agulha fina com resultado inconclusivo indica tratamento\ncirúrgico.","E":"O achado de nódulo quente à cintilografia em pacientes com hipertireoidismo praticamente exclui\na presença de lesão maligna."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-30934","number":"30934","sourceNumber":"30934","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 25 anos é encaminhada por apresentar níveis séricos elevados de T4 total e\nníveis normais de TSH. Assintomática. Qual dessas opções apresenta a explicação mais provável\ndessa alteração laboratorial?","options":{"A":"Hipertireoidismo subclínico.","B":"Resistência hipofisária ao hormônio tireoideano.","C":"Resistência periférica ao hormônio tireoideano.","D":"Uso de anticoncepcional oral.","E":"Adenoma hipofisário produtor de TSH."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-30932","number":"30932","sourceNumber":"30932","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre câncer da tireoide, podemos afirmar que:","options":{"A":"O carcinoma folicular é o mais comum, sendo frequente a ocorrência de metástases regionais e\nà distância.","B":"O carcinoma medular é o mais agressivo, necessitando emprego de quimioterapia neoadjuvante\nseguida de tireoidectomia total para\ncontrole local da doença.","C":"O tratamento clássico de carcinomas bem diferenciados é a tireoidectomia parcial com\nseguimento pós-operatório pela dosagem de tireoglobulina e calcitonina.","D":"O carcinoma papilífero afeta mais comumente mulheres e poucos pacientes cursam com\nsintomas de malignidade, como dor cervical, disfonia ou dispneia.","E":"A biópsia por agulha fina de nódulos tireoidianos é excelente no diagnóstico de carcinomas\nfoliculares e muito pouco específica nos papilíferos."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-24314","number":"24314","sourceNumber":"24314","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Quando um paciente apresenta um nódulo palpável na tireoide e os testes de função\nsão normais, ultrassom é realizado. Como o\nnódulo era sólido, foi indicada uma punção com agulha\nfina para citologia. A ressecção cirúrgica está indicada nos casos abaixo, EXCETO:","options":{"A":"Presença de células foliculares no esfregaço","B":"Esfregaço compatível com neoplasia papilar","C":"Esfregaço contendo coloide e macrófagos","D":"Esfregaço com células de Hurthle"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-22935","number":"22935","sourceNumber":"22935","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente 65 anos, diabética, com antecedente de uso de amiodarona por arritmia\ncardíaca controlada evolui, em 3o pós-operatório\nde colecistectomia, com confusão mental e\nsonolência. Seus sinais vitais estão normais, não tem dispneia, dor torácica e os exames mostram\nhiponatremia (Na = 120 mEq/L) com glicemia e eletrocardiograma normais. São, respectivamente,\na causa mais provável e o exame a ser solicitado:","options":{"A":"insuficiência renal e creatinina","B":"tromboembolismo pulmonar e dímero-D","C":"hipotireoidismo e TSH","D":"acidente vascular cerebral e tomografia computadorizada de crânio","E":"sepse e hemoculturas"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-22952","number":"22952","sourceNumber":"22952","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Dentro das patologias benignas da tireoide, podemos citar os distúrbios do metabolismo\ncomo o hipotireoidismo. Sobre essa\npatologia é INCORRETO afirmar que:","options":{"A":"está associado a um decréscimo da produção de T3 e T4 na glândula, embora possam também\nocorrer estados de limitada atividade na\nperiferia","B":"a ingestão insuficiente de iodo em países subdesenvolvidos explica a grande quantidade de\nestados hipotieoideos. Já nos países desenvolvidos as principais causas são a tireoidite de\nHashimoto e a ablação cirúrgica da glândula","C":"outras causas mais raras de hipotireoidismo referem-se aos defeitos hereditários da síntese de\nhormônio, ação medicamentosa e hipoplasia ou agenesia da tireoide","D":"acompanhando as alterações fisiológicas em resposta à deficiência de iodo, ocorre uma\ndiminuição difusa da glândula por uma resposta hipotrófica dos folículos tireoideanos e aumento\ndos espaços foliculares","E":"à medida que a deficiência de iodo torna-se mais grave, os folículos podem se tornar inativos e\ndistendidos pelo coloide, levando, em alguns casos à necrose, retração, hemorragia e retração\nfibrosa"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-24307","number":"24307","sourceNumber":"24307","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 32 anos evoluindo com febre baixa, mialgia e dor de garganta há 01 semana.\nHá 03 dias percebeu aumento do volume da\ntireóide que se mostrava muito dolorosa à palpação.\n\nNo momento do exame, apresentava FC=120 bpm, exame da orofaringe normal e sopro sistólico\npancardíaco. Qual a melhor opção em relação ao diagnóstico e conduta?","options":{"A":"Trata-se de Doença de Graves. Solicito TSH, T3 e T4 e inicio propiltiouracil","B":"Trata-se tireoidite viral. Solicito TSH, T3 e T4 e inicio AAS","C":"Trata-se de Doença de Graves. Solicito TSH e T4 livre e início prednisona","D":"Trata-se de tireoidite silenciosa. Solicito TSH e T4 livre e início propiltiouracil"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-27744","number":"27744","sourceNumber":"27744","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente 36 anos, sexo feminino, com história de fadiga, constipação intestinal,\n\n?esquecimento?. Apresenta-se com a pele ressecada, pulso 60 ppm. A dosagem de T4 livre\nencontra-se diminuída e a de TSH aumentada. Qual a hipótese diagnóstica mais provável para\nesse caso?","options":{"A":"Hipotireoidismo primário","B":"Hipotireoidismo secundário","C":"Eutireoidismo","D":"Resistência ao hormônio tireoideano","E":"Hipertireoidismo"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-27731","number":"27731","sourceNumber":"27731","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação ao câncer da tireoide, é correto afirmar que:","options":{"A":"sexo feminino e idade inferior a 40 anos são fatores prognósticos desfavoráveis no câncer bem\ndiferenciado da tireoide.","B":"a disseminação via hematogênica é a preferencial dos carcinomas papilíferos da tireoide.","C":"o carcinoma anaplásico é de progressão lenta.","D":"o carcinoma medular da tireoide está relacionado com neoplasia endócrina múltipla tipo 2A.","E":"o carcinoma folicular está relacionado com o aumento do nível de calcitonina sérica."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-25319","number":"25319","sourceNumber":"25319","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação ao Carcinoma (Ca) da Tireoide, assinale a alternativa ERRADA:","options":{"A":"O Ca Papilífero é um carcinoma bem diferenciado, é o mais prevalente dos Ca desta glândula,\npode ser diagnosticado através de Punção\nBiópsia Aspirativa por Agulha Fina (PAAF) e com maior\nfrequência gera metástases por via linfática, e não por via hematogênica.","B":"O Ca Folicular é um carcinoma bem diferenciado, é o 2º mais prevalente dos Ca desta glândula,\npode ser diagnosticado através de Punção\nBiópsia Aspirativa por Agulha Fina (PAAF) e com maior\nfrequência gera metástases por via hematogênica, e não por via linfática.","C":"O Ca Anaplásico é um carcinoma indiferenciado, perfaz menos que 5% dos Ca desta glândula,\npode ser diagnosticado através de Punção\nBiópsia Aspirativa por Agulha Fina (PAAF) e com\nfrequência gera metástases por via hematogênica, e não por via linfática.","D":"O Ca Medular tem origem nas células C (produtoras de calcitonina), pode se apresentar na\nforma familiar ou esporádica, e pode fazer\nparte da Neoplasia Endócrina Múltipla tipo IIa, junto com\nHiperparatireoidismo Primário e Feocromocitoma.","E":"A história de irradiação do pescoço é um fator etiológico importante no desenvolvimento do\ncâncer de tireoide."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-9025","number":"9025","sourceNumber":"9025","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre nódulo tireoidiano é FALSO afirmar:","options":{"A":"A possibilidade de um nódulo tireoidiano ser câncer é maior em homens acima de 50 anos.","B":"Múltiplos nódulos tireoidianos são mais frequentemente benignos.","C":"Carcinoma papilífero pode se apresentar na forma de uma lesão cística.","D":"Um nódulo sólido com calcificações é usualmente maligno."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-7266","number":"7266","sourceNumber":"7266","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre a anatomia da glândula tireoide, responda o item correto.","options":{"A":"As artérias tireoideas superior e inferior são ramos diretos da artéria carótida externa e\nsubclávia, respectivamente.","B":"A glândula é drenada por três pares de sistema venoso: superior, média e inferior. A veia\ntireoidea média é encontrada em mais da metade das pessoas.","C":"A tireoide apresenta um pobre sistema de drenagem linfática, justificando portanto a baixa\nincidência de metástases linfonodais.","D":"Do lado esquerdo o nervo laríngeo recorrente separa-se do vago quando cruza com a artéria\nsubclávia. Do lado direito esta separação se dá quando o nervo atravessa a artéria aorta.","E":"O nervo laríngeo superior separa-se do nervo vago no pólo superior da tireoide e possui apenas\nfunção motora."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-8866","number":"8866","sourceNumber":"8866","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Nos pacientes com câncer de tireoide tratados com tireoidectomia ?quase total?, qual o\nprincipal indicador de recidiva do tumor?","options":{"A":"Aumento de TSH.","B":"Redução de T3.","C":"Redução de T4.","D":"Aumento de tireoglobulina.","E":"Aumento de iodo."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-17831","number":"17831","sourceNumber":"17831","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No hipertireoidismo é verdadeiro afirmar:","options":{"A":"A maioria tem causa secundária","B":"Na doença de Plummer os níveis de TSH são normais","C":"Aumento difuso da glândula com sinais de tireotoxicose sugerem doença de Graves","D":"No struma ovarii cerca de dois terços das pacientes tem clínica de hipertireoidismo","E":"Carcinoma anaplásico da tireoide cursa com hipertireoidismo em 30% dos casos"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-349743","number":"349743","sourceNumber":"349743","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino, 56 anos, em pós-operatório de tireoidectomia radical, deu\nentrada no pronto atendimento com queixa de formigamento em membros superiores e tremores,\nassociados a sudorese. No exame físico, são encontrados sinais de Trousseau e Chvostek\npositivos. Considerando o antecedente da paciente, qual eletrólito pode estar em níveis alterados e\nque poderia explicar a clínica e os achados no exame físico?","options":{"A":"Cálcio.","B":"Sódio.","C":"Potássio.","D":"Magnésio.","E":"Cloro."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-349765","number":"349765","sourceNumber":"349765","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente será submetido a uma tireoidectomia total devido a um câncer de tireoide.\nDiante disso, as principais complicações que podem ocorrer após o procedimento e devem ser\ninformadas ao paciente pelo médico são:","options":{"A":"hipercalcemia e alteração da voz.","B":"hipocalemia e rouquidão.","C":"hipocalcemia e paresia dos músculos da face.","D":"hipercalemia e dificuldade de deglutição.","E":"hipocalcemia e alteração da voz."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-365648","number":"365648","sourceNumber":"365648","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No que concerne à avaliação das disfunções e lesões tireoidianas, assinale a\nalternativa que apresenta uma recomendação para a avaliação da tireoide.","options":{"A":"Não há indicação de pesquisa de marcadores moleculares na avaliação do nódulo tireoidiano.","B":"Na avaliação inicial dos nódulos da tireoide, deve-se solicitar tireoglobulina sérica.","C":"Deve-se solicitar a dosagem de T3 reverso na avaliação da função tireoidiana.","D":"Deve-se repetir anualmente a dosagem do anticorpo anti-TPO nos pacientes com tireoidite de\nHashimoto com exame anterior positivo."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-365646","number":"365646","sourceNumber":"365646","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A tireoidite de Hashimoto, o mais frequente distúrbio autoimune da tireoide, é a\nprincipal\ncausa de hipotireoidismo nas áreas do mundo onde não há deficiência de iodo. (Disponível em\n\n<https://www.sciencedirect.com/science/article/abs/pii/S1521690X19301186> Acesso em: 7 dez.\n2023, com adaptações.) Quanto a esse tema,\nentre os fatores de risco para o desenvolvimento da\ntireoidite de Hashimoto, está o (a)","options":{"A":"testosterona.","B":"excesso de vitamina D.","C":"suspensão de tratamento com interferon.","D":"excesso de iodo."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-322128","number":"322128","sourceNumber":"322128","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente será submetido a uma tireoidectomia total. Qual das alternativas a seguir\napresenta uma complicação que pode ocorrer em consequência desse tipo de cirurgia e sua\njustificativa?","options":{"A":"Hiperparatireoidismo por lesão das paratireoides.","B":"Paralisia de prega vocal por lesão do nervo laríngeo recorrente.","C":"Hipertireoidismo por liberação de grande quantidade de hormônios tireoideanos.","D":"Rouquidão por lesão do nervo glossofaríngeo.","E":"Hipercalcemia por paratireoidectomia acidental."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-322150","number":"322150","sourceNumber":"322150","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação ao hipotireoidismo, é correto afirmar que","options":{"A":"é muito importante solicitar tireoglobulina sérica na avaliação inicial de nódulos de tireoide.","B":"a dosagem do T3 reverso (rT3), na avaliação de função tireoideana, é essencial.","C":"Não devem ser repetidos exames de autoanticorpos [antitireoperoxidase (Anti-TPO) e/ou\nantitireoglobulina] no seguimento de\npacientes com hipotireoidismo por tireoidite de Hashimoto com\nexame anterior positivo.","D":"é essencial a dosagem de tri-iodotironina (LT3), isolada ou em associação com levotiroxina\n(LT4), no tratamento de hipotireoidismo.","E":"a dosagem de marcadores moleculares, na avaliação inicial de pacientes com nódulo de tireoide,\né muito importante para o plano terapêutico."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-322179","number":"322179","sourceNumber":"322179","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Na Hiperplasia congênita das suprarrenais por deficiência da 21-hidroxilase, ocorre","options":{"A":"aumento exagerado da produção de cortisol, sem alterar os níveis de aldosterona.","B":"deficiência de 17-hidroxiprogesterona, com aumento da produção dos androgênios suprarrenais,\nexceto de androstenediona e testosterona.","C":"aumento do cortisol, com retroalimentação negativa deficiente do cortisol na hipófise e no\nhipotálamo, seguida por grave redução de hormônio liberador de corticotrofina e hormônio\nadrenocorticotrófico.","D":"hiperplasia das glândulas por redução dos níveis de hormônio liberador de corticotrofina e de\nhormônio adrenocorticotrófico.","E":"deficiência da produção de cortisol e, em 75% dos pacientes, deficiência da produção de\naldosterona."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-322192","number":"322192","sourceNumber":"322192","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Quais dos seguintes sintomas podem estar associados ao aumento do hormônio\nprolactina no organismo?","options":{"A":"Queda de cabelo e acne.","B":"Hirsutismo e aumento do fluxo menstrual.","C":"Amenorreia e galactorreia.","D":"Irregularidade menstrual e disforia pré-menstrual.","E":"Dispareunia e dismenorreia."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-305276","number":"305276","sourceNumber":"305276","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente com um nódulo de tireoide biopsiado, compatível com neoplasia, possui\nindicação de tireoidectomia total. Para realizar tal cirurgia, o médico deve ter o conhecimento das\nestruturas anatômicas da região. Assinale a alternativa que apresenta apenas informações\nCORRETAS sobre a anatomia locorregional necessária para esse procedimento.","options":{"A":"A tireoide está localizada sob os músculos platisma e escaleno, que devem ser seccionados ou\nafastados para acessá-la.","B":"É necessário ficar atento quanto ao trajeto do nervo glossofaríngeo, já que ele tem seu trajeto\nlateral e adjacente à tireoide.","C":"É necessário ficar atento quanto ao esôfago, que tem trajeto posterior e adjacente à glândula\ntireoide.","D":"É necessário ficar atento às paratireoides, que se localizam atrás da glândula tireoide,\nadjacentes a ela.","E":"As artérias que irrigam a tireoide ? tireóidea superior, média e inferior ? provêm da artéria\ncarótida interna."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-298863","number":"298863","sourceNumber":"298863","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nPor causa da alteração de humor depressivo, o ideal é iniciar com lítio e risperidona em doses\nbaixas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/298863.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-298864","number":"298864","sourceNumber":"298864","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nO PTH é responsável pelo aumento do cálcio sérico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/298864.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-298865","number":"298865","sourceNumber":"298865","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nSintomas psiquiátricos são pouco conhecidos e extremamente raros nesses pacientes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/298865.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-298866","number":"298866","sourceNumber":"298866","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nVitamina D pode ser considerada como um tratamento não cirúrgico importante para esse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/298866.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-298867","number":"298867","sourceNumber":"298867","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nAs setas em branco denotam lesões líticas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/298867.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-298868","number":"298868","sourceNumber":"298868","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 60 anos de idade, proveniente da Índia, foi atendido no pronto-socorro\npor alteração do status mental, humor deprimido\ne mudança de comportamento. Além disso, ele\napresentava dor óssea. Exames bioquímicos indicaram o nível de PTH 20 vezes acima do valor de\nreferência. A função renal mostrou-se preservada; SatO2 = 97% em ar ambiente; FC = 86 bpm; e\nPA = 120 mmHg x 84 mmHg. TC de pelve foi realizado, conforme imagem a seguir. A respeito\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue os itens a seguir.\nÉ importante avaliar a presença de fraturas vertebrais, bem como sintomas de compressão\nradicular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/298868.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-274368","number":"274368","sourceNumber":"274368","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação às tireoidites, assinale a alternativa CORRETA.","options":{"A":"A tireoidite de Hashimoto é a forma mais comum, acometendo mais mulheres, entre 3?40 anos,\nsendo o evento laboratorial mais comum a presença de anticorpos antitireoglobulina.","B":"A tireoidite pós-parto é um quadro raro que ocorre nos primeiros dias pós-parto, de curta\nduração, autolimitado, sem necessidade de tratamento específico.","C":"A tireoidite de Quervain é um quadro inflamatório e autoimune da tireoide, geralmente\nautolimitado, mais frequente em mulheres, presumivelmente causado por infecção viral ou\npós-infecção viral.","D":"A tireoidite mais comum é de forma infecciosa, causada por bactérias gram-positivas, comum\nem pacientes previamente hígidos e com bom\nprognóstico.","E":"A tireoidite induzida por radiação é um quadro de ocorrência exclusiva de pacientes com terapia\nactínica para controle de tireotoxicose prévia e se manifesta como coma mixedematoso por perda\naguda da função tireoidiana."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-274375","number":"274375","sourceNumber":"274375","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O tipo histológico mais comum de neoplasia de tireoide e seu padrão de disseminação\nsão, respectivamente:","options":{"A":"carcinoma folicular, padrão linfonodal.","B":"carcinoma folicular, padrão hematogênico.","C":"carcinoma papilífero, padrão hematogênico.","D":"carcinoma papilífero, padrão linfonodal.","E":"carcinoma medular, padrão linfonodal."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262130","number":"262130","sourceNumber":"262130","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. A paciente\napresenta um quadro de crise tireotóxica, devendo ser\nimediatamente encaminhada para a unidade de terapia intensiva e iniciada terapia com\nglicocorticoides em altas doses.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262131","number":"262131","sourceNumber":"262131","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. Tendo em vista a principal hipótese diagnóstica, essa é uma\ndoença autoimune na qual TRAB estimula a produção e a liberação de hormônios tireoidianos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262132","number":"262132","sourceNumber":"262132","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. A doença\nde Graves é a principal hipótese diagnóstica e é a\nsegunda principal causa de hipertireoidismo, tendo os nódulos autônomos como a causa principal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262133","number":"262133","sourceNumber":"262133","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. Betabloqueadores constituem-se em um dos tratamentos para\ncontenção de sintomas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262134","number":"262134","sourceNumber":"262134","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. Tabagismo constitui fator de risco para desenvolvimento da\ndoença de Graves.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262135","number":"262135","sourceNumber":"262135","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 36 anos de idade apresenta queixas de palpitação, tremores nas\nmãos e insônia. Relata que perdeu cerca de\n16 kg em três meses, mesmo tendo percebido\naumento da fome. Ao exame físico, a paciente encontra-se lúcida, com tremor, FC = 116 bpm; FR =\n14 irpm, SatO2 = 98% com aumento do volume cervical e temperatura axilar = 36,3 °C. Ela nega\ncomorbidades ou uso de medicações e suplementos. De antecedentes pessoais, refere apenas ser\ntabagista, fazendo uso de meio maço de cigarros ao dia. Em razão da queixa de palpitação da\npaciente, é feito um eletrocardiograma que revela uma taquicardia sinusal, sem outras alterações.\n\nConsiderando a principal hipótese diagnóstica desse caso clínico e os conhecimentos médicos\ncorrelatos, julgue o item a seguir. Caso a paciente estivesse grávida, entre as drogas\nantitireoidianas, o metimazol deveria ser usado no primeiro trimestre e o propiltiouracil passaria a\nser a droga de escolha a partir do segundo trimestre.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262142","number":"262142","sourceNumber":"262142","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Apesar de grave, o quadro da paciente\nnão tem mortalidade elevada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262143","number":"262143","sourceNumber":"262143","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. O tratamento deve ser feito com medidas\nde suporte, aquecimento do corpo e uso de hormônio tireoidiano.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262144","number":"262144","sourceNumber":"262144","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. O quadro apresentado geralmente é\nmais comum em mulheres e idosos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262145","number":"262145","sourceNumber":"262145","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Deve ser iniciado também antibiótico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262146","number":"262146","sourceNumber":"262146","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. A infecção pulmonar da paciente,\nembora agrave o conjunto dos sintomas, não está diretamente relacionada ao quadro apresentado\npor ela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262147","number":"262147","sourceNumber":"262147","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 79 anos de idade, com quadro de tosse secretiva há cerca de três\ndias, evolui agora com alteração do nível de\nconsciência. Tem história de hipotireoidismo desde os\n20 anos de idade, em tratamento com levotiroxina, atualmente com tratamento irregular, pois a\npaciente estava se esquecendo de fazer uso da medicação. Também é hipertensa e dislipidêmica\nem uso de losartana e rosuvastatina. Ao exame físico, encontra-se sonolenta, com pele seca e fria,\nPA = 82 mmHg x 58 mmHg; FC = 50 bpm; FR = 12 irpm e SatO2 = 95%. Apresenta edema em\npernas e no rosto. Constatam-se leucócitos = 19.300 com desvio; creatinina = 1,4 mg/dL; TSH = 61\nmUI/L (VR 0,4 a 6,4); e T4 livre = 0,5 (VR 0,8 ? 1,8). A respeito desse caso clínico e com base nos\nconhecimentos médicos correlatos, julgue o item a seguir. Deve ser iniciado também corticoide.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262160","number":"262160","sourceNumber":"262160","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. A tireoidite de\nHashimoto é a segunda causa mais frequente, de acordo com o quadro da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262161","number":"262161","sourceNumber":"262161","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. O excesso de\niodo pode causar hipotireoidismo transitório decorrente do efeito Wolff-Chaikoff, o que\njustificaria o\ncaso da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262162","number":"262162","sourceNumber":"262162","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. Durante a\ninvestigação, deve-se dosar anti-TPO e anti-Tg, esta última menos comum. Altos níveis de de\n\nanti-TPO indicam Hashimoto, mas não é patognomônico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262163","number":"262163","sourceNumber":"262163","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. Os valores de\nreferência do TSH não sofrem influência da idade da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262164","number":"262164","sourceNumber":"262164","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. A irregularidade\nmenstrual pode ser causada por alteração da função tireoidiana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-262165","number":"262165","sourceNumber":"262165","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 33 anos de idade comparece a consulta com queixa de indisposição,\nsonolência, queda de cabelo, unhas\nquebradiças e retenção hídrica, e leva os exames solicitados\npor sua ginecologista, pois apresentava irregularidade menstrual. Os exames mostram TSH = 14\nmUI/mL e T4L = 0,54 ng/dL. Ao exame físico, verificaram-se pele seca, FC = 62 bpm, FR = 14 irpm,\ne SatO2 = 100%. A paciente tem discreto aumento do volume cervical. A respeito desse caso\nclínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. O tratamento\ndeve ser feito com levotiroxina, na dose inicial de 1 mcg por quilo da paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-250085","number":"250085","sourceNumber":"250085","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A insuficiência adrenal é um distúrbio caracterizado por alteração da função\nadrenocortical normal. Considerando essa\ninformação, julgue o item a seguir. Hiponatremia e\nhipercalemia são achados laboratoriais clássicos na insuficiência adrenal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-255680","number":"255680","sourceNumber":"255680","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 65 anos de idade está investigando uma massa cervical. Na consulta,\ndescobre que apresenta um tumor de tireoide. O exame anatomopatológico dela demonstra\nneoplasia folicular. Não há indícios de metástases. Além disso, a paciente apresentava hipertensão\nsecundária. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Em geral, a cirurgia é o modo apropriado para o tratamento desse tipo de tumor.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-255681","number":"255681","sourceNumber":"255681","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 65 anos de idade está investigando uma massa cervical. Na consulta,\ndescobre que apresenta um tumor de tireoide. O exame anatomopatológico dela demonstra\nneoplasia folicular. Não há indícios de metástases. Além disso, a paciente apresentava hipertensão\nsecundária. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Tumores foliculares geralmente são uninodulares quando comparados a papilíferos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-255753","number":"255753","sourceNumber":"255753","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma gestante de 12 semanas vai a consulta assintomática. Apresenta sorologias\nnegativas do primeiro trimestre, um TSH de\n6,25 mU/L (VR 0,3 e 4,0 mU/L) e um T4 livre de 0,9\nmU/L. Seu anti-TPO era positivo (3x acima do valor da normalidade). Acerca desse caso clínico e\ncom base nos conhecimentos médicos correlatos, julgue o item a seguir. Essa gestante apresenta\nrisco aumentado de pré-eclâmpsia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-211923","number":"211923","sourceNumber":"211923","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 32 anos de idade, apresenta achado incidental de nódulo 0,8 cm no\nlobo direito da tireoide, ao realizar ecografia cervical. A punção aspirativa por agulha fina (PAAF)\nmostra citologia compatível com Bethesda VI. A respeito desse caso clínico e considerando os\nconhecimentos médicos correlatos, no que concerne às patologias de tireoide, assinale a\nalternativa correta.","options":{"A":"A tireoidectomia parcial é uma opção de tratamento cirúrgico adequado para a patologia dessa\npaciente.","B":"Uma das desvantagens da tireoidectomia parcial são as taxas mais altas de hipocalemia.","C":"A punção aspirativa por agulha fina (PAAF) tem alta sensibilidade e especificidade para\nconfirmar patologia benigna de tireoide.","D":"A lobectomia seria uma opção terapêutica para essa paciente.","E":"O principal nervo lesado na tireoidectomia é o nervo vago."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-179182","number":"179182","sourceNumber":"179182","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Assinale a alternativa que apresenta a patologia que acomete indivíduos acima de\ncinquenta anos de idade, principalmente\nmulheres, devido ao uso de hipolipemiantes nesses casos\nassociar-se ao risco elevado de miopatia.","options":{"A":"diabetes","B":"hipertensão arterial","C":"angina instável","D":"hipotireoidismo","E":"obesidade mórbida"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-179168","number":"179168","sourceNumber":"179168","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Assinale a alternativa que apresenta a maior possibilidade de carcinoma diferenciado\nda tireoide, com indicação de realização de\npunção guiada por ultrassonografia, em paciente com\ndiagnóstico de doença nodular tireoidiana.","options":{"A":"TSH elevado e hipofunção por cintilografia","B":"TSH elevado e baixa ecogenicidade ecográfica","C":"TSH normal ou baixo e hiperfunção por cintilografia","D":"TSH baixo e nódulos impalpáveis detectados por ultrassom","E":"TSH baixo e nódulos múltiplos"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-179203","number":"179203","sourceNumber":"179203","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um RN do sexo feminino apresenta sinais de virilização da genitália externa, traduzida\npor aumento de clitóris, fusão labial e formação\nde seio urogenital. Nessa situação hipotética, o\nprincipal distúrbio metabólico a ser monitorado será a:","options":{"A":"Hipoglicemia.","B":"Hipopotassemia.","C":"Hiponatremia.","D":"Hipocalcemia.","E":"Hipomagnesemia."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-179208","number":"179208","sourceNumber":"179208","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 46 anos de idade foi submetida a uma avaliação geral de saúde\ndevido à queixa de fraqueza e fadigas\nfrequentes. Nega comorbidades prévias, alcoolismo,\ntabagismo e uso de drogas ilícitas. Ao exame físico, não apresentava alterações dignas de nota. À\navaliação laboratorial, foi evidenciado cálcio sérico de 12,1 mg/dl (8,4 a 10,4 mg/dl), fosfato\nsérico\nde 1,8 ml/dl (2,5 a 4,8 mg/dl) e cloreto sérico de 104 mmol/L. O hemograma, o restante da\navaliação laboratorial, o EAS, a radiografia de tórax e o eletrocardiograma de doze derivações\nvieram normais. Com base nesse caso hipotético, assinale a alternativa CORRETA:","options":{"A":"O diagnóstico da paciente é doença de Paget e a confirmação diagnóstica pode ser realizada\npela presença de PTHi sérico reduzido.","B":"É importante solicitar uma amostra de urina de 24 horas e, em caso de baixa concentração de\ncálcio urinário, pensar na hipótese de Hipercalcemia Hipocalciúrica Familiar Benigna (HHFB) e\nindicar paratireoidectomia.","C":"A paratireoidectomia é o melhor tratamento para a paciente e deverá ser realizada quando seu\nnível sérico de cálcio atingir 15 mg/dl.","D":"As glândulas paratireoides estão situadas na face posterior da tireoide, não sendo\nrecomendados os exames de imagem para localização pré-operatória.","E":"Na presença de PTH elevado e na ausência de padrão familiar de hipercalcemia, estão\nindicadas a localização e a exploração cirúrgica das paratireoides."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-154398","number":"154398","sourceNumber":"154398","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A. A. C. 78 anos de idade, sexo feminino, comparece ao ambulatório com queixa de\nrouquidão progressiva há três meses. Refere que associadamente vem apresentando quadro de\ntosse com hemoptoico, dispneia e disfagia para sólidos, inclusive se alimentando no momento com\nalimentos liquidificados. Negou perda ponderal importante nos últimos seis meses, assim como\noutras queixas. Faz uso irregular de levotiroxina 88 mcg há 10 anos. Clinicamente é percebido\naumento difuso da tireoide de aspecto endurecido e com aparente nodulação que segue na direção\ndo estreito torácico, sendo os linfonodos cervicais palpáveis e sem alterações. Pela\nultrassonografia\ncervical, solicitada por outro clínico, observa-se parênquima heterogêneo com múltiplos pequenos\nnódulos, grande nodulação de crescimento expansivo em direção ao tórax, com aspecto misto e\ncom trama vascular periférica aumentada e medindo 12 cm no maior eixo. Acerca do caso clínico\nexposto, assinale a alternativa correta.","options":{"A":"Os sintomas de tosse com hemoptoico, dispneia e disfagia para sólidos sugerem invasão\nlocorregional e malignidade. A disfonia\nrelatada corresponde ao encarceramento do nervo laríngeo\ncolateral, responsável pela inervação da musculatura das pregas vocais.","B":"A hipercalcitoninemia está associada à disseminação dos carcinomas papilar e folicular de\ntireoide, podendo provocar manifestações a distância, como prurido, rubores e diarreia.","C":"No restreamento dos módulos tireoidianos aqueles que apresentam diâmetro máximo maior que\n1,0 cm e menor que 1,5 cm são elegíveis para biópsia por aspiração com agulha fina.\nEstatisticamente, 20% dessas biópsias produzem material citológico adequado, mas\ndiagnosticamente indeterminado. Para nódulos com essas características, considera-se que a\nrespectiva natureza histológica é maligna, sendo impositiva a realização de cirurgia.","D":"O carcinoma medular da tireoide origina-se das células C derivadas das cristas neurais, sendo\nclassificado como tumor epitelial com características neuroendócrinas. As células C têm atividade\nbiossimétrica diversa e secretam entre outros calcitonina e antígeno e carcinoembriogênio (CEA)\nimportantes marcadores séricos desse tipo histológico.","E":"A biópsia por aspiração com agulha fina é o exame mais preciso para excluir ou confirmar a\n\ndoença maligna em pacientes que apresentam nódulo suspeito e níveis de TSH normais. A\nultrassonografia cervical não é necessária antes da biópsia, mesmo considerando que o respectivo\nuso auxilia a definir precisamente o tamanho da lesão, se tem natureza estática ou sólida e se há\nnódulos adicionais."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-152125","number":"152125","sourceNumber":"152125","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino, 20 anos de idade, relata que, há três semanas, está com\nhipertensão refratária à terapêutica medicamentosa otimizada. Refere que apresenta cansaço\nextremo durante o dia, além de palpitações, cefaleia e sudorese. No momento da consulta, sua\npressão é de 160 x 100 mmHg. Foram solicitadas catecolaminas urinárias que apresentaram valor\nacima da normalidade. Considerando esse caso clínico, julgue o item a seguir. Feocromocitoma\nassociado à neoplasia endócrina múltipla 2A tem relação com carcinoma medular de tireoide.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-135012","number":"135012","sourceNumber":"135012","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No próximo item é apresentado um caso clínico seguido de uma assertiva a ser julgada.\nUma criança do sexo masculino de nove anos de idade foi levada pela mãe ao serviço médico por\napresentar nódulo no pescoço. Ao palpar a tireoide da criança, o médico observou um nódulo\nendurecido no lobo direito. Os exames laboratoriais revelaram dosagem de hormônios tireoidianos\nnormais. A cintilografia e a ultrassonografia da tireoide resultaram, respectivamente, em nódulos\nhipocaptante (frio) e nódulo sólido de 12 mm de diâmetro. A mãe da criança relatou que ela e a tia\nmaterna do paciente apresentaram tumores no pâncreas e na tireoide. Nesse caso, todos os\nelementos clínicos e de imagem não indicam a possibilidade de carcinoma da tireoide.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-105531","number":"105531","sourceNumber":"105531","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Assinale a alternativa que apresenta a afecção patológica que melhor se relaciona com\na seguinte descrição: \"fenômeno imunológico\nque resulta na formação de complexo imune e de\ncomplemento na membrana basal das células foliculares e que leva a alterações da função da\ncélula tireoidiana e promove a produção de anticorpos microssomais tireóideos\".","options":{"A":"Tireoidite de Hashimoto.","B":"Doença de Graves.","C":"Doença de Plummer.","D":"Tireoidite de Riedel.","E":"Tireoidite supurativa aguda."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-88722","number":"88722","sourceNumber":"88722","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Julgue o item seguinte com relação ao hipotireoidismo. Mesmo que ocorra uma melhora\nclínica de paciente com hipotireoidismo após o período de duas a três semanas de terapêutica,\nrecomenda-se a medida do TSH sérico depois de seis semanas de início do tratamento regular\npara uma nova reavaliação e subsequente reajuste de dose, se necessário.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-88731","number":"88731","sourceNumber":"88731","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Julgue o item seguinte com relação ao hipotireoidismo. Pacientes cujo hipotireoidismo é\nresultante de tireoidite crônica autoimune podem necessitar de doses mais altas de levotiroxina\npara a normalização do quadro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-52594","number":"52594","sourceNumber":"52594","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Julgue o item subsequente, relativo a afecções que podem acometer a tireoide. O\ncarcinoma anaplásico, forma mais agressiva de câncer na tireoide, representa menos de 1% das\ndoenças malignas dessa glândula.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-45717","number":"45717","sourceNumber":"45717","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma mulher com 69 anos de idade apresentou uma massa na região anterior do\npescoço de crescimento rápido (seis meses) ,\nrouquidão e linfadenopatia cervical. Um exame de\nimagem mostrou tratar-se de tumoração da glândula tireoide com invasão da traqueia , mas uma\nbiópsia (punção aspirativa com agulha fina ou incisional) é indispensável para orientar a\nterapêutica. Nesse caso, o diagnóstico mais provável é carcinoma:","options":{"A":"Anaplásico.","B":"Medular.","C":"De Hurthle.","D":"Folicular.","E":"Papilífero"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-27542","number":"27542","sourceNumber":"27542","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A tireoidite de Riedel pode se associar com uma das afecções citadas abaixo.\nAssinale-a.","options":{"A":"Colangite esclerosante.","B":"Ginecomastia.","C":"Tumor retroperitonial.","D":"Insulinoma.","E":"Esofagite de refluxo."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-13841","number":"13841","sourceNumber":"13841","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Considerando o quadro clínico de uma paciente de 28 anos de idade que possui nódulo\ntireoidiano de 1,5 cm com diagnóstico de carcinoma bem diferenciado, assinale a opção correta.","options":{"A":"Se essa paciente tiver história de exposição à radiação, o principal diagnóstico será de câncer\nanaplásico de tireoide.","B":"Devido à idade dessa paciente, o carcinoma folicular é o mais provável diagnóstico.","C":"Na ausência de linfonodos cervicais palpáveis, essa paciente poderá ser submetida à\nnodulectomia tireoidiana.","D":"Caso essa paciente seja portadora de carcinoma papilar, ela terá melhor prognóstico em relação\naos outros tipos bem diferenciados.","E":"A cintilografia de tireoide poderá esclarecer qual tipo de carcinoma que essa paciente possui."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-352369","number":"352369","sourceNumber":"352369","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um homem de 55 anos foi encaminhado ao ambulatório de Cirurgia devido a uma\nalteração abdominal identificada. Anteriormente,\nestava em boa saúde, mas começou a\nexperienciar fraqueza muscular generalizada de forma insidiosa, ocasionalmente acompanhada por\ncâimbras. Além disso, relata que sua urina, por vezes, apresenta uma coloração acastanhada. Os\nexames laboratoriais revelaram uma urina de tipo I com presença de hemossiderinúria e níveis de\ncreatina fosfoquinase de 2.000 U/L (valor de referência: 22 - 334 U/L). Uma anomalia na imagem\nabdominal está evidente na seta e na cabeça de seta na figura abaixo. Considerando o quadro\nclínico hipotético apresentado, julgue o item a seguir. Na condição apresentada, dependendo da\nrapidez com que ocorre o desequilíbrio hidroeletrolítico predominante, é possível que se desenvolva\numa paralisia ascendente, que se assemelha à Síndrome de Guillain-Barré.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-352368","number":"352368","sourceNumber":"352368","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um homem de 55 anos foi encaminhado ao ambulatório de Cirurgia devido a uma\nalteração abdominal identificada. Anteriormente,\nestava em boa saúde, mas começou a\nexperienciar fraqueza muscular generalizada de forma insidiosa, ocasionalmente acompanhada por\ncâimbras. Além disso, relata que sua urina, por vezes, apresenta uma coloração acastanhada. Os\nexames laboratoriais revelaram uma urina de tipo I com presença de hemossiderinúria e níveis de\ncreatina fosfoquinase de 2.000 U/L (valor de referência: 22 - 334 U/L). Uma anomalia na imagem\nabdominal está evidente na seta e na cabeça de seta na figura abaixo. Considerando o quadro\nclínico hipotético apresentado, julgue o item a seguir. Mutações somáticas do trocador no gene do\ncanal de potássio pode ser a causa de quase metade dos casos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-352367","number":"352367","sourceNumber":"352367","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um homem de 55 anos foi encaminhado ao ambulatório de Cirurgia devido a uma\nalteração abdominal identificada. Anteriormente,\nestava em boa saúde, mas começou a\nexperienciar fraqueza muscular generalizada de forma insidiosa, ocasionalmente acompanhada por\ncâimbras. Além disso, relata que sua urina, por vezes, apresenta uma coloração acastanhada. Os\nexames laboratoriais revelaram uma urina de tipo I com presença de hemossiderinúria e níveis de\ncreatina fosfoquinase de 2.000 U/L (valor de referência: 22 - 334 U/L). Uma anomalia na imagem\nabdominal está evidente na seta e na cabeça de seta na figura abaixo. Considerando o quadro\nclínico hipotético apresentado, julgue o item a seguir. Após um rastreamento positivo, quando a\ntomografia de cortes finos revela uma massa unilateral com mais de 1,0 cm em pacientes com\nidade igual ou inferior a 40 anos, sem alteração contralateral de mesma topografia, a intervenção\ncirúrgica é recomendada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-352366","number":"352366","sourceNumber":"352366","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um homem de 55 anos foi encaminhado ao ambulatório de Cirurgia devido a uma\nalteração abdominal identificada. Anteriormente,\nestava em boa saúde, mas começou a\nexperienciar fraqueza muscular generalizada de forma insidiosa, ocasionalmente acompanhada por\ncâimbras. Além disso, relata que sua urina, por vezes, apresenta uma coloração acastanhada. Os\nexames laboratoriais revelaram uma urina de tipo I com presença de hemossiderinúria e níveis de\ncreatina fosfoquinase de 2.000 U/L (valor de referência: 22 - 334 U/L). Uma anomalia na imagem\nabdominal está evidente na seta e na cabeça de seta na figura abaixo. Considerando o quadro\nclínico hipotético apresentado, julgue o item a seguir. Em situações específicas, a realização de\ncateterismo da veia suprarrenal pode ser necessária para confirmar a lateralização e, assim,\norientar a decisão terapêutica, que pode incluir tratamento medicamentoso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-334881","number":"334881","sourceNumber":"334881","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 35 anos de idade, assintomático, procurou atendimento médico para\nrealizar seu exame anual periódico exigido pela empresa em que trabalha. No exame físico,\nidentificou-se tireoide palpável com consistência lisa e elástica, não havendo relato de dor à\npalpação. A avaliação da função tireoidiana mostrou TSH, aumentado com T4 livre normal. Que\nachado laboratorial confirma o provável diagnóstico desse paciente?","options":{"A":"Leucocitose com desvio à esquerda","B":"Nível de T3 aumentado","C":"Nódulo hipocaptante de tireoide","D":"Presença de anticorpo antitireoperoxidase","E":"Aumento do colesterol total"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-301244","number":"301244","sourceNumber":"301244","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 53 anos de idade, obesa, portadora de diabetes mellitus tipo 2,\nprocurou atendimento médico com resultado de\nexame laboratorial mostrando valor sérico reduzido\nde 25 hidroxi-vitamina D. A paciente negou sintomas e relatou estar em uso de orlistate 120 mg\n(três vezes ao dia) há seis meses, além de metformina, 1 g ao dia, há cinco anos. Com base nesse\ncaso hipotético, considerando o posicionamento da Sociedade Brasileira de Endocrinologia e\nMetabologia, julgue os itens de 1 a 3. O orlistate utilizado pela paciente pode causar\nhipovitaminose\nD pelo aumento da degradação da vitamina D e de seus metabólitos ao ativar as enzimas\nlisossomais hepáticas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-301245","number":"301245","sourceNumber":"301245","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 53 anos de idade, obesa, portadora de diabetes mellitus tipo 2,\nprocurou atendimento médico com resultado de\nexame laboratorial mostrando valor sérico reduzido\nde 25 hidroxi-vitamina D. A paciente negou sintomas e relatou estar em uso de orlistate 120 mg\n(três vezes ao dia) há seis meses, além de metformina, 1 g ao dia, há cinco anos. Com base nesse\ncaso hipotético, considerando o posicionamento da Sociedade Brasileira de Endocrinologia e\nMetabologia, julgue os itens de 1 a 3. A deficiência de vitamina D da paciente pode estar\nacompanhada da elevação da concentração sérica de paratormônio, o que aumenta o risco de\nfraturas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-301246","number":"301246","sourceNumber":"301246","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 53 anos de idade, obesa, portadora de diabetes mellitus tipo 2,\nprocurou atendimento médico com resultado de\nexame laboratorial mostrando valor sérico reduzido\nde 25 hidroxi-vitamina D. A paciente negou sintomas e relatou estar em uso de orlistate 120 mg\n(três vezes ao dia) há seis meses, além de metformina, 1 g ao dia, há cinco anos. Com base nesse\ncaso hipotético, considerando o posicionamento da Sociedade Brasileira de Endocrinologia e\nMetabologia, julgue os itens de 1 a 3. Em casos de deficiência grave de vitamina D, ocorrem\nhipercalcemia e sintomas relacionados, como náuseas, vômitos, fraqueza, anorexia e desidratação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-274590","number":"274590","sourceNumber":"274590","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Homem, 43 anos, hipertenso, com feocromocitoma suprarrenal devido a neoplasia\nendócrina múltipla 2. Nesse caso, o tratamento de escolha é a ressecção cirúrgica do tumor.\n\nQuanto ao uso dos betabloqueadores, é CORRETO afirmar:","options":{"A":"São os medicamentos de escolha para o controle da frequência cardíaca.","B":"São os medicamentos de escolha para o controle da PA antes da cirurgia.","C":"Devem ser sempre adicionados antes do uso de alfabloqueadores, isolados, para não\ndesencadearem crises hipertensivas.","D":"Sempre devem ser associados ao uso de diuréticos, para não agravar a hipotensão postural\ncausada pelos alfabloqueadores."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-263353","number":"263353","sourceNumber":"263353","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente com 20 anos de idade notou nodulação na região central do pescoço.\nProcurou atendimento médico ambulatorial, no qual\nfoi solicitada dosagem de hormônio tireoidiano\n(com resultados normais) e ultrassonografia com Punção Aspirativa por Agulha Fina (PAAF) do\nnódulo. O resultado foi nódulo de 1 cm em lobo esquerdo da tireoide, hipoecoico, de margens\nirregulares, sem calcificação. A PAAF não conseguiu distinguir entre lesão maligna ou benigna\n(Bethesda IV). O resultado do Perfil de Expressão Gênica (PEG) indicou suspeita para malignidade.\nA conduta médica adequada para esse caso é:","options":{"A":"Observar clinicamente e repetir ultrassonografia a cada 3 meses.","B":"Repetir ultrassonografia e realizar nova punção aspirativa com agulha fina.","C":"Indicar tireoidectomia total com esvaziamento cervical do lado esquerdo.","D":"Indicar cirurgia com retirada apenas do lobo esquerdo sem linfadenectomia."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-291476","number":"291476","sourceNumber":"291476","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma mulher de 30 anos de idade vem a consulta com o endocrinologista para\nacompanhamento de hipotireoidismo. Há 6\nmeses ela procurou o médico da Unidade Básica de\nSaúde próxima a sua residência devido a constipação (evacuava a cada 3 dias, com fezes\nressecadas e com dor ao evacuar). A paciente era sedentária e apresentava erros alimentares\nevidentes, com baixa ingesta de água durante o dia e pouco consumo de frutas e verduras. O\nmédico orientou ajustes na alimentação, ingesta hídrica e necessidade de atividade física regular,\nassim como dosagem de TSH e T4 livre. Após 2 meses a paciente retornou, tendo aderido às\nrecomendações, resultando na solução do quadro de constipação (evacuava diariamente, sem dor,\ncom fezes bem formadas), contudo, os exames laboratoriais demonstraram: TSH=5,5mUI/mL (valor\nde referência: 0,4 a 4, 5mUI/mL) e T4 livre =1,0 (valor de referência 0,7 a 1,8 ng/dL). O médico\nrepetiu os exames que indicaram TSH = 5,3mUI/mL (valor de referência: 0,4 a 4, 5mUI/mL) e T4\nlivre = 1,1 (valor de referência 0,7 a 1,8 ng/dL). Diante da persistência dos exames alterados, o\nmédico prescreveu levetiroxina 50mcg/dia e encaminhou ao especialista. Durante a consulta com o\nendocrinologista, a paciente está assintomática, com tireoide não palpável e índice de massa\ncorpórea 22kg/m², contudo, não havia iniciado a levotiroxina, pois possuía receio de possíveis\nefeitos adversos. Considerando o que foi apresentado, o endocrinologista deve","options":{"A":"Insistir com o uso da levotiroxina, pois trata-se de um caso de hipotireoidismo primário.","B":"Insistir com o uso da levotiroxina, pois trata-se de um caso de hipotireoidismo secundário.","C":"Orientar não usar a levotiroxina, pois trata-se de um caso de hipotireoidismo subclínico.","D":"Iniciar a levotiroxina apenas após realizar cintilografia, para confirmação do diagnóstico."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-273336","number":"273336","sourceNumber":"273336","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 45 anos com nódulo tireoidiano de 1,5 cm apresenta um resultado da\nPAF de ?tumor folicular?. Assinale a\nresposta correta:","options":{"A":"Trata-se de um tumor benigno e o tratamento deve ser conservador.","B":"Deverá ser operada já que se trata de um tumor maligno.","C":"Trata-se de um tumor maligno mas o tratamento não é cirúrgico.","D":"Deverá ser operada e o diagnóstico de benigno ou maligno será definido pela peça cirúrgica."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-291494","number":"291494","sourceNumber":"291494","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 26 anos de idade, usou pílula contraceptiva por 6 anos e interrompeu há cerca\nde 9 meses. Desde então, menstruou apenas 2\nvezes e está há 4 meses em amenorreia. Nega\nfogachos, acne, hirsutismo ou ressecamento vaginal. Ao exame físico: bom estado geral,\nhemodinamicamente estável, mamas com glactorreia bilateral, sem nódulos palpáveis. Útero de\ntamanho normal e anexos não palpáveis. Beta-hCG negativo. Para elucidação diagnóstica, deve-se\nsolicitar dosagem de","options":{"A":"estradiol.","B":"progesterona.","C":"prolactina.","D":"testosterona."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-291509","number":"291509","sourceNumber":"291509","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 38 anos foi internada na enfermaria de clínica médica de hospital\nuniversitário de ampla complexidade, em\nfunção de quadro de fibrilação atrial paroxística com alta\nresposta ventricular, sem instabilidade hemodinâmica, mas associada a queixas recentes de\nemagrecimento não intencional, irritabilidade e tremores finos de extremidades. Na anamnese\ndirigida, a paciente confirmava a presença de intolerância ao calor, fadiga, fraqueza, amenorreia e\nhiperdefecação. Ao exame físico, além da taquiarritmia, foram observados bócio difuso (com sopro\nà ausculta local), exoftalmia, tremores palpebrais frequentes, mixedema pré-tibial e sobre o hálux\ndireito, hipocratismo digital e pele quente e úmida. Administradas duas doses sequenciais, com\nintervalos de 5 minutos, de metoprolol intravenoso (5 mg), após redução da frequência cardíaca,\nocorreu reversão da arritmia para o ritmo sinusal. Solicitados exames complementares, resultados\nrevelaram TSH < 0,004 mUl/L (valor de referência: 0,5 a 4,5 mUl/L) e T4 livre = 4,2 ng/dL (valor de\nreferência: 0,9 a 2,0 ng/dL). Além de ser mantido o tratamento com beta-bloqueador, considerando\no fato de a paciente nunca ter sido previamente tratada de sua doença, a equipe médica optou por\ninstituir terapêutica direcionada à inibição da função da enzima tireoperoxidase, reduzindo a\noxidação e organificação do iodo na tireoide, além de promover a redução dos níveis de\nautoanticorpos circulantes. A intervenção terapêutica instituída nesse sentido foi","options":{"A":"radioiodo.","B":"dexametasona.","C":"metimazol.","D":"colestiramina."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-263431","number":"263431","sourceNumber":"263431","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma mulher com 55 anos de idade, previamente hígida, é admitida em hospital após\nepisódio de síncope. Apresenta bradicardia sinusal, discreta hipertensão arterial sistêmica e edema\npalpebral bilateral. Nota-se um aumento difuso da tireoide que a paciente não havia percebido até\nentão. Não há rouquidão, disfagia nem alteração recente de peso. Ademais, não apresenta\nhistórico familiar de câncer. Um estudo ultrassonográfico da tireoide mostra 3 nódulos de bordas\nregulares, parcialmente císticos, com componente sólido isoecoico, sem calcificações, de 0,4 cm,\n0,6 cm e 0,8 cm. Não há linfadenopatia cervical. O exame revelou TSH = 17,2 mUI/mL (valor de\nreferência = 0,3 a 5,0 mUI/mL). Nesse caso, a abordagem adequada para com a paciente é","options":{"A":"solicitar T3 total e T4 livre e cintilografia da tireoide antes de definir o tratamento.","B":"prescrever levotiroxina e realizar acompanhamento clínico e ultrassonográfico dos nódulos.","C":"prescrever levotiroxina e dosar anti-tireoide peroxidase para definir a abordagem dos nódulos.","D":"solicitar T4 livre e punção aspirativa com agulha fina do maior nódulo antes de definir o\ntratamento."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-244459","number":"244459","sourceNumber":"244459","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 42 anos de idade é submetida a tireoidectomia total, em razão de\nnódulo, com punção aspirativa com agulha fina (PAAF) compatível com tumor indiferenciado de\ntireoide. No segundo dia pós-operatório, refere que, ao medir a pressão arterial, passou a\napresentar espasmos na musculatura da mão. Acerca desse caso clínico, assinale a alternativa\ncorrespondente ao achado descrito pela paciente e aos cuidados que se devem ser seguidos.","options":{"A":"Sinal de Trousseau; solicitar cálcio e ECG.","B":"Sinal de Hertoghe; solicitar TSH e T4.","C":"Sinal de Chvostek; solicitar cálcio sérico.","D":"Sinal de Von Graefe; solicitar potássio e sódio séricos.","E":"Sinal de Dalrymple; solicitar T4 livre e T3."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-244460","number":"244460","sourceNumber":"244460","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 17 anos de idade busca atendimento por causa da presença de massa\ncervical em linha média. Ao exame, apresenta aspecto cístico. A respeito desse caso e com base\nnos conhecimentos correlatos, assinale a alternativa correta.","options":{"A":"O tratamento inicial é o procedimento conhecido como cirurgia de Sistrunk, independentemente\nda presença de infecção.","B":"Paralisia temporária unilateral da prega vocal é uma complicação frequente do tratamento desse\ntipo de patologia.","C":"Caso confirmada a hipótese de cisto tireoglosso no transoperatório, a retirada do hioide não\ninflui\nno risco de recidiva no pós-operatório.","D":"Bócio mergulhante deve ser considerado, nesse caso, a idade do paciente.","E":"Deve-se avaliar a tireoide, seja ao exame físico, seja com métodos de imagem para evitar\ncomplicações no pós-operatório."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-244476","number":"244476","sourceNumber":"244476","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 42 anos de idade, com história de melanoma metastático em remissão\nda doença após início do tratamento\noncológico, procurou o serviço do pronto-socorro com um\nquadro de náusea, vômitos e ansiedade intratáveis. Ela havia iniciado terapia dupla com\nnivolumabe e ipilimumabe há um mês, e sua última dose foi há uma semana. Ela negou uso de\nálcool ou drogas ilícitas. Na apresentação, estava febril a 38 ºC, com FC = 146 bpm, FR = 18 irpm,\nSatO2 = 98% em ar ambiente e PA = 140 mmHg x 100 mmHg. Ao exame, a paciente estava\nagitada e extremamente ansiosa, com exoftalmia leve, mas acordada, alerta e orientada, sem\ndistensão venosa jugular, sem edema periférico, com exame cardíaco normal e sons claros ao\nexame pulmonar. O hemograma inicial completo, o painel metabólico básico, a lipase, a função\nrenal, o ácido úrico e o exame de urina estavam normais. O teste de gravidez foi negativo. As\nhemoculturas foram obtidas e mostraram-se negativas às 48 horas. Um eletrocardiograma mostrou\ntaquicardia sinusal. Os testes de função tireoidiana foram: TSH = 0,062 µU/mL (VR = 0,5 a 5,4) e\nT4 livre = 16,4 ng/dL (variação normal de 1,5 a 3,5 ng/dL). Um ultrassom da tireoide revelou\nheterogeneidade difusa da tireóide consistente com tireoidite inespecífica. Acerca desse caso\nclínico e tendo em vista os conhecimentos médicos correlatos, assinale a alternativa correta.","options":{"A":"A paciente manifesta quadro de choque séptico após tratamento oncológico. A sepse ocasiona\ndiminuição dos níveis séricos do hormônio tireoidiano e menor liberação de catecolaminas.","B":"A paciente tem quadro de reação de liberação de citoquinas, induzida pelos inibidores de TNF\nalfa (ipilimumab), com supressão transitória da função tireoideana.","C":"O nivolumabe e o ipilimumab são inibidores de TNF alfa; assim, o quadro clínico da paciente é\ncompatível com síndrome de lise tumoral.","D":"As manifestações clínicas da paciente são compatíveis com um quadro de insuficiência adrenal\naguda secundária ao tratamento oncológico.","E":"A paciente apresenta quadro de tempestade tireoideana e deve iniciar com propranolol 60 mg a\ncada seis horas, para obter controle\nadequado da frequência cardíaca, hidrocortisona 100 mg a\ncada oito horas e metimazol 20 mg a cada oito horas."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-230578","number":"230578","sourceNumber":"230578","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Durante o atendimento de um paciente com Síndrome de Down e obesidade,\n\nobserva-se um resultado de TSH de 6,5. Ele já apresentou, em outros momentos da vida, elevação\ndo TSH, com normalização dos resultados em\nexames subsequentes e sempre com dosagem de\nT4 livre normal. Qual é a MELHOR conduta em relação à avaliação tireoidiana desse paciente?","options":{"A":"Encaminhar ao endocrinologista.","B":"Nova dosagem de TSH, T4 livre e pesquisa do anticorpo Antitireoperoxidase (ATPO).","C":"Iniciar levotiroxina.","D":"Parar de dosar o TSH desse paciente, já que se encontra repetidamente elevado sem impacto\nclínico e com dosagem do T4 normal."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-206097","number":"206097","sourceNumber":"206097","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Há benefício clínico com a radioiodoterapia RIT, o objetivo do tratamento é promover a\nablação de tecido remanescente do câncer da tireoide. Podemos assim apenas ACEITAR que:","options":{"A":"Esta ablação pode ser definida como a ausência de captação de radioiodo em leito tireoidiano\nem estudo cintilográfico, ou a ausência de\nníveis séricos detectáveis de tireoglobulina estimulada.","B":"Esta ablação pode ser definida como a ausência de captação de radioiodo em leito tireoidiano\nem estudo cintilográfico, mas não da ausência de\nníveis séricos detectáveis de tireoglobulina\nestimulada.","C":"Esta ablação não pode ser definida como a ausência de captação de radioiodo em leito\ntireoidiano em estudo cintilográfico, somente com a ausência de níveis séricos detectáveis de\ntireoglobulina estimulada.","D":"Esta ablação pode ser definida como a ausência de captação de radioiodo em leito tireoidiano\nem estudo cintilográfico, ou a ausência de níveis\nséricos detectáveis de tireoglobulina não\nestimulada."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-202970","number":"202970","sourceNumber":"202970","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 38 anos de idade realizou ultrassom de tireoide, no qual foi\nvisualizado um nódulo sólido de 4 cm em lobo\ndireito. Foi feita uma punção aspirativa por agulha\nfina, que mostrou uma lesão classificada como Bethesda VI. A respeito desse caso clínico, qual é a\nconduta indicada?","options":{"A":"Tireoidectomia total.","B":"Lobectomia direita e istmectomia.","C":"Lobotomia direita e istmectomia com biópsia de congelação.","D":"Acompanhamento com ultrassom a cada três meses.","E":"Terapia ablativa com iodo radioativo."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-206161","number":"206161","sourceNumber":"206161","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"É fundamental um exame físico cuidadoso com palpação da região cervical,\ncaracterização do nódulo quanto à\nconsistência, fixação a outras estruturas cervicais e avaliação da\npresença de disfonia secundária à paralisia de corda vocal. O objetivo da avaliação do nódulo\ntireoidiano é estabelecer o risco de câncer por meio de métodos que sejam acurados, precisos,\nalém de seguros e custo-efetivos. Não sendo aceito, entretanto, que:","options":{"A":"O paciente com diagnóstico de doença nodular tireoidiana deve ter a dosagem de hormônio\ntireotrófico (TSH), com o objetivo de avaliar a função tireoidiana.","B":"Na presença de níveis inferiores de hormônio tireotrófico (TSH) aos valores considerados\nnormais, recomenda-se a realização de\n\ncaptação e cintilografia com radioisótopo para investigar a possibilidade de hipofunção\ntireoidiana.","C":"A incidência de neoplasia maligna neste tipo de doença nodular tireoidiana é rara, não havendo\nindicação de realização de punção guiada pela ultrassonografia.","D":"Os níveis de TSH têm sido relacionados ao risco de câncer da tireóide em pacientes com\ndoença nodular."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-206163","number":"206163","sourceNumber":"206163","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O preparo para a terapia com radioiodo tem como objetivo aumentar a eficácia do\ntratamento do câncer da tireóide. A\nprincipal medida relacionada à eficácia é a elevação dos níveis\nde TSH. Sendo adequado considerarmos que:","options":{"A":"A redução deste hormônio estimulante pode ser obtida pela interrupção do uso de levotiroxina,\ninduzindo hipotiroidismo endógeno (causando\nelevação fisiológica do TSH), ou pela administração\nexógena de TSH recombinante humano (TSHrh).","B":"A elevação deste hormônio estimulante não pode ser obtida pela interrupção do uso de\nlevotiroxina, hipotiroidismo endógeno (causando elevação fisiológica do TSH), ou pela\nadministração exógena de TSH recombinante humano (TSHrh).","C":"A elevação deste hormônio estimulante pode ser obtida pela interrupção do uso de levotiroxina,\ninduzindo hipotiroidismo endógeno (causando elevação fisiológica do TSH), ou pela administração\nexógena de TSH recombinante humano (TSHrh).","D":"A elevação deste hormônio estimulante pode ser obtida pela interrupção do uso de levotiroxina,\ninduzindo hipertiroidismo\n\nendógeno (causando elevação fisiológica do TSH), ou pela administração exógena de TSH\nrecombinante humano (TSHrh)."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-206167","number":"206167","sourceNumber":"206167","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O Carcinoma Diferenciado da Tireóide (CDT) é a neoplasia maligna endócrina de maior\nprevalência no mundo, sendo INCORRETO o seguinte:","options":{"A":"Além do carcinoma papilífero, não podemos incluir dentro do grupo de CDT o carcinoma de\ncélulas de Hürthle.","B":"Entende-se como CDT, o tumor maligno da tireóide de origem epitelial.","C":"O carcinoma papilífero é o principal representante desta categoria.","D":"Além do carcinoma papilífero, incluem-se dentro do grupo de CDT o carcinoma folicular e o\ncarcinoma de células de Hürthle."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-206176","number":"206176","sourceNumber":"206176","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Os linfonodos cervicais aumentados são achados frequentes, muitas vezes decorrentes\nde infecções crônicas do trato respiratório\nsuperior. Parte destes nódulos é de natureza benigna,\nporém malignidade pode ser encontrada. Sendo assim, podemos aceitar que:","options":{"A":"Nos tumores diferenciados da tireóide, em especial o carcinoma papilífero, cuja disseminação\nnão é por via linfática, a presença de\nlinfonodos aumentados pode indicar acometimento\nmetastático.","B":"Nos tumores diferenciados da tireóide, em especial o carcinoma papilífero, cuja disseminação é\npor via linfática, a presença de linfonodos aumentados pode indicar acometimento por contiguidade\napenas.","C":"Nos tumores diferenciados da tireóide, em especial o carcinoma papilífero, cuja disseminação é\npor via linfática, a presença de linfonodos aumentados pode indicar acometimento metastático.","D":"Nos tumores diferenciados da tireóide, em especial o carcinoma papilífero, cuja disseminação é\npor via linfática, a presença de linfonodos diminuídos pode indicar acometimento metastático."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-212129","number":"212129","sourceNumber":"212129","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Caso clínico: paciente sem doenças prévias; idade: 19 anos; sexo: feminino; sinais e\nsintomas: tremores nas extremidades, nervosismo e palpitações taquicárdicas (FC = 15 bpm; PA =\n135 mmHg x 65 mmHg, pulsos radiais palpáveis e arrítmicos). Avaliação cardiovascular evidenciou\nictus cordis in situ, ritmo cardíaco irregular em 2 tempos, taquicárdico, bulhas normofonéticas, sem\nsopros ou ruídos adventícios. Na palpação, percebeu-se glândula tireoide indolor, levemente\naumentada e não nodular. Resultado de dosagem séricas: TSH (tirotrofina) = 0,05 mU/L (valores de\nreferência = 0,4-4,2 mU/L); T4 livre (tiroxina livre) = 4,0 nanogramas/dl (valores de referência =\n\n0,8-2,7 nanograma/dl); anticorpos antirreceptor de TSH (ou Trab) = 2 U/L (valor de referência < 10\nU/L); anticorpos antitireoglobulinas = positivo 1/6.400 (valores de referência não reagente <\n1/100);\ndeterminação de anticorpos antiperoxidase tireoidiana (anti-TPO) = 70 U/ml (valores de referência <\n35 U/ml). Ecodopplercardiograma = normal. Tira de ritmo eletrocardiográfico (ECG) mostrada na\nfigura a seguir (derivação D2, velocidade do papel: 25 mm/s, calibração: 1 cm= 1 mV). A respeito\ndas informações do caso clínico descrito anteriormente, julgue o item subsequente. O principal\ndiagnóstico clínico é tireoidite de Hashimoto.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/212129.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-212132","number":"212132","sourceNumber":"212132","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Caso clínico - paciente sem doenças prévias; Idade: 19 anos: sexo: feminino; Sinais e\nsintomas: tremores nas extremidades, nervosismo e palpitações taquicárdicas (FC = 15 bpm, PA\n135 mmHg x 65 mmHg, pulsos radiais palpáveis e arrítmicos); Avaliação cardiovascular evidenciou\nictus cordis in situ, ritmo cardíaco irregular em 2 tempos, taquicárdico, bulhas normofonéticas, sem\nsopros ou ruídos adventícios. Na palpação, percebeu-se glândula tireoide indolor, levemente\naumentada e não nodular. Resultado de dosagem séricas: TSH (tirotrofina) = 0,05 mU/L (valores de\nreferência = 0,4 - 4,2 mU/L); T4 livre (tiroxina livre) = 4,0 nanogramas/dL (valores de referência =\n0,8 - 2,7 nanograma/dL); anticorpos antirreceptor de TSH (ou Trab) = 2 U/L (valor de referência <\n10 U/L); anticorpos antitireoglobulinas = positivo 1/6.400 ( valores de referência não reagente <\n1/100); determinação de anticorpos antiperoxidase tireoidiana (anti-TPO) = 70 U/mL (valores de\nreferência < 35 U/mL). Ecodopplercardiograma = normal. Tira de ritmo eletrocardiográfico (ECG)\nmostrada na figura a seguir (derivação D2, velocidade do papel: 25 mm/s, calibração: 1 cm= 1 mV).\nA respeito das informações do caso clínico descrito anteriormente, julgue o item subsequente. A\nprincipal base tiofisiopatogenética da doença apresentada pela paciente do caso clínico em\nquestão e a infecção viral.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/212132.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-212125","number":"212125","sourceNumber":"212125","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Caso clínico - paciente sem doenças prévias; Idade: 19 anos: sexo: feminino; Sinais e\nsintomas: tremores nas extremidades, nervosismo e palpitações taquicárdicas (FC = 15 bpm, PA\n135 mmHg x 65 mmHg, pulsos radiais palpáveis e arrítmicos); Avaliação cardiovascular evidenciou\nictus cordis in situ, ritmo cardíaco irregular em 2 tempos, taquicárdico, bulhas normofonéticas, sem\nsopros ou ruídos adventícios. Na palpação, percebeu-se glândula tireoide indolor, levemente\naumentada e não nodular. Resultado de dosagem séricas: TSH (tirotrofina) = 0,05 mU/L (valores de\nreferência = 0,4 - 4,2 mU/L); T4 livre (tiroxina livre) = 4,0 nanogramas/dL (valores de referência =\n0,8 - 2,7 nanograma/dL); anticorpos antirreceptor de TSH (ou Trab) = 2 U/L (valor de referência <\n10 U/L); anticorpos antitireoglobulinas = positivo 1/6.400 (valores de referência não reagente <\n1/100); determinação de anticorpos antiperoxidase tireoidiana (anti-TPO) = 70 U/mL (valores de\nreferência < 35 U/mL). Ecodopplercardiograma = normal. Tira de ritmo Eletrocardiográfico (ECG)\nmostrada na figura a seguir (derivação D2, velocidade do papel: 25 mm/s, calibração: 1 cm= 1 mV).\nA respeito das informações do caso clínico descrito anteriormente, julgue o item subsequente. O\nuso de medicamento betabloqueador, como o propranolol, é recomendado para essa condição\nclínica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/212125.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-206140","number":"206140","sourceNumber":"206140","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Com relação à paralisia das cordas vocais, assinale a alternativa INCORRETA:","options":{"A":"O nervo laríngeo recorrente inerva toda a musculatura laríngea, exceto o músculo cricotireóideo,\nque é inervado pelo nervo laríngeo superior.","B":"A paralisia dos músculos laríngeos pode ocorrer a partir de uma lesão do sistema nervoso\ncentral ou, mais comumente, por comprometimento de nervo periférico (90%).","C":"No lado esquerdo, o nervo laríngeo recorrente separa-se do nervo vago no tórax e passa em\ntorno do arco aórtico ao nível do ducto\narterioso, correndo superiormente ao sulco traqueoesofágico\naté a articulação cricotireóidea.","D":"A paralisia vocal direita é mais comum que a da esquerda."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-206149","number":"206149","sourceNumber":"206149","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Hiperparatiroidismo é a terceira alteração endócrina mais comum, após o diabetes e a\ndoença tireoidea. Quanto a isso, assinale a\nalternativa INCORRETA:","options":{"A":"É caracterizada por hipersecreção de paratormônio, levando a hipercalcemia.","B":"Quando o hiperparatiroidismo é observado em casos de insuficiência renal crônica é\ndenominado hiperparatiroidismo secundário.","C":"A abordagem clássica para o tratamento cirúrgico do Hiperparatiroidismo primário é a\nexploração cervical unilateral.","D":"A Cintilografia com Tecnécio-99m Sestamibi funciona por captação mitocondrial e é um bom\nexame para localização\n\npré-operatória não invasiva da paratireoides."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-206156","number":"206156","sourceNumber":"206156","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre o Feocromocitoma, assinale a alternativa INCORRETA:","options":{"A":"Originam-se das células cromafínicas da medula adrenal ou células paraganglionares\nextramedulares.","B":"Secretam norepinefrina, epinefrina e dopamina.","C":"São bilaterais em 50% dos casos.","D":"Podem ser esporádicos ou associados a NEM2A ou doença de von Hippel-Lindau."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-177269","number":"177269","sourceNumber":"177269","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um homem de 45 anos de idade busca orientação médica. Ele relata uma mudança na\nprópria fisionomia, ao mesmo tempo em que há necessidade de que ele renove os repectivos\ndocumentos de identificação. Ele informa que, nos últimos 5 anos, iniciou uso de anti-hipertensivo e\ntem apresentado impotência sexual e diminuição da energia. No período, ele necessitou trocar os\nsapatos por números maiores. Com base nas informações apresentadas, a investigação do quadro\nclínico do referido paciente indica a solicitação de","options":{"A":"TSH e T4 livre, em função do fato de que o hipotireoidismo é uma afecção que acarreta\nalterações corpóreas e hipertensão.","B":"nível sérico de IGF-I, já que, na acromegalia, as mudanças de fisionomia e a hipertensão são\nfrequentes.","C":"cortisol livre na urina de 24 horas, em função do fato de que a síndrome de Cushing justifica as\nmudanças de fisionomia e hipertensão.","D":"nível sérico de hormônio de crescimento, já que os adenomas hipofisários acarretam\nacromegalia e mudanças como as citadas, pela\nhipersecreção de hormônio do crescimento.","E":"nível sérico de prolactina, já que a hipersecreção hipofisária causa adinamia e alteração da\nlibido\nsexual"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-177235","number":"177235","sourceNumber":"177235","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma mulher de 22 anos de idade procura um ambulatório com queixa de dificuldade de\ncontrole dos níveis pressóricos, desde que recebeu o diagnóstico de pressão alta, há 6 meses. Ela\ninforma que, desde o diagnóstico, tem seguido as recomendações dietéticas e as relacionadas aos\nhábitos de vida. Atualmente, ela está em uso de nifedipina, 20 mg, 3 vezes ao dia, associada a\nmetoprolol 100 mg ao dia, e clonidina, 0,200 mg, 3 vezes ao dia. No último mês, ela foi admitida 2\nvezes em um pronto-socorro, com crises hipertensivas, tendo apresentado melhora após uso de\ncaptopril. Ao exame físico, ela apresenta níveis pressóricos estimados em 176 mmHg x 98 mmHg e\nfrequência cardíaca de 62 bpm. Durante o citado exame, não se evidencia edema ou sopros\ncardíacos. Não foi constatada na paciente distribuição anormal de pelos na face. Ela traz diversos\nexames; entre eles, o Mapa, com valores alterados, além de um ecocardiograma, com resultado\nnormal. Evidenciou-se, na paciente, função renal normal, com creatina de 0,8 mg/dL e redução de\npotássio, mantido em 2,8 mEq/dL. O bicarbonato teve o valor medido em 30 mEq/dL. Já a glicemia\nde jejum era de 96 mg/dL. Com base nas informações do hipotético caso clínico mencionado, é\ncorreto afirmar que este se trata de hipertensão secundária a:","options":{"A":"síndrome de Cushing.","B":"doença renovascular por displasia fibromuscular.","C":"feocromocitoma.","D":"hiperaldosteronismo primário.","E":"hiperplasia suprarrenal congênita."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-154491","number":"154491","sourceNumber":"154491","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"RN a termo com IG de 38 semanas e 4 dias, peso de nascimento de 3640 g. APGAR\n8/9 recebeu alta no segundo dia de vida e aos\n16 dias comparece à segunda consulta de\npuericultura, em aleitamento materno exclusivo, com queixa de constipação. Apresenta ganho\nponderal adequado e ao exame é notado apenas icterícia. A mãe refere que a criança é \"boazinha\",\nchora pouco e está amarela desde a alta da maternidade. Diante do quadro deve-se pensar em:","options":{"A":"Galactosemia.","B":"Icterícia associada ao aleitamento materno.","C":"Atresia de vias biliares.","D":"Icterícia fisiológica persistente.","E":"Hipotireoidismo congênito."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-154509","number":"154509","sourceNumber":"154509","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Menina de 6 anos de idade, previamente hígida, é atendida pelo pediatra com história\nde pelos pubianos há 6 meses e crescimento\nacelerado. Ao exame físico identificado estágio de\nTanner M1P3 sem ambiguidade genital. Os exames laboratoriais mostram: DHEA-S de 78 ug/dL\n(VR <150 ug/dL); testosterona de 80 ng/dL (VR< 40 ng/dL); androstenediona de 300 ng/dL (VR <\n275 ng/dL) e 17-OH progesterona de 940 ng/dL (VR< 150 ng/dL). Diante do quadro clínico trata-se\nprovavelmente de:","options":{"A":"Tumor suprarrenal.","B":"Puberdade precoce isolada idiopática.","C":"Exposição exógena de androgênios.","D":"Tumor ovariano.","E":"Hiperplasia Adrenal Congênita."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-133974","number":"133974","sourceNumber":"133974","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A interpretação de resultados laboratoriais de função tireoidiana em doentes\ncriticamente enfermos apresenta dificuldades. Em\nrelação à síndrome do eutireoideo doente e de\nacordo com a Diretriz Brasileira de Hipotireoidismo - Projeto Diretrizes, assinale a alternativa\ncorreta.","options":{"A":"Medicações como corticoides e dopamina podem interferir no resultado de exames de função\ntireoidiana.","B":"Em razão da importância da ação tireoidiana em casos graves, a avaliação da função tireoidiana,\nnesses casos, deve ser feita de rotina por\nendocrinologistas.","C":"A concentração de T3 reverso costuma estar diminuída nesses pacientes, devendo se reposto\nprofilaticamente.","D":"Quando feita a análise da função tireoidiana, ela deve ser realizada com o paciente em jejum de\n48 horas para evitar fatores confundidores.","E":"Na ocasião em que é feita a análise da função tireoidiana, deve-se priorizar excepcionalmente a\navaliação do T4 total."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-133981","number":"133981","sourceNumber":"133981","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"De acordo com a Diretriz Brasileira de Hipotireoidismo, em relação à investigação de\ndiagnósticos diferenciais envolvendo hipóteses de hipotireoidismo e depressão, assinale a\nalternativa CORRETA.","options":{"A":"Pacientes deprimidos devem receber de rotina reposição de hormônios tireoidianos,","B":"O diagnóstico de hipotireoidismo clínico deve ser feito com base na relação T4 livre por T4\ntotal.","C":"O diagnóstico de hipotireoidismo subclínico deve ser considerado em pacientes deprimidos.","D":"O tratamento de hipotireoidismo é fundamentado na reposição de TSH.","E":"O tratamento de hipotireoidismo apoia-se na reposição de T4 total."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-129041","number":"129041","sourceNumber":"129041","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente com 36 anos de idade, portadora de tireoidite de Hashimoto há cinco\nanos, procurou atendimento médico após receber\nos resultados de seus exames de uma clínica de\n\"check-up\". Ela não tinha qualquer queixa de saúde, referiu mãe hipertensa e pai com câncer de\npróstata e estava em uso diário de 75 mcg de levotiroxina sódica. Sua preocupação era com o\ndiagnóstico de lúpus eritematoso sistêmico dado por facultativo. Seu exame físico não mostrou\nalterações. Ao analisar os exames complementares que a paciente havia levado, o médico\nconstatou que o exame para fator antinuclear era positivo, com descrição de padrão nuclear\npontilhado fino denso e título de 1/160. Não havia nenhuma alteração no hemograma ou nas\nprovas de atividade inflamatória. Com base nesse caso clínico hipotético, assinale a alternativa\ncorreta.","options":{"A":"O título de 1/160 confirma o diagnóstico de lúpus eritematoso sistêmico.","B":"O padrão de fluorescência nuclear indica forte probabilidade de existir hepatite autoimune.","C":"A tireoidite de Hashimoto pode explicar o fator antinuclear positivo, sem que haja qualquer outra\ndoença autoimune.","D":"O tipo de padrão de fluorescência e o elevado título sérico indicam que é muito provável que\nseja lúpus eritematoso induzido por droga (levotiroxina).","E":"A associação de autoanticorpos e a ausência de sintomas indicam que se trata de lúpus pérnio."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-129045","number":"129045","sourceNumber":"129045","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Assinale a alternativa que apresenta a complicação, a longo prazo, mais comum em\npacientes com doença de Graves tratados com iodo radioativo.","options":{"A":"Atresia de esôfago.","B":"Hipotireoidismo.","C":"Carcinoma da tireoide.","D":"Linfoma da tireoide.","E":"Infertilidade."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-111352","number":"111352","sourceNumber":"111352","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma idosa de 62 anos de idade apresenta, há um ano, sintomas de cansaço,\ndesânimo, ganho de peso, edema de membros\ninferiores e hipercolesterolemia não controlada\ncom estatinas. Dos exames a seguir, assinale o mais indicado nesse caso.","options":{"A":"Dosagem do hormônio liberador da tireotropina.","B":"Dosagem do hormônio estimulante da tireoide.","C":"Dosagem da tiroxina livre.","D":"Ecocardiograma.","E":"Eletrocardiograma."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-97809","number":"97809","sourceNumber":"97809","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma senhora com 47 anos de idade é atendida na Unidade Básica de Saúde com\nqueixa de \"caroço\" no pescoço há quatro\nmeses. À palpação da região cervical, o médico\nencontrou um nódulo de mais ou menos 4 cm, de consistência endurecida e aderido aos planos\nprofundos. Foi solicitada ultrassonografia cervical, que evidenciou nódulo tireoidiano de 4,3 cm,\ncom hipoecogenicidade, microcalcificações, ausência de halo periférico, bordas irregulares e fluxo\nintranodular. As dosagens séricas de T3, T4 e TSH foram normais. A principal hipótese diagnóstica\ne a investigação inicial são:","options":{"A":"bócio nodular tóxico; cintilografia tireoidiana.","B":"cisto do conduto tireoglosso; biópsia excisional","C":"tireoidite de Hashimoto; dosagem de anticorpos antitireoidianos.","D":"carcinoma de tireoide; biópsia por agulha fina guiada por ultrassom."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-97754","number":"97754","sourceNumber":"97754","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente com 42 anos de idade, com antecedentes de duas gestações prévias\nsem intercorrências e sem outras comorbidades,\ncomparece à Unidade Básica de Saúde com\nqueixas de aumento de volume em região cervical anterior, notado há aproximadamente 10 meses.\nNega dor local ou vermelhidão. Nega quadros semelhantes na família. No exame físico encontra-se\nem bom estado geral, corada, sem linfonomegalias cervicais. A tireoide é visível durante a\ndeglutição e, na palpação, tem dimensões aumentadas em cerca de 2 vezes, com consistência\nmais fibrosa do que a normal, é móvel e indolor e sem nódulos palpáveis. As auscultas cardíaca e\npulmonar são normais. A frequência cardíaca é de 72 bpm e a pressão arterial = 125 x 70 mmHg. A\npaciente não apresenta tremores de extremidades. A ultrassonografia da tireoide revela uma\nglândula com ecotextura heterogênea e com parênquima moderadamente hipoecoico; observam-se\náreas de hiperecogenicidade e traves fibróticas. O volume total é de 28 ml (Valor de referência = 8\n-\n14 ml). Além de solicitar dosagem de TSH e de T4 livre, a conduta adequada para essa paciente é\nsolicitar:","options":{"A":"punção aspirativa da tireoide.","B":"pesquisa de anticorpo antitireoperoxidase.","C":"dosagem de T3 livre e cintilografia da tireoide.","D":"dosagem de T3 livre e pesquisa de anticorpo antirreceptor do TSH."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-64437","number":"64437","sourceNumber":"64437","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 35 anos está em investigação de astenia crônica. Na avaliação laboratorial\nencontra-se TSH < 0,01 mcU/ml e T4 livre < 0,1 ng/ml. Dentre os abaixo, o próximo exame a ser\nsolicitado será:","options":{"A":"Cintilografia da tireoide.","B":"Anticorpo antirreceptor de tireotrofina (TRab).","C":"Anticorpo antiperoxidase.","D":"Ecografia da tireoide.","E":"Ressonância magnética da cela túrcica."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-64438","number":"64438","sourceNumber":"64438","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 38 anos, submetida à tireoidectomia subtotal por nódulo de 1,8 cm no lobo\ndireito. O laudo histopatológico confirma se tratar de um carcinoma folicular bem diferenciado. A\nconduta seguinte será:","options":{"A":"Totalização da tireoidectomia.","B":"Radioiodoterapia.","C":"Tireoidectomia subtotal à esquerda.","D":"Acompanhamento clínico com níveis de tireoglobulina.","E":"Quimioterapia."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-75546","number":"75546","sourceNumber":"75546","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher com 52 anos de idade, previamente hígida, há 3 meses queixa-se de astenia,\nsonolência e ganho de peso, constipação, além de artralgias e mialgias. Ao exame, nota-se pele\nseca e frequência cardíaca de 62 bpm, além de não apresentar sinais de artrite ou deformidades\narticulares. Os exames indicados e o principal diagnóstico a serem considerados são,\nrespectivamente:","options":{"A":"CPK e aldolase; fibromialgia.","B":"TSH e T4 livre; hipotireoidismo primário.","C":"Cálcio sérico e PTH; hiperparatireoidismo.","D":"TSH e T4 livre; hipotireoidismo secundário.","E":"Cortisol e potássio séricos; insuficiência adrenal."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-137595","number":"137595","sourceNumber":"137595","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um mulher de 55 anos de idade procura o médico da Unidade Básica de Saúde\n(UBS) para realizar uma consulta. A\npaciente está assintomática. Durante o exame físico, o\nmédico identificou nódulo palpável no lobo esquerdo da tireóide. Solicitou ultrassonografia,\nque mostrou nódulo bem circunscrito de 1,8 cm em seu maior diâmetro, localizado no pólo\nsuperior esquerdo da tireóide e ausência de linfonodomegalia. Indicou, então, punção aspi rati va\ncom agul ha fi na. O exame histopatológico revelou alterações celulares sugestivas de\ncarcinoma papilífero de tireoide. A paciente foi submetida a tireoidectomia e o exame\nanátomo-patológico confirmou o diagnóstico de carcinoma papilífero de tireoide, de 1,8 cm, sem\ninvasão capsular , bem diferenciado, sem extensão local ou intratireoideana. Além da\nreposição hormonal, a conduta nessa paciente implica a","options":{"A":"aplicação de radioterapia.","B":"aplicação de quimioterapia.","C":"aplicação de Iodo 131.","D":"associação de radioterapia e quimioterapia.","E":"associação de Iodo 131 e quimioterapia."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-351611","number":"351611","sourceNumber":"351611","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um indivíduo do sexo masculino, 65 anos de idade, apresenta uma massa suprarrenal\ndireita acidental ao exame tomografia\ncomputadorizada (TC), durante a investigação devido a um\ntraumatismo. Ele não tem história de hipertensão nem quaisquer condições malignas. O exame\nfísico é negativo. A investigação sanguínea demonstra eletrólitos e metanefrinas plasmáticas\nnormais. O cortisol livre urinário está normal e o teste de supressão de dexametasona, por uma\nnoite, em doses baixas, mostrou um nível baixo de cortisol na manhã seguinte. O exame TC\ndemonstrou uma massa heterogênea, de forma irregular, de 6cm. Assinale a alternativa que\napresenta CORRETAMENTE a próxima providência apropriada no tratamento desse paciente.","options":{"A":"Efetuar uma biópsia com agulha da massa suprarrenal sob orientação TC.","B":"Repetir o exame TC em 6 meses.","C":"Efetuar uma adrenalectomia aberta.","D":"Administrar mitotane ao paciente."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-351591","number":"351591","sourceNumber":"351591","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"É CORRETO afirmar que a mais frequente complicação associada ao pós-operatório do\ntratamento cirúrgico do câncer de tiroide é:","options":{"A":"Infecção.","B":"Granuloma de fio cirúrgico.","C":"Seroma.","D":"Hipocalcemia."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-346837","number":"346837","sourceNumber":"346837","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 27 anos queixa-se de dor na região cervical anterior e febre há 8 dias. Nega\ncomorbidades conhecidas e não faz uso de medicamentos. Ao exame físico, PA: 140x86mmHg,\nFC: 118bpm, FR: 18ipm, SPO? 98% (aa), Tax: 37,9°C. Apresenta tireoide de volume aumentado,\nquente e dolorosa a palpação. Os exames respiratório, cardiovascular e abdominal não revelam\noutras anormalidades. O exame neurológico revela tremor postural e cinético das extremidades\nsuperiores e hiperreflexia difusa. Exames de laboratório: TSH 0,03mU/L (VR 0,4 a 4,5mU/L); T4L\n2,7ng/dL (VR 0,7 a 1,8ng/dL); leucócitos 15.980/mm3 (VR 4.000 a 11.000/mm³); neutrófilos 11.540\n(VR 1.500-7.600/m³); VHS 84mm (VR > 20mm). Assinale a alternativa que apresenta a prescrição\nMAIS adequada para essa paciente.","options":{"A":"Metimazol e dipirona.","B":"Propiltiouracil e betabloqueador.","C":"Antibiótico e anti-inflamatório não esteroidal.","D":"Anti-inflamatório não esteroidal e betabloqueador."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-336256","number":"336256","sourceNumber":"336256","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 40 anos, apresenta nódulo em lobo direito da tireoide de 20 mm, cuja PAAF\nevidenciou carcinoma papilífero. Tendo em vista o diagnóstico obtido pela PAAF e de acordo com\nseus conhecimentos acerca do tema tumores diferenciados da tireoide, assinale a alternativa\ncorreta:","options":{"A":"O tratamento cirúrgico proposto é de tireoidectomia parcial por tratar-se de microcarcinoma\npapilífero seguida de radioiodoterapia, sendo indicado\no seguimento com a USG cervical.","B":"O tratamento cirúrgico proposto é tireoidectomia total devendo ser solicitado no pós operatório a\ndosagem da tireoglobulina e deve ser prescrito no pós operatório doses adequadas da levotiroxina\na fim de manter o TSH suprimido e o paciente em um quadro de hipertireoidismo subclínico\n(assintomático).","C":"O tratamento cirúrgico proposto é de tireoidectomia total e caso haja alteração no proto\noncogene RET deve ser pesquisada todos os\nfamiliares uma vez que essa alteração evidencia o\ncarcinoma papilífero familiar.","D":"O tratamento cirúrgico proposto é de tireoidectomia total sendo indicado o seguimento com a\nUSG cervical e a dosagem da calcitonina."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-335074","number":"335074","sourceNumber":"335074","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um jovem de 17 anos de idade apresenta um nódulo cervical direito de 2 cm. É feita\numa punção aspirativa com agulha fina, e as células se coram positivamente para calcitonina. Os\ntestes laboratoriais revelam também cálcio elevado. O diagnóstico mais provável, nesse caso, é","options":{"A":"câncer folicular da tireoide.","B":"NEM 1.","C":"NEM 2a.","D":"NEM 2b."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-334727","number":"334727","sourceNumber":"334727","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente MCF, sexo feminino, 51 anos, refere ter percebido no banho a presença de\num nódulo em topografia cervical anterior a\nesquerda, medindo cerca de 3 cm, não doloroso e que\nse movia quando a paciente deglutia. A paciente procurou assistência médica e foi solicitado\nultrassonografia do pescoço. A ultrassonografia mostrou um nódulo de 2,5 cm, hipoecóico de\ncontornos irregulares e com microcalcificações. Foi solicitado uma punção aspirativa do nódulo que\nteve o resultado de Bethesda V. Qual das condutas abaixo não seriam adequadas para o caso\nacima?","options":{"A":"Tireoidectomia parcial com exame de congelação intraoperatória.","B":"Acompanhamento.","C":"Tireoidectomia parcial.","D":"Tireoidectomia total."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-320443","number":"320443","sourceNumber":"320443","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A causa mais comum de Distúrbio da Diferenciação Sexual é:","options":{"A":"Anormalidades cromossômicas.","B":"Tumores virilizantes dos ovários.","C":"Exposição intrauterina à progestágenos.","D":"Hiperplasia adrenal congênita.","E":"Uso de drogas ilícitas na gestação"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-336309","number":"336309","sourceNumber":"336309","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 50 anos, hipertensa em uso de losartana, refere aparecimento de nódulo em\nlobo esquerdo da tireóide há 2 anos, de crescimento lento, sem disfonia, disfagia e dispnéia. Nega\nsintomas de hipertireoidismo, hipotireoidismo e diabetes melitus. Nega história familiar de\nneoplasias. Tabagista há 30 anos (20 cigarros/semana) e nega etilismo. Exame físico: Oroscopia:\nausência de lesões. Laringoscopia: mobilidade normal de pregas vocais, ausência de lesões. À\npalpação cervical identificado nódulo de cerca de 4 cm, localizado em lobo esquerdo da tireoide,\nausência de linfadenomegalia cervical. Tendo em vista a anamnese e o exame físico desta\npaciente bem como seus conhecimentos acerca do tema doenças cirúrgica da tireoide é correto\nafirmar que além de USG cervical, é necessário solicitar:","options":{"A":"Dosagem do TSH. Caso a USG evidencie nódulo cístico com componente sólido associado é\nnecessário a realização da PAAF","B":"Dosagem de TSH e cintilografia. Caso a USG evidencie nódulo sólido, hipoecoico, com\nmacrocalcificações não é necessário realizar a PAAF.","C":"Dosagem de TSH. Caso a USG evidencie nódulo cístico com componente sólido associado não\nestá indicado a realização da PAAF.","D":"Dosagem de TSH e tireoglobulina. Caso a USG evidencie nódulo sólido hipoecoico, com\nmicrocalcificações e altura maior que largura estamos diante de características ultrassonográficas\nde um nódulo benigno."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-304843","number":"304843","sourceNumber":"304843","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 32 anos, apresenta quadro de náuseas, vômitos, dor abdominal e astenia há\n4 semanas. Ao exame físico apresenta hipotensão\nortostática, hiperpigmentação em região areolar,\náreas de dobras cutâneas e gengival. Sem outras alterações ao exame do sistema cardiovascular,\nrespiratório e palpação abdominal. Apresenta os seguintes exames laboratoriais: glicemia = 65\nmg/dl; sódio = 138 mEq/L; potássio = 6,4 mEq/L; magnésio = 1,8 mg/dl; hemoglobina = 12,8 g/dl;\nleucócitos = 7.800/mm³; hormônio tiroestimulante = 1,35 UI/ml. Na sequência da propedêutica\nlaboratorial, espera-se encontrar:","options":{"A":"Níveis séricos de cortisol baixo, de ACTH e renina aumentados.","B":"Níveis séricos de cortisol e de renina baixos e de ACTH aumentado.","C":"Níveis séricos de cortisol baixo, de renina aumentado e de ACTH normal.","D":"Níveis séricos de cortisol, aldosterona e de ACTH baixos."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-313285","number":"313285","sourceNumber":"313285","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Quando a concentração plasmática de cálcio cai, a glândula paratireoide é estimulada a\nliberar paratormônio (PTH). Este aumenta a excreção urinária de fosfato e a reabsorção de cálcio.\nA elevação do PTH estimula os rins a secretar ?-hidroxilase que leva a ativação de:","options":{"A":"Folato.","B":"Aldosterona.","C":"Magnésio.","D":"Vitamina D.","E":"Vitamina E."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-304860","number":"304860","sourceNumber":"304860","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 35 anos, assintomática do ponto de vista cervical, realizou ultrassonografia de\nmama e teve seu pescoço rastreado no\nexame. Encontrou-se nódulo sólido em lobo esquerdo de\ntireoide, isoecoico, com halo hipoecoico bem definido, 0,9 cm em seu maior diâmetro, TI-RADS® 3,\nsem outros achados suspeitos ou informações de risco. Dosagem de TSH de 1,2. A melhor conduta\nserá:","options":{"A":"Indicar PAAF, dirigida por ultrassom.","B":"Indicar observação clínica e ultrassonográfica.","C":"Indicar lobectomia esquerda e biópsia de congelação.","D":"Indicar tireoidectomia total."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-287844","number":"287844","sourceNumber":"287844","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Assinalar a alternativa que preenche a lacuna abaixo CORRETAMENTE: A punção\naspirativa por agulha fina (PAAF) é\nessencial para definição diagnóstica de pacientes com nódulos\nde tireoide e, consequentemente, definir a necessidade de abordagem cirúrgica. A classificação\n\né a que padroniza a terminologia usada para descrever os achados do exame.","options":{"A":"BI-RADS","B":"Bethesda","C":"Bosniak","D":"TNM","E":"ASA"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-257371","number":"257371","sourceNumber":"257371","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Analise a proposição e a razão apresentadas. Proposição: Sinal de Chvostek pode ser\nencontrado no pós-operatório de uma tireoidectomia total PORQUE Razão: A hipercalcemia dessa\ncirurgia pode ser complicação. Com base na análise realizada, DEVE-SE concluir que:","options":{"A":"A proposição e a razão são verdadeiras e a razão é realmente a causa da proposição","B":"A proposição e a razão são verdadeiras, mas a razão não é a causa da proposição.","C":"A proposição é falsa, mas a razão é verdadeira.","D":"A proposição é verdadeira e a razão é falsa."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-227250","number":"227250","sourceNumber":"227250","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Os níveis séricos de fosfatase alcalina óssea encontram-se mais elevados na seguinte\nsituação:","options":{"A":"Hipoparatireoidismo.","B":"Artrite reumatoide.","C":"Doença de Paget.","D":"Osteoporose."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-246360","number":"246360","sourceNumber":"246360","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Lactente de 3 meses é levado por tia materna ao pediatra da UBSF com queixa de\nsonolência, letargia, choro rouco e dificuldade para sugar mamadeira. Ao exame físico apresentava\ntom de pele amarelado, mixedema, macroglossia, fontonelas amplas e hérnia umbilical.\n\nQuestionada sobre o teste do pezinho, tia relata que a mãe biológica é usuária de drogas,\nabandonou a criança e que não assumiu a\nresponsabilidade legal da mesma. Não tem os\ndocumentos de nascimento e não sabe dizer se exame foi realizado. Pelos sinais e sintomas\nclínicos, qual a principal hipótese diagnóstica?","options":{"A":"Hiperplasia Adrenal Congênita","B":"Deficiência da Biotinidase","C":"Hipotireoidismo Congênito","D":"Anemia Falciforme"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-255635","number":"255635","sourceNumber":"255635","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Enquanto realizava o exame da língua de Dona Judith, Dr. Wagner, médico\nacupunturista, observou um nódulo em sua região cervical anterior. Quanto à investigação e\ndiagnóstico do nódulo solitário da tireóide, MARQUE A CORRETA:","options":{"A":"Após coleta da história e exame físico, o TSH e T4 livre devem ser pedidos.","B":"O achado de uma lesão cística pode ser tranquilizante, mas este representa uma pequena\nminoria entre os nódulos tireóideos.","C":"As lesões nas quais o resultado da biópsia da punção aspirativa por agulha fina for\npersistentemente não diagnóstico devem ser\nacompanhadas por ultrassonografia a cada 6 meses.","D":"O carcinoma papilífero é a mais comum das neoplasias da tireóide e está geralmente associado\na um prognóstico ruim."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-227096","number":"227096","sourceNumber":"227096","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O hipotireoidismo na lactância e na infância pode ser congênito ou adquirido. Em\nrelação ao hipotireoidismo, assinale a alternativa INCORRETA:","options":{"A":"O hipotireoidismo adquirido é tipicamente causado por tireoidite autoimune (tireoidite de\nHashimoto) e ocorre na fase final da infância e da adolescência.","B":"A triagem de rotina nos recém-nascidos detecta o hipotireoidismo antes do aparecimento dos\nsinais clínicos.","C":"O hipotireoidismo em crianças é geralmente congênito; as causas adquiridas se tornam mais\ncomuns com a idade.","D":"A dosagem de T3 livre deve ser realizada sempre que se suspeitar de hipotireoidismo."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-246375","number":"246375","sourceNumber":"246375","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente 36 anos, sexo feminino, procura o ambulatório de cirurgia de cabeça e\npescoço com relato de durante consulta de\nrotina ter sido identificado nódulo em lobo esquerdo da\ntireoide. Nega disfonia, dispneia e disfagia. Nega história familiar de doença tireoidiana e\nirradiação\ndo pescoço durante a infância. Nega diabetes melitus e hipertensão arterial sistêmica. Nega\ntabagismo e etilismo. Ao exame físico presença de nódulo de cerca de 2 cm em lobo esquerdo da\ntireoide, sem linfonodos cervicais palpáveis. Videolaparoscopia: cordas vocais móveis. Realizado\nUSG cervical com identificação de nódulo de cerca de 2 cm localizado em lobo esquerdo, de\ncontornos irregulares, microcalcificações, circulação central e halo incompleto. PAAF é sugestivo de\nneoplasia maligna (Bethesda VI). Realizado tireoidismo total sendo que o histopatológico\nevidenciou Carcinoma medular de tireoide. Sobre o carcinoma medular é incorreto afirmar:","options":{"A":"A Síndrome NEN 2 A é caracterizada pela presença de carcinoma medular da tireoide, doença\ndas paratireoides e feocromocitoma.","B":"A disseminação metastática do carcinoma medular da tireoide se dá tanto por via linfática\nlinfonodal como por via hematogênica.","C":"O carcinoma medular da tireoide é uma neoplasia de diferenciação intermediária e proveniente\ndas células C ou parafoliculares.","D":"A síndrome NEN 2 B é caracterizada pela presença de feocromocitoma, doença das\nparatireoides e carcinoma medular da tireodie."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-246376","number":"246376","sourceNumber":"246376","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente 44 anos, sexo masculino, diabético, procura o ambulatório de Cirurgia de\nCabeça e Pescoço com relato de bócio há 5\nanos sendo que nos últimos 30 dias apresenta queixa\nde dispneia e disfagia devido ao crescimento rápido da lesão. Nega disfonia. Relata história\nfamiliar\nde neoplasia de tireoide (irmão com diagnóstico de carcinoma papilifero e irmã com relato de\nnódulo tireoidiano em investigação). Ao exame apresenta aumento difuso da glândula tireoide e\nmassa linfonodal à direita que ocupa níveis II, III e IV. Videolaringoscopia evidência pregas vocais\nmóveis e sem lesões. Realizado USG cervical e tomografia de pescoço. PAAF realizada é\nsugestiva de neoplasia maligna (Bethesda VI). Analisando o caso descrito assinale a alternativa\ncorreta em relação em relação às doenças neoplásicas da tireoide.","options":{"A":"O carcinoma folicular de tireoide é um tumor cujo padrão de disseminação metastática é\npredominantemente linfática.","B":"O carcinoma insular de tireoide é uma neoplasia de diferenciação intermediaria , com\nprognóstico melhor que o carcinoma anaplásico.","C":"O carcinoma medular de tireoide é uma neoplasia bem diferenciada da tireoide, cujo seguimento\nse faz com a dosagem de calcitonina.","D":"O carcinoma anaplásico é um tumor indiferenciado, de prognóstico reservado, derivado das\ncélulas foliculares"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-227313","number":"227313","sourceNumber":"227313","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A tireoide tem um papel importante na regulação de numerosos processos metabólicos\nde todo o corpo. Nos distúrbios da tireoide é\nCORRETO afirmar:","options":{"A":"O hipotireoidismo congênito é hereditário e se apresenta, na maioria dos casos, com retardo no\ndesenvolvimento mental e físico, que já é visível ao nascimento. As crianças com hipotireoidismo\ncongênito nascem pequenas para a idade gestacional e com os reflexos mais lentos.","B":"A tireoide de Hashimoto ou tireoidite linfocítica crônica é rara antes da adolescência e a\npresença de bócio descarta o diagnóstico.","C":"Na tireoidite linfocítica crônica, a glândula tireoide geralmente está diminuída, com\nconsistência\nfirme e indolor à palpação.","D":"O hipertireoidismo resulta da secreção excessiva de hormônio tireoidiano durante a infância e\ngeralmente é causado pela doença de Graves."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-220281","number":"220281","sourceNumber":"220281","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação ao tratamento do hipotireoidismo, assinale a alternativa CORRETA:","options":{"A":"A reposição da levotiroxina melhora a maioria das manifestações clínicas, exceto a disfunção\ncognitiva e os transtornos do humor.","B":"Na tireoidite de Hashimoto, está indicado o uso de corticoide para impedir a progressão da\ndestruição autoimune da glândula.","C":"A dose de levotiroxina deve ser ajustada de acordo com o valor do TSH após 2 semanas do\ninício.","D":"Nos pacientes idosos e cardiopatas, é recomendado iniciar doses baixas de levotiroxina e\nprogredir lentamente."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-199543","number":"199543","sourceNumber":"199543","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação à insuficiência adrenal, assinale a assertiva CORRETA.","options":{"A":"A doença de Addison é causada por autoanticorpos contra as células produtoras de ACTH.","B":"Suspensão abrupta de um corticoide após longo tempo de administração exógena é a principal\ncausa de insuficiência adrenal.","C":"Hiperpigmentação é achado típico da insuficiência adrenal secundária.","D":"O tratamento da insuficiência adrenal secundária requer a reposição de prednisona e\nfludrocortisona."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-196745","number":"196745","sourceNumber":"196745","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A biópsia com agulha fina (pequeno calibre 23 à 27) é uma ferramenta valiosa e de\ngrande custo/benefício, tornando-se uma modalidade chave na avaliação de pacientes com:","options":{"A":"Derrame Pleural.","B":"Tuberculose Peritoneal.","C":"Carcinomatose Peritoneal.","D":"Nódulos Tireoidianos."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-196744","number":"196744","sourceNumber":"196744","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente 24 anos, com tendência a engordar, dificuldade de perder peso, desânimo,\nqueda de cabelo e pele seca. Você desconfia\nde alteração em:","options":{"A":"Hipófise.","B":"Tireoide.","C":"Ovário.","D":"Suprarrenal."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-196800","number":"196800","sourceNumber":"196800","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Pacientes em corticoterapia prolongada podem desenvolver efeitos adversos e efeitos\ncolaterais. Assinale a opção abaixo que NÃO é um efeito que ocorre durante a corticoterapia.","options":{"A":"Hiperglicemia.","B":"Hipercalemia.","C":"Osteoporose.","D":"Dislipidemia."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-188021","number":"188021","sourceNumber":"188021","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 46 anos, vem ao consultório médico preocupada com nódulo tireoidiano\nencontrado incidentalmente durante banho. No exame físico, apresenta nódulo único de\nconsistência firme com aproximadamente 1,0 cm de diâmetro. Sobre o manejo da doença em\nquestão, assinale a alternativa correta:","options":{"A":"Hormônio tireoestimulante sérico baixo se correlaciona com uma maior probabilidade de\nmalignidade.","B":"Microcalcificações e hipervascularização são achados ultrassonográficos suspeitos de câncer.","C":"Ultrassonografia evidenciando lesão cística ou mesmo sólido-cística descarta neoplasia maligna.","D":"Ressonância magnética é inapropriada para avaliação de massa tireoidiana com linfonodos\ncervicais palpáveis.","E":"Biópsia aspirativa com agulha fina apresenta valor preditivo positivo próximo de 90% para\nnódulos sólidos malignos na tireoide."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-172516","number":"172516","sourceNumber":"172516","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo masculino, 64 anos, hipertenso e diabético de longa data, PO tardio\nde revascularização miocárdica, miocardiopatia\nisquêmica com fração de ejeção discretamente\nreduzida, insuficiência renal crônica ainda sem terapia dialítica e proteinúria de 6 g em 24h. Faz\nuso de losartan 100 mg/dia, bisoprolol 10 mg/dia, AAS 100 mg dia, furosemida 40 mg/dia,\nrosuvastatina 20 mg/dia, mononitrato de isossorbida 40 mg/dia, trimetazidina 70 mg/dia e\nreposição oral de potássio. Internado no CTI por piora da dispneia com BNP bastante elevado;\ncreatina = 3,6; ureia = 190; alcalose metabólica e potássio = 2,1.","options":{"A":"Sem dúvidas, essa dosagem de potássio está errada, deve ser repetida, afinal não é possível\nhaver hipocalemia em um paciente com insuficiência\nrenal, usando losartan e betabloqueador.","B":"É um quadro clássico de hipoaldosteronismo hiporreninêmico, evidenciado claramente pela\nalcalose metabólica e pela hipocalemia.","C":"Inicialmente, poderia até se pensar em atribuir a hipocalemia ao uso da furosemida, mas a\npresença de alcalose metabólica afasta definitivamente essa\n\npossibilidade.","D":"É um possível caso de hiperaldosteronismo primário associado aos problemas já\nexistentes, onde uma elevada atividade da renina\nplasmática e níveis elevados de aldosterona\nplasmática auxiliam na confirmação do diagnóstico. Além disso, um exame de imagem das\nsuprarrenais é fundamental.","E":"É um possível caso de hiperaldosteronismo primário associado aos problemas já\nexistentes, onde uma atividade da renina\nplasmática bastante reduzida e níveis elevados de\naldosterona plasmática auxiliam na confirmação\n\ndo diagnóstico. Além disso, um exame de imagem das suprarrenais é fundamental."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-148615","number":"148615","sourceNumber":"148615","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 32 anos apresenta quadro de perda ponderal, taquicardia, palpitações,\nagitação psicomotora, tremores e hiperfagia há cerca\nde 2 meses. Ao exame físico apresenta-se\ncom FC=135 bpm, PA = 140 x 60 mmHg, tremor fino de extremidades, tireóide aumentada\ndifusamente de volume com temperatura local elevada e sopro tireoidiano, proptose bilateral sem\nsinais flogísticos oculares. Assinale a alternativa correspondente ao manejo deste caso neste\nmomento.","options":{"A":"Devem ser prescritos metimazol, benzodiazepínico, inibidor da enzima conversora de\nangiotensinas.","B":"Devem ser prescritos propiltiuracil, propranolol, prednisona.","C":"A paciente deve ser encaminhada para tratamento com iodo radioativo.","D":"A paciente deve ser encaminhada para tratamento cirúrgico.","E":"Deve ser prescritos solução de lugol e sais de lítio."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-162586","number":"162586","sourceNumber":"162586","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A Síndrome de Cushing pode ser causada pela produção ectópica de ACTH ou CRH.\nCom base nisso, considere as neoplasias\nabaixo. I ? Carcinoide de timo; II ? Carcinoma de pulmão;\nIII ? Carcinoma de pâncreas. Quais podem estar associadas à Síndrome de Cushing?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-155472","number":"155472","sourceNumber":"155472","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre o carcinoma folicular da tireóide, marque a alternativa CORRETA:","options":{"A":"Hipotireoidismo é a regra no momento do diagnóstico.","B":"O comprometimento linfonodal ocorre na maioria dos pacientes.","C":"Rouquidão sugere melhor prognóstico.","D":"Está presente em até 10% dos pacientes portadores de bócio multinodular.","E":"É o tipo mais comum de câncer da tireóide."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-148528","number":"148528","sourceNumber":"148528","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente feminina, 50 anos, procura o ambulatório evidenciando massa em região\ncervical na topografia da glândula tireoide.\nApós a ultrassonografia e cintilografia cervical ficou\ndeterminado nódulo único sem captação do radioisótopo. A paciente foi encaminhada à biópsia por\nagulha fina. Pensando em malignidade qual o provável diagnóstico citológico em acordo com a sua\nincidência:","options":{"A":"Carcinoma medular.","B":"Carcinoma folicular.","C":"Carcinoma papilífero.","D":"Carcinoma anaplásico.","E":"Linfoma."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-131614","number":"131614","sourceNumber":"131614","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre a tireoide, assinale a resposta CORRETA:","options":{"A":"O carcinoma folicular é o câncer mais comum em pacientes com história de radioterapia externa.","B":"Metástases de câncer de tireoide são frequentes em linfonodos do nível 1.","C":"Carcinoma medular deve ser habitualmente tratado com tireoidectomia total sem\nlinfadenectomia.","D":"1% dos cistos do ducto tireoglosso podem conter câncer. Podem ocorrer tumores foliculares,\npapilíferos e anaplásicos. Exceto medulares.","E":"Sialoadenite não é uma complicação possível após dose ablativa de 100 mCi de I 131."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-77539","number":"77539","sourceNumber":"77539","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A paciente IMR, 72 anos, tem diagnóstico de hipertensão arterial, diabetes tipo 2 e\nosteopenia em coluna lombar. Encontra-se em uso de metformina 1500 mg/dia, losartana 50\nmg/dia, hidroclorotiazida 12,5 mg/dia, carbonato de cálcio 1200 mg/dia e ácido acetilsalicílico 100\nmg/dia. Encontra-se assintomática. Apresenta os seguintes exames laboratoriais: glicemia de jejum\n\n= 108 mg/dl, glicemia 2 horas pós-prandial = 138 mg/dl, hemoglobina glicada = 6,3%, colesterol\ntotal = 150 mg/dl, HDL-colesterol = 54\nmg/dl, triglicerídios = 135 mg/dl, creatinina = 1,1 mg/dl,\nhormônio tireoestimulante = 6,9 (valor de referência: 0,34-5,6 µUI/ml), tiroxina livre = 0,88 ng/dl\n(valor de referência: 0,54-1,24 ng/dl), anticorpo anti-tireoperoxidase= 32 UI/ml (valor de\nreferência:\n\n< 9 UI/ml), cálcio total = 9,2 mg/dl (valor de referência: 8,6-10,2 mg/dl), 25-OH vitamina D = 18\nmg/dl (valor de referência > 30 mg/dl). Em relação ao caso clínico supra descrito, assinale a\nalternativa incorreta.","options":{"A":"Não há necessidade de ajuste de dose da metformina ou associação de outro hipoglicemiante\noral para a paciente.","B":"Como a paciente apresenta fatores de risco cardiovascular e osteopenia, está indicado o uso de\nlevotiroxina para tratamento do hipotireoidismo.","C":"Está indicada a reposição de colecalciferol devido à perda de massa óssea.","D":"Apesar do elevado risco cardiovascular da paciente, não há indicação para uso de estatina\ncomo droga hipolipemiante.","E":"Os níveis pressóricos da paciente devem idealmente ficar abaixo de 130/80 mmHg, sendo\nrecomendado o uso de um medicamento inibidor da enzima conversora de angiotensina ou\nbloqueador do receptor da angiotensina II."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-77531","number":"77531","sourceNumber":"77531","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre hipotireoidismo na infância, responda qual alternativa está CORRETA. I) Deve\nser avaliado Hipotireoidismo Congênito (HC) em\nneonatos com icterícia prolongada. II) Atraso no\ndesenvolvimento neuropsicomotor é um dos sintomas de hipotireoidismo adquirido. III) O\nhipotireoidismo congênito é a principal causa evitável de deficiência mental.","options":{"A":"Somente III está correta.","B":"Todas estão corretas.","C":"Somente II e III estão corretas.","D":"Somente I e III estão corretas.","E":"Somente I e II estão corretas."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-43941","number":"43941","sourceNumber":"43941","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente feminina, 43 anos, diagnóstico recente de hipotireoidismo ainda\ndescompensado, apresenta dor tipo neuropática em\nhálux e indicador e diminuição da força de\npinça. Ao exame físico, apresenta Manobra de Phalen positivo. Qual o diagnóstico?","options":{"A":"Contratura de Dupuytren.","B":"Síndrome do túnel do carpo.","C":"Tenossinovite De Quervain.","D":"Síndrome do impacto.","E":"Síndrome da compressão no nervo radial."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-43295","number":"43295","sourceNumber":"43295","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino, 34 anos, com queixa de emagrecimento de 8 kg em 2\nmeses, tremores, insônia, palpitação e sudorese\nexcessiva. Ao exame físico, encontra-se lúcida,\ncorada, acianótica, FC 135 bpm, PA 120/60 mmHg, mãos quentes e sudoreicas, com tremor leve\nde extremidades, reflexos Aquileu e patelar exacerbados. Exame da região cervical com nódulo\ntireoidiano móvel de 2 cm em polo superior do lobo direito. Restante da glândula normal. Com base\nnos dados acima, os exames indicados que confirmariam a hipótese diagnóstica e o diagnóstico da\npaciente são respectivamente:","options":{"A":"Eletrocardiograma, TSH e T4 livre; Taquiarritmia e Doença de Graves.","B":"US de tireoide, TSH e T4 livre; Doença de Graves.","C":"Cintilografia de tireoide, TSH e T4 livre; Doença de Plummer.","D":"US e Ressonância da tireoide, TSH e T4 livre; Doença de Plummer.","E":"Hemograma, TSH, T4 livre; Tireoidite de Hashimoto."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-23146","number":"23146","sourceNumber":"23146","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Todas as afirmativas estão corretas exceto:","options":{"A":"Na tireoidite de Hashimoto encontra-se níveis elevados de anticorpos circulantes\nantitireoglobulina.","B":"A tireoidite de Hashimoto é mais frequente no período da adolescência, no sexo masculino.","C":"A síndrome de DiGeorge caracteriza-se por hipoparatireoidismo congênito, aplasia tímica e\nanomalias cardíacas.","D":"Hipocalcemia é comum nas primeiras horas de vida, principalmente em prematuros.","E":"A tríade clássica da doença de Graves inclui bócio, exoftalmia e hipertireoidismo."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-9374","number":"9374","sourceNumber":"9374","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Quanto aos tumores malignos da tireoide, está incorreto:","options":{"A":"Carcinoma papilar é a forma mais comum das neoplasias da tireoide.","B":"O carcinoma folicular é mais frequente nas mulheres do que nos homens.","C":"O carcinoma medular pode manifestar-se isoladamente ou fazer parte das Neoplasias\nEndócrinas Multiplas (NEM).","D":"A calcitonina é marcadora biológica eficiente para os tumores anaplásicos.","E":"Linfoma deve ser considerado nos bócios que crescem em período muito curto."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-8163","number":"8163","sourceNumber":"8163","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Para diferenciação entre lesões benignas e malignas da tireoide, qual o melhor método\ndiagnóstico considerando que o nódulo da tireoide apresente 10 mm de diâmetro?","options":{"A":"Ultrassonografia de tireoide.","B":"Cintilografia de tireoide.","C":"Iodo radioativo.","D":"Punção aspirativa por agulha fina.","E":"TSH ultrassensível."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-363962","number":"363962","sourceNumber":"363962","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Leia o caso clínico a seguir: Mulher de 53 anos foi encaminhada para avaliação de\nhiperprolactinemia. Não apresentava qualquer tipo de queixa, totalmente assintomática.\n\nAntecedente de última menstruação há 48 meses. Trazia exame de RNM de sela túrcica com lesão\ncompatível com adenoma hipofisário de 5 mm, sem invasão extra-selar. Seguindo as diretrizes do\núltimo Consenso Internacional da Sociedade Hipofisária, a conduta mais apropriada para essa\npaciente deverá ser","options":{"A":"o encaminhamento para cirurgia.","B":"o encaminhamento para radioterapia.","C":"a utilização de agonista dopaminérgico.","D":"o acompanhamento da paciente."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-363982","number":"363982","sourceNumber":"363982","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 45 anos, transplantado renal, começou a apresentar um quadro de\nhipertensão severa, apesar do uso de vários anti-hipertensivos. Não usa diuréticos. Na\ninvestigação, apresentou hipocalemia. A partir do caso apresentado, qual deve ser o próximo\nexame a ser solicitado, pensando na causa desse distúrbio?","options":{"A":"Dosagem de tacrolimos.","B":"Doppler do enxerto renal.","C":"Relação aldosterona/atividade plasmática de renina.","D":"Dosagem de metanefrinas séricas urinárias."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-354830","number":"354830","sourceNumber":"354830","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente, 40 anos idade, sexo masculino, durante\ninvestigação de cefaleia foi encontrado adenoma hipofisário de 0,8 cm em lobo direito da hipófise.\nExames laboratoriais demonstram GH: 10 µg/L, IGF1: 215 ng/mL (VR: 58 a 219 ng/mL) e\nnormalidade dos demais eixos hipofisários. Considerando o caso relatado, qual é a próxima\nconduta e sua justificativa?","options":{"A":"Acompanhar o paciente a longo prazo, por tratar-se de um incidentaloma hipofisário.","B":"Solicitar o teste de supressão do GH com glicose (dosagem de GH durante o TOTG) para\nesclarecimento diagnóstico.","C":"Iniciar o tratamento com octreotide LAR pois o GH, no valor apresentado no exame, confirma\ndiagnóstico de acromegalia.","D":"Encaminhar o paciente para neurocirurgia, por se tratar de um tumor de hipófise com efeitos\ncompressivos."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-354829","number":"354829","sourceNumber":"354829","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Leia o relato do caso clínico a seguir. Paciente, 45 anos de idade, sexo feminino, refere\nsintomas de perda de peso, tremores, sudorese, taquicardia e diarreia. Ao exame físico apresenta\nexoftalmia bilateral, com edema e eritema em ambas as pálpebras e conjuntivas, além de dor à\nmovimentação ocular; PA: 140/90 mmHg, FC; 112 bpm. Exames complementares com discreto\naumento de volume tireoidiano ao ultrassom, anti TRAB: 3 UI/L (VR: < 0,55 UI/L), TSH: 0,001\nmicroUI/mL (VR: 0,48 a 5,6), T4 livre: 3 ng/dL (VR: 0,85 a 1,5 ng/dL). Considerando o caso\nrelatado, qual é a conduta a ser adotada?","options":{"A":"Indicar radioiodoterapia por ser um procedimento resolutivo, com grande probabilidade de cura.","B":"Encaminhar para Tireoidectomia total de imediato.","C":"Iniciar tratamento medicamentoso com tapazol 30 mg e propranolol.","D":"Escolher entre as opções terapeuticas: radioidoterapia, tireoidectomia total ou tratamento\nmedicamentoso a critério do médico\nassistente e da preferência do paciente, já que nenhum dos\ntratamentos é contraindicado e nem há expectativa de melhor resposta com um tratamento\nespecífico."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-362629","number":"362629","sourceNumber":"362629","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Os fatores de risco descritos para hiperglicemia induzida pelo uso de glicocorticoide são\nlistados corretamente no item:","options":{"A":"Uso de doses mais baixas (prednisolona > 20 mg, hidrocortisona > 50 mg, dexametasona > 4\nmg), longa duração de tratamento, idade avançada, IMC elevado, intolerância à glicose prévia,\nhistória de diabetes gestacional, história anterior de hiperglicemia induzida por glicocorticoide,\nhistória familiar de DM, HbA1c ? 6%.","B":"Uso de doses mais altas (prednisolona > 20 mg, hidrocortisona > 50 mg, dexametasona > 4 mg),\ncurta duração de tratamento, idade avançada, IMC elevado, intolerância à glicose prévia, história\nde diabetes gestacional, história anterior de hiperglicemia induzida por glicocorticoide, história\nfamiliar de DM, HbA1c ? 6%.","C":"Uso de doses mais altas (prednisolona > 20 mg, hidrocortisona > 50 mg, dexametasona > 4 mg),\nlonga duração de tratamento, idade avançada, IMC elevado, intolerância à glicose prévia, história\nde diabetes gestacional, história anterior de hiperglicemia induzida por glicocorticoide, história\nfamiliar de DM, HbA1c ? 6%.","D":"Uso de doses mais altas (prednisolona > 20 mg, hidrocortisona > 50 mg, dexametasona > 4 mg),\nlonga duração de tratamento, idade avançada, IMC elevado, intolerância à glicose prévia, história\nde diabetes gestacional, história anterior de hiperglicemia induzida por glicocorticoide, história\nfamiliar de DM, e não por HbA1c ? 6%."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-339758","number":"339758","sourceNumber":"339758","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um paciente de 80 anos foi admitido no hospital devido a um episódio de fibrilação\natrial de frequência rápida. Familiares\nreferiam também quadro de perda de peso, apatia, declínio\ncognitivo, dispneia e fraqueza muscular ao longo dos últimos seis meses. Qual dos exames abaixo\nserá mais útil para a definição diagnóstica neste caso?","options":{"A":"Holter","B":"TSH","C":"Pet scan","D":"Creatinina","E":"Ressonância de encéfalo"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-334774","number":"334774","sourceNumber":"334774","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 67 anos de idade, com hipertensão arterial compensada em uso de 2 classes\nde medicações anti-hipertensivas. Fez avaliação\nde rotina com dosagem de TSH de 6,4 mUi/L (VR\n0,45 - 4,50). Após 8 semanas repetiu TSH com resultado de 6,0 mUi/L (VR 0,45 - 4,5). De acordo\ncom o Consenso Brasileiro para avaliação e tratamento do hipotireoidismo subclínico em adultos:\nrecomendações do Departamento de Tireoide da SBEM, a conduta inicial para este caso é","options":{"A":"solicitar dosagem sérica de triiodotironina e anticorpos tireoidianos.","B":"iniciar tratamento com levotiroxina em doses baixas com aumento gradual.","C":"acompanhar clínica e laboratorialmente a paciente, sem iniciar o tratamento.","D":"iniciar uso da associalção de levotiroxina e triiodotironina em doses baixas."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-342605","number":"342605","sourceNumber":"342605","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente submetida a tireoidectomia total por bócio de grandes dimensões evolui\ncom dispneia intensa, cornagem e estridor assim\nque é retirado o tubo endotraqueal. A\nlaringoscopia mostra cordas vocais paralisadas em adução. Tendo em vista as relações anatômicas\nentre tireoide, traqueia, vasos e nervos da região cervical anterior, provavelmente que estrutura\nfoi\nlesada durante o procedimento operatório?","options":{"A":"nervo laríngeo recorrente","B":"nervo laríngeo superior","C":"músculo cricofaringeo","D":"fáscia pré-vertebral"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-334775","number":"334775","sourceNumber":"334775","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Rapaz de 28 anos de idade, apresentou diagnóstico de SARS-COV2 há 4 semanas,\ncom sintomas leves, sem necessidade de\ninternação e uso de medicações específicas. Há 2\nsemanas vem evoluindo com recidiva da dor cervical, palpitações, tremores e sudorese excessiva.\nAntecedente familiar de hipotireoidismo. Ao exame: fácies atípica, tireoide aumentada de volume e\ndolorosa á palpação, FC: 102 bpm, PA: 130 x 70 mmHg, tremores, de extremidades. Exames\nlaboratoriais: TSH: < 0,01 MUI/I, VR (0,45 - 4,5), T 4 livre: 1,8 (0,8 - 1,4), anticorpos\ntireoidianos\nnegativos, TRAb negativo. De acordo com o caso relatado, o diagnóstico e a conduta são,\nrespectivamente,","options":{"A":"doença de Graves pelo antecedente familiar e função tireoidiana: iniciar drogas como metimazol.","B":"tireoidite subaguda dolorosa viral: utilizar propranolol, anitinflamatótio e acompanhar\nevolução.","C":"doença de Graves pela história familiar e exames laboratoriais; indicar dose ablativa com iodo\nradioativo e propranolol.","D":"tireoidite subaguda dolorosa viral; utilizar prednisona e metimazol."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-321551","number":"321551","sourceNumber":"321551","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"De acordo com os guidelines da Endocrine Society, qual dos testes iniciais deve ser\nrecomendado para diagnóstico de hipercortisolismo em um paciente com suspeita de síndrome de\ncushing?","options":{"A":"Cortisol salivar no final de noite (2 medidas).","B":"Cortisol sérico com ACTH pela manhã.","C":"Teste de estímulo com ACTH (cortrosina).","D":"Teste de supressão com 8mg de dexametasona."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-330077","number":"330077","sourceNumber":"330077","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, 50 anos, sexo feminino, apresenta insuficiência adrenal com acometimento\ndo setor hipofisário corticotrófico, com\ncomprometimento da produção de Hormônio\nAdrenocorticotrófico (ACTH) e consequente deficiência de glicocorticoide e andrógenos adrenais,\nsem comprometer a produção de mineralocorticoide, sem escurecimento da pele e mucosas e nem\nhiperpotassemia. É um caso de:","options":{"A":"Insuficiência adrenal primária crônica.","B":"Insuficiência adrenal primária aguda.","C":"Insuficiência adrenal secundária crônica.","D":"Insuficiência adrenal secundária aguda."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-342613","number":"342613","sourceNumber":"342613","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma mulher de 30 anos realiza punção aspirativa de nódulo na tireoide de 2cm. Exame\ncitológico revela neoplasia folicular. A cirurgia melhor indicada para essa paciente é:","options":{"A":"nodulectomia","B":"lobectomia total com istmectomia","C":"tireoidectomia total","D":"lobectomia subtotal"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-334115","number":"334115","sourceNumber":"334115","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Com relação à produção hormonal do hipotálamo e hipófise, assinale a alternativa\ncorreta.","options":{"A":"Os hormônios CRH, liberador das gonadotrofinas (GnRH), liberador da tireotrofina (TRH) e\nliberador do hormônio do crescimento (GHRH)\nsão produzidos no hipotálamo e alcançam a hipófise\natravés do trato hipotalâmico-hipofisário.","B":"A arginina vasopressina (AVP) é produzida nos neurônios magnocelulares do hipotálamo e\nalcançam a hipófise através do trato hipotalâmico-hipofisário.","C":"O hormônio liberador da AVP é produzido no hipotálamo e é levado à adeno-hipófise por meio\ndo sangue.","D":"Os hormônios CRH, GnRH, TRH e GHRH são produzidos o hipotálamo e alcançam a\nneuro-hipófise por meio do sangue."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-334122","number":"334122","sourceNumber":"334122","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre o prognóstico da Doença de Graves na faixa etária pediátrica, assinale a\nalternativa correta.","options":{"A":"Em geral, não há remissão, e os pacientes utilizam drogas antitireoideanas até a vida adulta.","B":"Cerca de 30% a 50% dos casos apresentam remissão espontânea, permitindo a retirada gradual\nda medicação.","C":"Apenas 10% dos pacientes apresentam remissão espontânea, por isso, frequentemente, há\nindicação de tireoidectomia total.","D":"Apesar de grande parte das crianças apresentarem remissão espontânea, quase todas precisam\nser submetidas à ablação cirúrgica ou química, em\nrazão do alto risco de crise tireotóxica."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-342627","number":"342627","sourceNumber":"342627","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A causa mais frequente de tireotoxicose é:","options":{"A":"adenoma tóxico","B":"doença de Graves","C":"tireoidite subaguda","D":"bócio multinodular tóxico"},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-334800","number":"334800","sourceNumber":"334800","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O tratamento dos prolactinomas da hipófise é preferencialmente feito com:","options":{"A":"Cirurgia.","B":"Betabloqueadores.","C":"Inibidor direto da renina.","D":"Agonistas dopaminérgicos."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-334132","number":"334132","sourceNumber":"334132","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Todas as alternativas abaixo apresentam sintomas que são sinais de alarme para crise\ntireotóxica, exceto:","options":{"A":"Icterícia.","B":"Diarreia.","C":"Hipertermia.","D":"Exantema."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-342635","number":"342635","sourceNumber":"342635","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um recém-nascido de 10 dias é atendido com quadro de icterícia. A mãe relata que ele\npermaneceu internado na maternidade durante 5 dias por ter apresentado hipoglicemia e icterícia.\nO peso e o comprimento ao nascer são 3.000g e 49cm, respectivamente. Ao exame físico,\nmostrou-se ativo, ictérico, com tônus adequado, micropênis e testículos tópicos. Assinale a\nalternativa correta, que apresenta o diagnóstico mais provável:","options":{"A":"síndrome de Noonan","B":"hipotireoidismo congênito","C":"hipopituitarismo","D":"síndrome de Silver-Russe"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-342636","number":"342636","sourceNumber":"342636","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um recém-nascido com 2 semanas de vida, mamando exclusivamente ao seio materno,\napresenta perda de peso, recusa alimentar, vômitos, desidratação com sódio = 120mEq/L e\npotássio = 6,5mEq/L, além de glicemia de 40mg/dL. Qual é o diagnóstico mais provável?","options":{"A":"filho de mãe diabética","B":"ingestão insuficiente de leite","C":"hiperplasia adrenal congênita","D":"estenose hipertrófica do piloro"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-334153","number":"334153","sourceNumber":"334153","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente 76 anos, queixando-se de dor em região cervical anterior, de início há 2\nmeses, associado a abaulamento local e aparecimento de tumoração palpável e dolorosa na\nmesma região. Realizada biópsia da lesão com laudo histopatológico de neoplasia maligna mais\ngrave e agressiva de tireóide. Trata-se de:","options":{"A":"Carcinoma anaplásico.","B":"Carcinoma papilífero.","C":"Carcinoma metaplásico tipo II.","D":"Carcinoma folicular."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-300795","number":"300795","sourceNumber":"300795","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Denomina-se ?hiperaldosteronismo primário? o grupo de doenças em que a produção\nde aldosterona pelo córtex adrenal é\ninapropriadamente elevada, relativamente autônoma em\nrelação ao sistema renina-angiotensina-aldosterona e não pode ser suprimida (ou é apenas\nparcialmente suprimida) por sobrecarga de sódio. Nesse contexto, a etiologia responsável pela\nmaioria dos casos de hiperaldosteronismo primário é:","options":{"A":"Hiperplasia adrenal primária unilateral.","B":"Carcinomas adrenais produtores de aldosterona.","C":"Hiperplasia adrenal bilateral.","D":"Hiperaldosteronismo familial."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-300797","number":"300797","sourceNumber":"300797","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Os prolactinomas, tumores hipofisários produtores de prolactina (PRL), são os\nadenomas hipofisários mais frequentes. Em geral,\nsurgem esporadicamente, mas podem se\nassociar a síndromes genéticas, como neoplasia endócrina múltipla tipo 1 e adenoma hipofisário\nfamiliar isolado. Considerando as manifestações clínicas associadas aos prolactinomas, é\nCORRETO afirmar:","options":{"A":"A hiperprolactinemia leva ao hipogonadismo hipogonadotrófico, principalmente por inibir a\npulsatilidade do hormônio liberador das gonadotrofinas (GnRH).","B":"Clinicamente, as mulheres podem apresentar fase lútea longa, anovulação, infertilidade,\noligomenorreia e amenorreia.","C":"A hiperprolactinemia crônica leva ao aumento da densidade mineral óssea na coluna lombar em\nambos os sexos em razão do hipogonadismo.","D":"A compressão da haste hipofisária, do tecido hipofisário normal ou em decorrência da apoplexia\nhipofisária, leva ao comprometimento dos seios cavernosos."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-316295","number":"316295","sourceNumber":"316295","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre câncer de tireoide, podemos afirmar:","options":{"A":"O tumor maligno encontrado com maior frequência na glândula tireoide é do tipo papilífero,\npodendo corresponder de 80 a 90% dos tumores malignos de tireoide.","B":"O carcinoma medular, que se origina nas células C parafoliculares (produtoras de calcitonina), é\na forma mais prevalente nos pacientes com CA\nde tireoide.","C":"A punção aspirativa por agulha fina (PAAF) é de extrema importância na diferenciação das\nneoplasias benignas e malignas dos tumores foliculares.","D":"O CA anaplásico é bem diagnosticado por PAAF, raramente necessitando de amostra para\nanálise imuno-histoquímica."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-300798","number":"300798","sourceNumber":"300798","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A acromegalia, na maioria dos casos (98%), é causada por um adenoma hipofisário\nsecretor de somatotrofinoma (GH), sendo 70-80%\nmacroadenomas. Carcinomas somatotróficos\nsão extremamente raros. Por ser uma doença com estigmas, o diagnóstico é clínico na maioria dos\ncasos. Os sinais e os sintomas mais comuns na acromegalia em relação ao comprometimento\nosteomuscular são:","options":{"A":"Espessamento da pele, papilomas cutâneos (skin tags), espaçamento dentário.","B":"Espessamento do couro cabeludo, acantose nigricante, hiperidrose, hirsutismo.","C":"Aumento das mãos e do número dos sapatos, aumento do volume do crânio, acentuação dos\nmalares.","D":"Edema de tecidos moles, aumento da cartilagem do nariz e das orelhas, lábios espessados."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-300799","number":"300799","sourceNumber":"300799","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A Síndrome de Cushing é caracterizada por um grupo de sinais e sintomas que refletem\na exposição prolongada e inapropriada ao\ncortisol. É considerada a etiologia mais prevalente da\nSíndrome de Cushing endógena:","options":{"A":"Corticotrofinoma.","B":"Depressão e outras doenças psiquiátricas.","C":"Etilismo.","D":"Resistência aos glicocorticoides."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-294256","number":"294256","sourceNumber":"294256","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"As doenças osteometabólicas incluem um grupo extenso de afecções que alteram o\nmetabolismo ósseo, resultando, entre outras coisas, em aumento ou redução generalizada da\nmassa óssea. Dentro deste contexto, o hiperparatireoidismo secundário tem relação direta com","options":{"A":"o escorbuto.","B":"a osteodistrofia renal.","C":"o raquitismo.","D":"as mucopolissacaridoses."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-314103","number":"314103","sourceNumber":"314103","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 36 anos procurou endocrinologista com queixa de ganho de peso, cerca de\n10 quilos nos últimos seis meses, atribuído\nao isolamento pela pandemia, diminuição da atividade\nfísica e episódios de compulsão alimentar. Ao exame físico, entretanto, chamava atenção a\npresença de estrias violáceas abdominais e hipertensão arterial estágio 2. Iniciada investigação\npara hipercortisolismo, com diagnóstico final de síndrome de cushing ACTHdependente, com\nadenoma hipofisário de 8mm ao exame de imagem. Segundo os Guidelines da Endocrine Society,\nqual conduta inicial seria considerada como terapia de primeira linha nessa paciente?","options":{"A":"Cirurgia para ressecção da lesão hipofisária.","B":"Tratamento medicamentoso com inibidores da esteroidogênese, por tempo indeterminado.","C":"Adrenalectomia bilateral.","D":"Radioterapia."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-317156","number":"317156","sourceNumber":"317156","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo masculino 55 anos, durante exame periódico pelo médico do trabalho,\nassintomático, apresenta um nódulo tireoidiano á direita palpável de aproximadamente 2 cm. São\nafirmativas corretas, exceto:","options":{"A":"O tipo histológico papílífero dissemina-se em até um terço dos casos por via linfática","B":"O tipo histológico mais comum dos cânceres de tireoide é o folicular correspondendo até a 80%\ndos casos.","C":"O carcinoma folicular apresenta maior risco de metástases a distância e reincidência.","D":"A punção aspirativa com agulha fina (PAAF) é mandatória neste caso, independente da\nsintomatologia do paciente."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-317158","number":"317158","sourceNumber":"317158","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A glândula tireóide é sede potencial de várias patologias benignas e malignas. O\nachado de nódulos na tireóide é cada vez\nmais frequente, em virtude, principalmente, da maior\ndisponibilidade dos métodos de imagem. Em relação aos nódulos tiroidianos, está INCORRETO:","options":{"A":"A frequência de nódulos, palpáveis ou não, aumenta com a idade e é cerca de quatro vezes\nmais comum no sexo feminino.","B":"Como a grande maioria dos nódulos é benigna, o exame de ultrassonografia só deve ser\nsolicitado em pacientes que apresentam\nqueixas, alterações na palpação e/ou fatores de risco para\ncâncer de tireoide.","C":"Tireoide difusamente heterogênea, com áreas hipoecoicas de permeio, traves fibróticas e\npseudonódulos são sinais ultrassonográficos sugestivos de tireoidite crônica autoimune.","D":"A PAAF (Punção Aspirativa por Agulha Fina) é um método muito útil na avaliação de pacientes\ncom nódulos na tireóide e deve ser solicitada\npara todos os pacientes com diagnóstico de nódulo\ntiroidiano."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-294266","number":"294266","sourceNumber":"294266","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo masculino procurou endocrinologista devido a quadro de obesidade,\ncom ganho de 15 quilos nos últimos seis meses,\nassociado a aumento de apetite. No exame físico,\napresentava índice de massa corpórea de 33 kg/m², hipertensão arterial (154/99 mmHg), aumento\nda circunferência abdominal (108 cm), presença de estrias com 2,0 cm de largura em abdome, de\ntom violáceo. Feita hipótese diagnóstica de síndrome de Cushing. Nesse caso, qual é a conduta\nindicada para confirmação diagnóstica?","options":{"A":"Cortisol sanguíneo pela manhã, colhido em posição supina. Dois valores acima de 30 µg/dl\nconfirmam diagnóstico de síndrome de Cushing.","B":"Solicitar ressonância magnética de sela túrcica. A presença de adenoma hipofisário maior que 5\nmm ratifica diagnóstico de doença de Cushing.","C":"Cortisol sanguíneo com valor acima de 1,8 µg/dl, após supressão com 1 mg de dexametasona\nassociado a cortisol salivar das 23 horas\nelevado, confirma o diagnóstico de hipercortisolismo.","D":"Solicitar tomografia computadorizada de abdome superior. A presença de adenoma adrenal > 7\nmm é diagnóstico de síndrome de Cushing ACTH-independente."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-313198","number":"313198","sourceNumber":"313198","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma mulher de 43 anos está em investigação por fraturas recorrentes por pequenos\ntraumas. Antecedentes pessoais: hipertensão\narterial, nefrolitiase e constipação intestinal há 2\nanos. Inventário ósseo: fraturas de rádio e ulna esquerdos e de calcâneos consolidadas,\nosteopenia intensa em ossos da mão e crânio com aspecto ?em sal e pimenta?. O achado\neletrocardiográfico mais provável é:","options":{"A":"ondas T apiculadas","B":"elevação do segmento ST","C":"encurtamento do intervalo QT","D":"bloqueio AV do 2° grau Mobitz ||"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-295355","number":"295355","sourceNumber":"295355","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 25 anos, do sexo feminino, refere ganho de peso excessivo nos últimos\nanos e acredita ser por alteração em\ntireoide. Refere indisposição, fraqueza, queda de cabelo e\nunhas quebradiças. Faz uso de anticoncepcional oral. Ao exame físico: PA: 130/85 mmHg, FC 85\nbpm, peso 85 kg, altura 1,55 m. Exames laboratoriais: TSH ? 5,6 (VR 0,3 a 4,5), T4 livre ? 0,96\nng/dl (VR 0,85 a 1,5 ng/dl), Hb 11,7 g/dl (VR 12 a 16 g/dl), VCM 75 fl (VR 80 a 100 fl), HCM 26 pg\n\n(VR 26 a 32 pg), leucócitos 6.800 (VR 4.000 a 11.000), plaquetas 275.000, CT 210, LDL 150, HDL\n\n35, TGL 180. Nesse caso, em relação ao diagnóstico, sabe-se que:","options":{"A":"A presença de sintomas compatíveis com hipotireoidismo associado a um exame de TSH acima\ndo valor referencial confirma o diagnóstico e indica a reposição imediata de levotiroxina para\nevitar\npiora do quadro clínico.","B":"Seria necessário repetir a dosagem de TSH e, caso o valor seja confirmado, o tratamento com\nlevotiroxina deve ser iniciado, já que a paciente está sintomática.","C":"Não podemos confirmar o diagnóstico de hipotireoidismo, pois os sintomas relatados pela\npaciente podem ter outras causas e é possível\nque a alteração do TSH seja secundária à própria\nobesidade.","D":"Antes de iniciar o tratamento é necessário dosar o selênio e o iodo, pois pode ser necessário\ntratamento prévio com lugol e selênio em caso de deficiências confirmadas."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-313209","number":"313209","sourceNumber":"313209","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma mulher de 27 anos refere labilidade emocional, choro fácil, dificuldade para dormir\ne palpitações taquicárdicas. Na avaliação\nclínica, apresenta-se inquieta, com pele quente e úmida e\ntremor fino de extremidades. Sua frequência cardíaca é de 116bpm, e notam-se reflexos\ntendinosos exacerbados. Assinale a alternativa que contém o achado de exame complementar\nmais provável:","options":{"A":"T4 total baixo","B":"T3 indetectável","C":"TSH baixo","D":"T4 livre baixo"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-316325","number":"316325","sourceNumber":"316325","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação à insuficiência adrenal, marque a alternativa correta:","options":{"A":"São alterações laboratoriais comuns: hipoglicemia, hipocalemia, hipernatremia e hipocalcemia.","B":"A síndrome poliglandular autoimune tipo I ocorre por mutação no gene ATP7B e se caracteriza\npela presença de candidíase mucocutânea,\nhipoparatireoidismo e doença de Addison.","C":"Alguns medicamentos podem causar insuficiência adrenal. Como exemplo, temos o cetoconazol,\nque aumenta a metabolização hepática do cortisol\ne a rifampicina, que inibe a esteroidogênese.","D":"A hiperpigmentação cutânea é um achado da insuficiência adrenal primária, não ocorrendo na\ninsuficiência adrenal secundária e aparece por aumento do MSH (melanocyte-stimulating hormone).\nO MSH estimula os melanócitos."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-315809","number":"315809","sourceNumber":"315809","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 52 anos de idade, masculino, procura atendimento médico ambulatorial\ndevido a picos hipertensivos frequentes nos\núltimos meses. Relata que há aproximadamente 3\nmeses vem apresentando picos hipertensivos esporádicos (aproximadamente 2 picos semanais\nisolados), com necessidade de controle pressórico com medicamentos orais. Nega uso contínuo de\nanti-hipertensivos. Devido ao aumento da frequência dos episódios, optou por procurar atendimento\nmédico. Relata ganho ponderal importante nos últimos meses, sem alteração de dieta ou exercício\nfísico, associado a dispneia progressiva. Nega febre. Nega tosse. Nega outras comorbidades. Nega\ncirurgias prévias. Ao exame físico: bom estado geral, corado, hidratado, eupneico, anictérico,\nacianótico, fáscies ?em lua cheia?. Bulhas rítmicas, normofonéticas, sem sopros. Murmúrio\nvesicular presente bilateral, com discretos estertor difusos. Abdome em avental, com estrias\nvioláceas, indolor a palpação, sem massas palpáveis. Pressão Arterial - Membro superior direito:\n160 x 100 mmHg Pressão Arterial - Membro superior esquerdo: 159 x 100 mmHg Glicemia em\njejum - 152 mg/dl (teste de triagem Realizou ultrassonografia abdominal que evidenciou massa em\ntopografia de loja renal esquerda, sem contornos definidos. Realizou, então, a tomografia e a\nradiografia de tórax abaixo. A principal hipótese diagnóstica é:","options":{"A":"Adenoma de suprarrenal.","B":"Aldosteronoma.","C":"Carcinoma adrenocortical.","D":"Adenocarcinoma ductal de pâncreas."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/315809.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-317211","number":"317211","sourceNumber":"317211","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 28 anos de idade, em acompanhamento por hipotireoidismo, decorrente de\ntireoidite de Hashimoto, vem em consulta na UBS para reavaliação clínica. Refere sonolência\ndiurna e piora do hábito intestinal com tendência a constipação. Faz uso diário de levotiroxina\n125mcg, omeprazol 20mg e carbonato de cálcio 500mg pela manhã. Ao exame físico, peso: 55kg,\nPA: 120x80 mmHg, FC: 62 bpm, tireoide com volume diminuído sem outras alterações. Os exames\nlaboratoriais mostram: TSH: 18,0 mUl/L (VR: 0,45-4,5) e T4 livre: 0,5 ng/dL (VR: 0,6-4,5). É\nCORRETO afirmar que:","options":{"A":"A paciente está em hipotireoidismo subclínico, o que não justifica os sintomas. Outras causas\ndevem ser investigadas.","B":"É necessário verificar se a administração da levotiroxina está sendo feita da forma preconizada.","C":"Os sintomas podem ser pelo hipotireoidismo, pois a paciente recebeu dose insuficiente de\nlevotiroxina para o seu peso, devendo-se aumentar a dose.","D":"Os sintomas podem ser pelo hipotireoidismo, devendo ser associada reposição de T3, pois é\npossível que a paciente apresente defeito na desiodase responsável pela conversão de T4 em T3."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-308295","number":"308295","sourceNumber":"308295","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A hiperplasia adrenal congênita (HAC) é uma doença com significativa\nmorbimortalidade, frequentemente subdiagnosticada.\nSobre a HAC, marque a alternativa incorreta.","options":{"A":"A HAC é um conjunto de doenças, de herança autossômica recessiva, potencialmente letal,\nresultantes da deficiência de uma das\nenzimas responsáveis pela síntese de cortisol nas glândulas\nadrenais.","B":"A HAC faz parte da triagem neonatal em nosso estado, através do teste do pezinho.","C":"As formas clínicas da HAC são tradicionalmente divididas em dois grandes grupos: Forma\nclássica e Forma não clássica.","D":"A Forma não clássica, cujos sintomas se manifestam ao nascimento, é subdividida em forma\nperdedora de sal, e possui como sintomas a virilização da genitália externa, surgimento precoce\ndos pêlos pubianos e aumento da massa muscular."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-281961","number":"281961","sourceNumber":"281961","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No que se refere a tumores de tireoide, está incorreto:","options":{"A":"Em relação aos tumores anaplásicos (carcinoma indiferenciado), a maioria dos pacientes\nmorrem por metástase óssea (a distância), após 2 anos de diagnóstico.","B":"Carcinoma papilífero ocorre em jovens e tem crescimento lento.","C":"No carcinoma folicular, o prognóstico depende além do padrão histológico, da idade, sexo e\nextensão do tumor no momento do diagnóstico.","D":"Carcinoma anaplásico ocorre principalmente na idade adulta tardia e corresponde a cerca de 1%\ndos tumores da tireoide."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-258153","number":"258153","sourceNumber":"258153","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A vitamina D exerce um importante papel na homeostase do cálcio. A vitamina D:","options":{"A":"Tem no calcidiol sua forma mais ativa.","B":"Sofre um primeiro processo de metabolização no fígado pela enzima 1-?-hidroxilase.","C":"Após primeira etapa de metabolização é transportada ao pulmão para segunda etapa de\nhidroxilação.","D":"Após ser hidroxilada pela 24-?-hidroxilase atuará no osteoblasto."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-257906","number":"257906","sourceNumber":"257906","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino, de 64 anos, com diagnóstico de hipotireoidismo há vários\nanos, com dose estável de levotiroxina (75\nmicrogramas/dia). Sempre em eutiroidismo na avaliação\nhormonal realizada semestralmente. Há nove meses, vem apresentando aumento de peso\ngradativo (cerca de 7 kg) e há seis meses início de sintomas gastrointestinas. Realizado o\ndiagnóstico de doença do refluxo. Orientada a realizar medidas de mudanças no estilo de vida e\niniciado tratamento com pantoprazol - 40 mg/dia. Exame atual de função tireoidiana com T4 livre de\n0,8 ng/dL (VR: 0,89 - 1,76 ng/dL) e TSH de 11,5 µUI/mL (VR: 0,48-5,6 µ UI/mL). Nesse caso, qual a\nconduta inicial mais correta para essa paciente?","options":{"A":"Avaliar aderência através de teste de absorção de levotiroxina.","B":"Manter dose de levotiroxina, observando as elevações discretas de TSH, que são características\nfisiológicas no paciente idoso.","C":"Aumentar dose de levotiroxina, ajustando para as variáveis do aumento de peso e provável\ndiminuição da absorção pela elevação do pH gástrico.","D":"Acrescentar triiodotironina (T3) para melhor supressão do eixo."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-273131","number":"273131","sourceNumber":"273131","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Corticoide ou corticosteroide é um grupo de hormonas esteroides produzidas pelas\nglândulas suprarrenais ou a derivados sintéticos destas. Se dividem em glicocorticoides,\nmineralocorticoides e 17-cetosteroides. Considerando o enunciado, é CORRETO afirmar:","options":{"A":"A descontinuidade do tratamento deve ocorrer de forma súbita.","B":"Apresentam efeito orexígeno e euforizante.","C":"São utilizados somente no tratamento da dor associada a lesões traumáticas e neoplásicas do\nsistema nervoso periférico.","D":"Podem ser empregados apenas por VO (Dexametasona, Deflazacort, Prednisolona) e IM\n(Hidrocortisona, Dexametasona, Betametasona, Metilprednisolona)."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-281980","number":"281980","sourceNumber":"281980","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A doença que se apresenta com bócio, exoftalmia, dermopatia e aumento na produção\ndos hormônios tireoidianos é a:","options":{"A":"Doença de Graves.","B":"Tireoide de Hashimoto.","C":"Tireoide de Riedel.","D":"Tireoide de Quervain."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-258172","number":"258172","sourceNumber":"258172","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Homem de 85 anos, com hipertensão e dislipidemia, veio encaminhado por apresentar\nTSH: 7,5 mUI/L (0,4?4,0). Repetiu exames:\nTSH: 6,4 mUI/L (0,4?4,0), T4 livre: 1,2 ng/dl (VR:\n0,8?1,8), anticorpos antitireoperoxidase e antitireoglobulina negativos. Nesse caso, qual é a\nconduta mais apropriada?","options":{"A":"Observar sem reposição de levotiroxina e repetir os exames com intervalo de seis meses.","B":"Iniciar levotiroxina em dose baixa com aumento gradual até dose efetiva.","C":"Iniciar dose plena de levotiroxina.","D":"Prescrever lugol a 5%; três gotas por dia durante 30 dias e repetir função tireoidiana."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-281284","number":"281284","sourceNumber":"281284","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"É a causa mais comum de Hiperparatireoidismo Primário:","options":{"A":"Adenoma.","B":"Hiperplasia primária.","C":"Carcinoma.","D":"Tireoidite."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-274476","number":"274476","sourceNumber":"274476","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente 26 anos, sexo feminino vem ao pronto atendimento com queixa de mal estar,\nhistórico de nictúria recorrente há mais de 3 meses e que percebeu alteração domiciliar da pressão\narterial. Nega histórico de doenças prévias. Nega uso de medicações ou substâncias ilícitas. Ao\nexame físico PA 140/90 mmHg em ambos MMSS. Sem outros achados de exame físico.\n\nConsiderando o diagnóstico sindrômico descrito e os dados do contexto, a causa etiológica mais\nprovável seria:","options":{"A":"Glomerulonefrite aguda.","B":"Hiperaldosteronismo primário.","C":"Feocromocitoma.","D":"Estenose de artéria renal."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-274477","number":"274477","sourceNumber":"274477","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente 26 anos, sexo feminino vem ao pronto atendimento com queixa de mal estar,\nhistórico de nictúria recorrente há mais de 3 meses e que percebeu alteração domiciliar da pressão\narterial. Nega histórico de doenças prévias. Nega uso de medicações ou substâncias ilícitas. Ao\nexame físico PA 140/90 mmHg em ambos MMSS. Sem outros achados de exame físico. Qual dado\ndiagnóstico possui baixa sensibilidade na avaliação clínica em pacientes com o referido\ndiagnóstico?","options":{"A":"Nível sérico de K+ abaixo do valor de referência.","B":"Nível sérico de aldosterona.","C":"Nível sérico de renina.","D":"Relação aldosterona/renina."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-274778","number":"274778","sourceNumber":"274778","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente, 38 anos, sexo masculino, dá entrada no pronto atendimento conduzido por\nfamiliares devido quadro de letargia há 12 horas. O mesmo não consegue se comunicar bem no\nmomento. Familiares referem que paciente vem apresentando, há 3 meses, dificuldade de\nconcentração, mudança de humor e se comportando diferente do habitual. Além disso, referem que\npaciente apresentou perda de peso nos últimos 2 meses. O mesmo não apresenta histórico de\nantecedentes pessoais. Ao exame físico, o que chama atenção é, além do emagrecimento,\nmudança da pigmentação na palma das mãos e em mucosa oral, com lesões hipercrômicas.\n\nConsiderando o contexto do quadro clínico, a principal hipótese diagnóstica e a causa da\nmanifestação inicial descrita é:","options":{"A":"neoplasia endócrina múltipla tipo 1 / hipomagnesemia.","B":"insuficiência supra renal / hipercalcemia.","C":"tuberculose ganglionar / hiponatremia.","D":"acidose tubular renal tipo V / hiponatremia."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-281998","number":"281998","sourceNumber":"281998","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O nódulo solitário da tireoide é uma patologia na maioria das vezes benigna, entretanto\no câncer de tireoide é sempre uma\npossibilidade. No manejo do nódulo solitário da tireoide, qual\ndas opções está certa?","options":{"A":"O exame físico não é útil, pois dificilmente estes nódulos são palpáveis.","B":"O ultrassom não consegue diferenciar se o nódulo é cístico ou sólido.","C":"Na suspeita de um carcinoma medular, os níveis de calcitonina devem ser dosados.","D":"A biópsia aspirativa por agulha fina (BAAF) só é útil quando o nódulo for sólido."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-281288","number":"281288","sourceNumber":"281288","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Incidentaloma de adrenal é definido por um nódulo ou massa incidental da suprarrenal\nencontrado em um exame de imagem do abdome realizado para investigação de queixas não\nrelacionadas a esta glândula. Das alternativas abaixo, assinale a que apresenta a característica\ntomográfica sugestiva de benignidade para incidentaloma de adrenal.","options":{"A":"Tamanho > 6 cm.","B":"Presença de conteúdo cístico intra-lesional.","C":"Invasão da veia cava inferior.","D":"Densidade menor que 1 UH (Unidade Hounsfield)."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-277434","number":"277434","sourceNumber":"277434","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma mulher de 22 anos apresenta ciclos menstruais irregulares há cerca de 10 meses,\ncom períodos de amenorreia, negando uso de\nmedicamentos. Não tem parceiros sexuais há 2\nanos. Os exames físico geral e ginecológico eram normais. A dosagem de prolactina ETA elevada\n(150ng/dL) revelou TSH e T4 livres normais. A ressonância magnética de sela túrcica revelou um\nmacroadenoma hipofisário. A conduta é:","options":{"A":"uso de agonistas da dopamina","B":"uso de agonistas do GnRH","C":"uso de contraceptivos hormonais orais","D":"radioterapia"},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-273195","number":"273195","sourceNumber":"273195","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A doença suprarrenal que consiste na alteração física e mental causada pelo excesso\nde cortisol no organismo por um longo período,\nque causa ganho de peso, diabetes, hipertensão,\nface de lua cheia e é diagnosticada por meio de exames de sangue, urina ou saliva é a(o):","options":{"A":"Hiperaldosteronismo.","B":"Síndrome de Cushing.","C":"Insuficiência adrenal.","D":"Hiperplasia adrenal congênita."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-241686","number":"241686","sourceNumber":"241686","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 26 anos é admitida no pronto-atendimento com queixa de taquicardia. Ao\nexame físico, apresenta exoftalmia, mãos\númidas e trêmulas, FC: 140 bpm, Tax 37,1°C. O exame\nneurológico identificou desorientação, agitação e hiperreflexia. Medicada na internação com\npropiltiouracil. A estratégia para inibir a liberação do hormônio pré-formado consiste na\nadministração de:","options":{"A":"amiodarona.","B":"iodeto de potássio.","C":"metimazol.","D":"propranolol.","E":"verapamil."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-231933","number":"231933","sourceNumber":"231933","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma paciente de 39 anos, branca, secretária executiva em uma multinacional, refere\nalteração nos olhos após viagem ao exterior, a trabalho. Refere antecedente de tireoidopatia\ntratada há mais de 3 anos e não sabe referir o medicamento utilizado na época, mas nega uso de\nradioiodo e cirurgia na região tireoidiana. Além das alterações oculares, refere estar com insônia,\nirritação e palpitações. Sem outras queixas e sem outros antecedentes patológicos, refere\ntabagismo, mas nega etilismo e uso de medicações no momento. Ao exame físico: exoftalmo\ndiscreto bilateral, lagoftalmo bilateral, tremores de pálpebras e extremidades, bócio difuso, PA =\n160x70 mmHg, FC = 120 bpm, mais nada digno de nota. Trouxe exames laboratoriais solicitados\npelo médico do trabalho: TSH suprimido com T4 livre elevado, hemograma e funções renal e\nhepática dentro da normalidade. Assinale a alternativa correta:","options":{"A":"o hipertireoidismo subclínico que a paciente apresenta deve ser tratado com radioiodoterapia\nseguida pelo uso de tireia, pois já apresentou esse\nquadro","B":"o diagnóstico de hipotireoidismo deve ser pensado, pois a paciente já apresentou um quadro\nanterior e a recorrência justifica o seu tratamento imediato","C":"no momento, a conduta inicial pode ser feita com o emprego de medicações da classe das\ntioureias ou tionamidas e solicitação de exames de controle","D":"o tratamento com levotiroxina deve ser iniciado imediatamente, pois a paciente apresenta\nsintomatologia e exames laboratoriais alterados","E":"o quadro clínico e laboratorial sugere o diagnóstico de doença de Basedow-Graves e necessita\nde tratamento imediato com levotiroxina sódica e\npropranolol, seguido por cirurgia para o\ntratamento definitivo"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-241687","number":"241687","sourceNumber":"241687","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 32 anos em investigação para astenia crônica. Na avaliação laboratorial,\nencontra-se TSH < 0,01 mcU/L e T4 livre < 0,1 ng/ml. A próxima etapa da investigação clínica\nbaseia-se em:","options":{"A":"cintilografia da tireoide.","B":"anticorpo antirreceptor de tireotrofina (TRAb).","C":"anticorpo antitireoperoxidase (anti-TPO).","D":"ultrassonografia da tireoide.","E":"ressonância magnética da sela turca."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-231934","number":"231934","sourceNumber":"231934","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No pós-operatório de uma paciente submetida a tireoidedectomia total por nódulo\ntireoidiano suspeito, deve-se estar atento às seguintes complicações, exceto:","options":{"A":"compressão traqueal","B":"estridor respiratório","C":"hipercalcemia","D":"insuficiência respiratória","E":"sangramento"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-254212","number":"254212","sourceNumber":"254212","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mariana acompanha o ambulatório de cardiologia e hoje recebe 4 pacientes, que\nreceberão sua primeira avaliação com\nespecialistas, após diagnóstico recente de hipertensão.\nPaciente 1 - homem, 49 anos, relatos de valores elevados de PA há cerca de 10 anos, sem\ntratamento ou seguimento; exames alterados: presença de microalbuminúria. Paciente 2 - mulher,\n32 anos, antecedente de nódulo de adrenal em seguimento conservador; exames alterados:\nhipercalemia. Paciente 3 - homem, 35 anos, apresenta episódios de cefaleia, sudorese, palpitação,\nassociados a picos hipertensivos. Paciente 4 - homem, 55 anos, apresenta ao exame físico\npresença de sopro abdominal. Baseado nos dados acima, assinale alternativa que indica o paciente\nque Mariana deveria suspeitar de HAS secundária e a etiologia mais provável:","options":{"A":"Paciente 1 - glomerulonefrite primária.","B":"Paciente 2 - hiperaldosteronismo.","C":"Paciente 3 - feocromocitoma.","D":"Paciente 4 - aneurisma de aorta."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-246522","number":"246522","sourceNumber":"246522","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher, 45 anos, apresentando quadro de irritabilidade, alopecia, intolerância ao calor,\ntaquicardia, proptose palpebral, foi submetida à avaliação laboratorial. Qual resultado melhor se\nencaixa ao quadro clínico?","options":{"A":"TSH elevado, T4 livre elevado, T3 diminuído.","B":"THS elevado, T4 livre diminuído, T3 diminuído","C":"TSH suprimido, T4 livre diminuído, T3 diminuído.","D":"TSH suprimido, T4 livre aumentado, T3 aumentado.","E":"TSH elevado, T4 livre diminuído, T3 aumentado."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-249842","number":"249842","sourceNumber":"249842","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"M.D.S.N., de 70 anos, do sexo feminino, chega ao pronto-socorro com queixa de\nformigamentos e dormência em extremidades, com início há um dia. Refere também fadiga e\nsensação de palpitações. Não apresenta outras queixas e estava assintomática antes do início do\nquadro. O exame físico geral é normal, com exceção de incisão em região cervical anterior, que,\nquando interrogada, a paciente diz se dever a uma cirurgia realizada há cinco dias, \"para retirar a\ntireoide\", não sabendo informar mais detalhes. Tem como comorbidades, transtorno de ansiedade\ngeneralizada e diabetes mellitus. O diagnóstico e a etiologia para o caso apresentado são,\nrespectivamente:","options":{"A":"hipercalcemia - adenoma de paratireoides.","B":"polineuropatia periférica - diabetes mellitus.","C":"hipocalcemia - hipoparatireoidismo pós-manipulação.","D":"crise de ansiedade - síndrome do pânico."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-248904","number":"248904","sourceNumber":"248904","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Nas situações de diagnóstico do hipotireoidismo e do hipertireoidismo primários, a\ndosagem sérica do TSH é o teste mais confiável.\nPorém, em determinadas situações, essa\ndosagem pode apresentar algumas limitações na avaliação da função tireoidiana. Dessa forma:","options":{"A":"níveis séricos diminuídos de hormônios tireoidianos são acompanhados de concentrações\nelevadas de TSH nos usuários de biotina em altas\ndoses, sem correlacionar com doença clínica","B":"pacientes com hipotireoidismo sem adesão ao tratamento e que fazem uso adequado de\nlevotiroxina semanas antes da coleta de sangue\npodem apresentar valores séricos baixos de TSH e\naltos de hormônios tireoidianos","C":"pacientes com disfunção tireoidiana crônica e grave podem apresentar o TSH ainda alterado,\napesar da normalização dos níveis séricos\ndos hormônios tireoidianos","D":"medicações como dopamina e glicocorticoides têm ação estimuladora na secreção do. TSH,\npodendo mimetizar o hipertireoidismo primário"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-254216","number":"254216","sourceNumber":"254216","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente em investigação de doença adrenal retorna com exames solicitados na última\nconsulta: aldosterona elevada (mesmo após teste com infusão salina); atividade plasmática da\nrenina reduzida; sódio urinário elevado; cateterismo de veias adrenais com coleta de sangue para\ndosagem de aldosterona revelou secreção unilateral de aldosterona. Qual o provável diagnóstico\nda paciente?","options":{"A":"Síndrome de Liddle.","B":"Síndrome de Conn.","C":"Hiperaldosteronismo idiopático.","D":"Hiperaldosteronismo secundário."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-247396","number":"247396","sourceNumber":"247396","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Atualmente, observa-se um aumento da prevalência de nódulos tireoidianos\ndiagnosticados em pacientes, possivelmente\npelo avanço dos métodos de imagem. Quais dados da\nanamnese e exame físico sugerem maior risco de malignidade do nódulo tireoidiano?","options":{"A":"Nódulo móvel, não aderido a planos profundos.","B":"Mulher com 40 anos de idade.","C":"Nódulo com crescimento lento e pouco volumoso.","D":"Síndromes Hereditárias como a síndrome de Cowden."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-249850","number":"249850","sourceNumber":"249850","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"No hipertireoidismo apatético,","options":{"A":"em crianças, há predomínio de sintomas adrenérgicos, como irritabilidade, nervosismo,\nagressividade e sudorese.","B":"em idosos, são predominantes sintomas cardiovasculares, depressão, labilidade emocional,\nprostração e apatia.","C":"em crianças, são observados diminuição da velocidade de crescimento, baixa estatura e baixo\npeso.","D":"em idosos, são recorrentes os sintomas adrenérgicos, como agitação, nervosismo,\nagressividade e sudorese."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-232227","number":"232227","sourceNumber":"232227","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente de 51 anos, do sexo masculino, com diagnóstico\nde diabetes mellitus tipo 2 e HAS, há cinco\nanos. Durante consulta de rotina com endocrinologista,\napresentou queixa de artralgia em várias articulações associada a hiperidrose e, ao exame físico,\npresença de discreto prognatismo, o que suscitou hipótese diagnóstica de acromegalia, confirmada\nposteriormente com a dosagem de GH basal de 7,6 ng/mL (VR homem: inferior ou igual a 3,00) e\nIGF-1 de 446 ng/mL (VR 50 a 54 anos: 48 a 209). A ressonância magnética revelou massa selar\nsólida, de 1,9 cm em seu maior diâmetro, sem expansão extrasselar, nem compressão de quiasma\nóptico. Nesse caso, qual tratamento primário de escolha deve ser indicado para esse paciente?","options":{"A":"Cirurgia transesfenoidal, realizada preferencialmente em centro especializado de referência.","B":"Antagonista do receptor de GH, representado pelo pegvisomanto (PEG).","C":"Análogos de somatostatina, como o octreotide.","D":"Agonistas dopaminérgicos, como a cabergolina."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-232228","number":"232228","sourceNumber":"232228","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente do sexo feminino, de 44 anos, com nódulo\ntireoidiano palpável durante consulta de rotina\ncom ginecologista. Solicitada ultrassonografia da\nregião cervical, que evidenciou a presença de nódulo sólido, hipoecoico, bem circunscrito, com 2,3\ncm. O exame de cintilografia tireoidiana está indicado em qual situação?","options":{"A":"Bethesda categoria V (suspeito para malignidade) na punção aspirativa com agulha fina guiada\npelo ultrassom.","B":"Bethesda categoria I (não diagnóstica) na punção aspirativa com agulha fina guiada pelo\nultrassom.","C":"Dosagem de anticorpo antirreceptor de TSH (TRAb) positiva.","D":"Presença de TSH suprimido."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-234328","number":"234328","sourceNumber":"234328","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Homem de 45 anos relata perda de aproximadamente cinco kg (5% do peso) em um\nmês, após quadro com febre e odinofagia de remissão espontânea. Nega alterações oculares.\n\nSente dor cervical à palpação e à deglutição, insônia, palpitações e aumento do número de\nevacuações diárias. Refere estar em uso de\nsuplementos \"termogênicos\" para melhorar sua\ndisposição para atividades físicas, há seis meses. Traz em mãos os seguintes exames: TSH = 0,01\nuIU/ml (VR 0,5 - 4,5 uIU/ml), T4 livre = 2,77 ng/dl (VR 0,7-1,5), tireoglobulina 250 ng/ml (VR:\n\n1,5-50), antitireoperoxidase e TRAb negativos. Nesse caso, o exame que melhor elucidaria o\nquadro atual e o provável diagnóstico desse paciente são:","options":{"A":"T3 total e tireotoxicose exógena.","B":"T4 total e bócio multinodular tóxico.","C":"VHS e tireoidite subaguda.","D":"Antitireoglobulina e doença de Graves."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-229837","number":"229837","sourceNumber":"229837","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre as patologias da tireóide NÃO se pode dizer que","options":{"A":"o câncer de tireóide é patologia rara, contudo a incidência no sexo feminino pode ser até 3x mais\nfrequente, sendo o carcinoma papilífero o mais comum. A radiação ionizante na infância na região\ndo pescoço é considerada um dos principais fatores de risco e a incidência tem aumentado\ncomprovadamente pelo aumento do número de mamografias.","B":"o tratamento cirúrgico é a principal terapia no câncer de tireóide, podendo ou não estar\nassociado a linfadenectomia cervical e complementação com aplicação de iodo radioativo.","C":"os nódulos tireoideanos têm diagnóstico de benignidade em cerca de 90% dos casos e as\ncaracterísticas que sugerem benignidade incluem: bócio multinodular, nível elevado de anticorpos\nanti-tireoideanos, nódulo \"\"quente\"\" à cintilografia.","D":"a citologia por punção por agulha fina da tireóide é dado importante para condutas em nódulos\ntireoideanos e pode auxiliar no acompanhamento, podendo sugerir desde tireoidites a linfomas,\npodendo suplantar o uso da cintilografia."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-247415","number":"247415","sourceNumber":"247415","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente é readmitido no hospital no quarto dia pós-tireoidectomia total por carcinoma\npapilífero, apresentando rouquidão importante e sinal de Chvostek. A conduta mais apropriada é:","options":{"A":"observar, pois as alterações são comuns e transitórias.","B":"iniciar reposição de cálcio devido a hipoparatireoidismo.","C":"acionar o cirurgião devido à suspeita de hematoma cervical compressivo.","D":"ajustar a reposição de hormônio tireoideano, insuficiente."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-252753","number":"252753","sourceNumber":"252753","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino, 36 anos, procura atendimento referindo palpitações, tremor\nde extremidades, insônia, perda ponderal de 15 kg\nnos últimos 30 dias e diarreia. Ao exame,\nobserva-se pele quente e úmida, frequência cardíaca de 120 bpm e pressão arterial de 140 x 90\nmmhg. Exames laboratoriais mostram: TSH: 0,001 MUI/l (Valores de referência: 0,4 a 4,3); T4 livre:\n2,5 ng/dl (0,7 a 1,8)), Glicemia de jejum: 80 bpm; Colesterol total: 180 mg/dl; HD-colesterol: 47\nmg/dl ; LDL-colesterol: 100 mg/dl, triglicerídeo: 100 mg/dl. Ultrassonografia da tireoide mostra\nnódulo hiperecogênico, TI-RADS 3, de 1,2 cm, no lobo esquerdo da tireoide. Diante desse caso,\nqual exame deve ser solicitado?","options":{"A":"Cintilografia da tireoide.","B":"Punção aspirativa por agulha fina da tireoide.","C":"Teste genético para avaliação do nódulo.","D":"Ressonância nuclear magnética do pescoço."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-252757","number":"252757","sourceNumber":"252757","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino, 35 anos, procura atendimento referindo episódios\nrecorrentes de cefaleia, sudorese e\npalpitação. Portadora de hipertensão arterial de difícil controle,\nmesmo em uso de anlodipina 10 mg/dia, losartana 100 mg/dia e hidroclorotiazida 25 mg/dia. Está\nmuito preocupada, pois fez uma tomografia de abdome que mostrou uma massa na adrenal direita.\nRefere ter sido submetida a tireoidectomia total há 3 anos, por um carcinoma medular da tireoide.\nDiante do caso, quais exames seriam interessantes para o diagnóstico?","options":{"A":"Aldosterona sérica e cortisol sérico matinal.","B":"Cálcio sérico e metanefrinas urinárias.","C":"Cobre urinário e atividade de renina plasmática.","D":"Ureia e magnésio sérico."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-249511","number":"249511","sourceNumber":"249511","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 56 anos procura atendimento médico ambulatorial queixando-se de diarreia\nde início há 3 meses, perda de peso,\ncalafrios e tremores sem causa aparente. Nega febre aferida.\nQueixa-se também de baixa acuidade visual. Nega alteração de hábitos rotineiros, alimentares e\nintrodução/suspensão de drogas de uso contínuo. Notou que há aumento de seu pescoço, relatado\ncomo \"inchaço\". Na investigação apresentou tireóide aumentada difusamente à palpação, níveis de\nT4 elevado, TSH suprimido e anticorpos anti-tireoideanos não detectáveis. Ecografia de tireóide\nevidenciou glândula difusamente aumentada. A cintilografia com iodo 131 evidenciou uma área\nautônoma funcional bem localizada e restante da glândula suprimida (não captante). A principal\nhipótese diagnóstica é:","options":{"A":"Doença de Plummer.","B":"Doença de Graves.","C":"Doença de Paget.","D":"Arterite de Takayasu."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-249512","number":"249512","sourceNumber":"249512","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O tratamento curativo do carcinoma medular de tireoide é a tireoidectomia total. Faz\nparte desta cirurgia o esvaziamento cervical, importante para ressecção de possíveis lesões\nmetastáticas. Na tireoidectomia total por carcinoma medular de tireoide, mesmo que de forma\nprofilática, deve-se esvaziar o nível cervical:","options":{"A":"II","B":"III","C":"V","D":"VI"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-249513","number":"249513","sourceNumber":"249513","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 26 anos procura pronto-socorro queixando-se de forte mialgia e câimbras\nconstantes que pioraram há 1 semana. Nega febre. Nega trauma. Vem apresentando crises\nhipertensivas recorrentes, já em uso de losartana 100mg/dia, anlodipino 10mg/dia e bisoprolol\n5mg/dia, sem melhora. Após coleta de rotina laboratorial em pronto-socorro foi internada por\nhipocalemia. Submeteu-se à tomografia de abdome abaixo. O provável diagnóstico é:","options":{"A":"Leptospirose.","B":"Paraganglioma.","C":"Adenoma adrenal.","D":"Hipoaldosteronismo - NEM 1."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":["question_bank/media/medcurso/medcurso-endocrinologia-end-1/249513.png"],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-229553","number":"229553","sourceNumber":"229553","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente 76 anos, queixando-se de dor em região cervical anterior, de início há 2\nmeses, associado a abaulamento local e aparecimento de tumoração palpável e dolorosa na\nmesma região. Realizado biópsia da lesão com laudo histopatológico de neoplasia maligna mais\ngrave e agressiva de tireóide. Trata-se de:","options":{"A":"carcinoma papilífero.","B":"carcinoma metaplásico tipo II.","C":"carcinoma anaplásico.","D":"carcinoma folicular."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-229876","number":"229876","sourceNumber":"229876","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente jovem apresentando palpitação, procura cardiologista que descarta causas\ncardíacas. Suspeita de origem endocrinológica\ne solicita exames de tireoide que revelam: TSH 0.01\nmU/L, T3 250 ng/dl, T4 livre 2.5 ng/dl, T4 25ng/dl, tireoglobulina 1.0 ng/ml, cintilografia com\nbaixa\ncaptação. Valores de referência: TSH 0,3 e 4,0 mU/L, T3 80 a 180 ng/dl, T4 livre 0.7-1.8 ng/dl, T4\ntotal 4,5 a 12.6 mg/dl, tireoglobulina 2,0 a 60,0 ng/MI. O provável diagnóstico é","options":{"A":"a doença de Graves","B":"o bócio nodular tireotóxico","C":"tireoidite factícia","D":"tireoidite subaguda"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-229561","number":"229561","sourceNumber":"229561","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 53 anos, diagnosticado pelo endocrinologista com Hiperparatireoidismo\nprimário. Qual a causa MAIS comum deste\ndesequilíbrio hormonal?","options":{"A":"carcinoma medular de tireoide.","B":"neoplasia endócrina múltipla tipo 2A.","C":"neoplasia de hipófise.","D":"adenoma único de paratireoide."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-229566","number":"229566","sourceNumber":"229566","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"NÃO faz parte das causas fisiológicas de hiperprolactinemia:","options":{"A":"estresse.","B":"gestação.","C":"estimulação de mamilos.","D":"hipertiroidismo."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-252799","number":"252799","sourceNumber":"252799","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre as neoplasias da tireoide, é incorreto afirmar:","options":{"A":"Os cânceres de tireoide, em sua maioria, cerca de 90% a 95%, são classificados como tumores\nbem diferenciados, originados nas células\nfoliculares.","B":"O carcinoma papilífero é a mais comum das neoplasias da tireoide, e está geralmente associado\na bom prognóstico.","C":"O carcinoma folicular atinge uma população mais idosa em relação ao papilífero, e é mais\ncomum em mulheres, ao contrário deste último.","D":"A maioria dos pacientes com carcinoma medular de tireoide, ou predisposição sindrômica,\ndevem passar pelo menos por uma tireoidectomia\ntotal."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-205549","number":"205549","sourceNumber":"205549","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"As microcalcificações encontradas no carcinoma de tireoide representam os corpos\nformados pela calcificação de papilas. Sendo assim, podemos apenas concordar que:","options":{"A":"A presença de macrocalcificações tem alto valor preditivo positivo para malignidade.","B":"A presença de microcalcificações não tem alto valor preditivo positivo para malignidade.","C":"A presença de microcalcificações tem alto valor preditivo negativo para malignidade.","D":"A presença de microcalcificações tem alto valor preditivo positivo para malignidade."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-217004","number":"217004","sourceNumber":"217004","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre as substâncias que interferem na absorção da levotiroxina no tratamento do\nhipotireoidismo, julgue os itens a seguir. I. Carbonato de cálcio. II. Hidróxido de alumínio. III.\nOmeprazol. IV. Sulfato ferroso. Pode-se afirmar que:","options":{"A":"Apenas I e II estão certos.","B":"Apenas I e III estão certos.","C":"Apenas II, III e IV estão certos.","D":"Apenas I, III e IV estão certos.","E":"Todos estão certos."},"answer":"E","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-201669","number":"201669","sourceNumber":"201669","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente de 24 anos, do sexo masculino, apresentando\nfebre, sudorese e palpitações. Ao exame físico, a\npressão arterial encontra-se em 180/110 mmHg.\nQue exame poderia auxiliar fortemente no seu diagnóstico?","options":{"A":"Dosagem de sódio urinário.","B":"Dosagem de serotonina urinária.","C":"Dosagem de metanefrina urinária.","D":"Dosagem de creatinina urinária."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-205567","number":"205567","sourceNumber":"205567","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"As calcificações no nódulo tireoideano podem ser observadas tanto em nódulos\nbenignos quanto malignos. Sobre isso, podemos apenas CONCORDAR que:","options":{"A":"As microcalcificações encontradas no carcinoma papilíifero de tireóide representam os corpos\npsamomatosos formados pela calcificação de trombos extra-tumorais ou infarto das extremidades\nde papilas malignas.","B":"As microcalcificações encontradas no carcinoma papilíifero de tireóide representam os corpos\npsamomatosos formados pela\n\ncalcificação de trombos intra-tumorais ou infarto das extremidades de papilas benignas.","C":"As microcalcificações encontradas no carcinoma papilíifero de tireóide representam os corpos\npsamomatosos formados pela calcificação de trombos intra-tumorais, mas nunca de infarto das\nextremidades de papilas.","D":"As microcalcificações encontradas no carcinoma papilíifero de tireóide representam os corpos\npsamomatosos formados pela calcificação de trombos intra-tumorais ou infarto das extremidades\nde papilas malignas."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-205579","number":"205579","sourceNumber":"205579","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Na presença de dois ou mais nódulos tireoidianos com mais de 10 mm devem ser\npuncionados, preferencialmente, aqueles que apresentam como características ultrassonográficas\nsuspeita de lesões malignas. Sobre isso, NÃO podemos apenas concordar que:","options":{"A":"Para uma exclusão segura de malignidade em uma glândula com múltiplos nódulos com 10 mm\nou mais de diâmetro, não é recomendada a\npunção de um único nódulo.","B":"A biópsia por agulha fina (PAAF) guiada pela ultrassonografia é um importante meio diagnóstico\ndos nódulos tireoidianos, sendo um método\nsensível no diagnóstico diferencial entre lesões\nmalignas e benignas.","C":"A biópsia por agulha fina (PAAF) é o procedimento de escolha na avaliação dos nódulos\ntireoidianos.","D":"A PAAF mostrou-se igualmente factível e com acurácia semelhante dependente das dimensões\ndos nódulos, incluindo a proporção de aspirados\nnão diagnósticos."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-205581","number":"205581","sourceNumber":"205581","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O nódulo de tireóide é um achado frequente na população, são clinicamente evidentes\ne, grande parte destes nódulos, é de natureza\nbenigna, porém malignidade pode ser encontrada. A\nultrassonografia é o método de escolha para a avaliação dos nódulos tireoideanos. Possui\nsensibilidade de quase 100%, sendo superior aos outros métodos. Sobre isso, assinale a\nalternativa INCORRETA:","options":{"A":"Permite diferenciar nódulos sólidos, nos quais a incidência de malignidade é menor do que nos\nnódulos císticos e mistos, prevalece a benignidade.","B":"Apresenta custo relativamente baixo, é de fácil execução, não necessita preparo para o exame e\nnão apresenta riscos para o indivíduo.","C":"Quando associado ao uso do doppler, observa-se que determinados padrões de vascularização,\ncomo, por exemplo, predomínio vascular na\nperiferia do nódulo, sugerem benignidade.","D":"Os carcinomas diferenciados se apresentam com vascularização periférica e central, em geral\ncom predomínio desta última."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-205591","number":"205591","sourceNumber":"205591","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O estudo ultrassonográfico da região cervical é útil na avaliação de linfonodo suspeito\nde malignidade decorrente de tireóide; sendo\nADEQUADO que:","options":{"A":"Confirma o diagnóstico, quando associado à punção aspirativa e dosagem de tireoglobulina no\naspirado; mas não é importante no seguimento e avaliação da resposta terapêutica.","B":"Confirma o diagnóstico, quando associado à punção aspirativa e dosagem de tireoglobulina no\naspirado; e é importante no seguimento e avaliação da resposta terapêutica.","C":"Confirma o diagnóstico, quando associado à punção aspirativa e dosagem de tireoglobulina no\naspirado; e é importante no seguimento, mas não na avaliação da resposta terapêutica.","D":"Confirma o diagnóstico, mesmo quando não associado à punção aspirativa e dosagem de\ntireoglobulina no aspirado; e é importante no seguimento e avaliação da resposta terapêutica."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-216464","number":"216464","sourceNumber":"216464","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente procura atendimento devido a nodulação em região cervical há cerca de 6\nmeses. A USG revela nódulo tireoideano de cerca de 2 cm de consistência sólida . Exames\ntireoidianos normais. Solicitada PAAF que evidenciou presença de células tipo Hurthle. Diante do\nquadro, qual a conduta mais indicada:","options":{"A":"Seguimento semestral ultrassonográfico.","B":"Seguimento semestral com PAAF.","C":"Ablação nodular com iodo radioativo.","D":"Tireoidectomia."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-205596","number":"205596","sourceNumber":"205596","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Uma cirurgia mais ampla também estaria indicada em pacientes com historia familiar de\ncâncer da tireóide e naqueles expostos previamente a radiação ionizante. Está de acordo com o\ncontexto da conduta, apenas o item abaixo indicado:","options":{"A":"A tireoidectomia total não está indicada, devido ao aumento de risco de malignidade, em\npacientes com citologia indeterminada em\ntumores maiores que 4 cm, quando existe alto grau de\natipia celular ou quando a biopsia é suspeita de carcinoma papilífero da tireóide (em qualquer\ntamanho de nódulo).","B":"A tireoidectomia total está indicada, devido ao aumento de risco de malignidade, em pacientes\ncom citologia indeterminada em tumores maiores\nque 8 cm, quando existe alto grau de atipia\ncelular ou quando a biopsia é suspeita de carcinoma papilífero da tireóide (em qualquer tamanho\nde nódulo).","C":"A tireoidectomia total está indicada, devido ao aumento de risco de malignidade, em pacientes\ncom citologia indeterminada em tumores maiores\nque 4 cm, quando existe alto grau de atipia\ncelular ou quando a biopsia é suspeita de carcinoma papilífero da tireóide (em qualquer tamanho\nde nódulo).","D":"A tireoidectomia total está indicada, devido ao aumento de risco de malignidade, em pacientes\ncom citologia indeterminada em tumores maiores\nque 1 cm, quando existe alto grau de atipia\ncelular ou quando a biopsia é suspeita de carcinoma papilífero da tireóide (em qualquer tamanho\nde nódulo)."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-216686","number":"216686","sourceNumber":"216686","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 28 anos queixa irritação, tremores, nervosismo e perda ponderal de 7kg em 2\nmeses, após ter iniciado tratamento para emagrecimento. O exame físico revela taquicardia e\nhipertensão arterial. Os exames complementares apresentaram TSH indetectável, VHS normal,\ntireoide homogênea a ultrassonografia, e captação baixa de iodo marcado à cintilografia. O\ndiagnóstico para esse quadro é:","options":{"A":"Tireoidopatia factícia.","B":"Doença de Basedow-Graves.","C":"doença de Plummer.","D":"Tireoidite de De Quervain."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-201731","number":"201731","sourceNumber":"201731","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Leia o caso clínico a seguir. Mulher de 42 anos procura assistência médica por causa\nde alteração de função tireoidiana. Refere\natividade física intensa e que, após um treino,\napresentou dor lombar de grande intensidade com irradiação para parte posterior de membro\ninferior esquerdo, sendo prescritos fisioterapia e glicocorticoide injetável intramuscular de\ndepósito\nhá uma semana (três ampolas). Ciclos menstruais regulares, em uso de contraceptivos orais. PA =\n120 x 80 mmHg; FC = 70 BPM, com ritmo cardíaco regular. Tireoide normopalpável. Traz os\nexames: TSH = 0,3 mUI/L (VR 0,4 a 4,0); T4 livre = 1,4 ng/dl (VR 0,8 a 1,9); T3 = 1,4 ng/ml (VR 0,7\na 1,8); TRAb = 0,1 UI/L (VR < 1,75); ATPO = 30 UI/ml (VR < 35); antitireoglobulina = 15 UI/ml (VR <\n20). Qual é a provável causa da alteração no TSH desta paciente?","options":{"A":"Doença de Graves.","B":"Uso de contraceptivo oral.","C":"Hashitoxicose.","D":"Uso de glicocorticoide."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-214970","number":"214970","sourceNumber":"214970","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A doença de Graves, a forma mais comum de hipertireoidismo, quando acomete\nmulheres grávidas apresenta características e cuidados específicos. Assinale a alternativa\nincorreta:","options":{"A":"a crise tireotóxica, decorrente do hipertireoidismo na gravidez, exige cuidados intensivos devido\nà extrema gravidade","B":"o propranolol pode ser usado, porém em baixas doses e por um curto e período de tempo, para\nevitar efeitos prolongados sobre o feto, como bradicardia ou retardo de crescimento intrauterino","C":"o propiltiouracil não deve ser indicado para o tratamento no 1° trimestre, devido ao risco de\nembriopatia acentuada","D":"a administração de iodo-131, como forma definitiva de tratamento do hipertireoidismo, é\ncontraindicada durante a gravidez"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-216449","number":"216449","sourceNumber":"216449","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Marque a alternativa INCORRETA:","options":{"A":"O hipotireoidismo primário é uma importante causa de hiperprolactinemia.","B":"Os achados clínicos típicos da hiperprolactinemia são: amenorreia e galactorreia.","C":"A principal causa de hiperprolactinemia é o tumor hipotalâmico produtor de prolactina.","D":"O tratamento da hiperprolactinemia por adenoma hipofisário produtor de prolactina é feito com o\nuso de agonistas dopaminérgicos."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-214119","number":"214119","sourceNumber":"214119","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher portadora de cancêr de mama e em uso de dexametasona (10mg) em cada\nseção de quimioterapia, evoluiu com aumento\nde glicemia de jejum (200mg/dl) hemoglobina glicada\nde 8% e triglicérides de 200mg. Diante dessa situação as medidas iniciadas são","options":{"A":"reduzir ou suspender a dexametasona, estimular a realização de exercícios físicos, reeducação\nalimentar e metiformina.","B":"manter a dexametasona na mesma dose, pois ela não interfere na glicemia e inicar o uso de\ninsulina NPH.","C":"reduzir ou suspender a dexametasona e iniciar uso de insulina glargina.","D":"manter a dexametasona ajustando a dose, estimular realização de exercícios físicos e\nreeducação alimentar."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-217088","number":"217088","sourceNumber":"217088","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre os distúrbios da tireoide, julgue os seguintes itens. I. O hipotireoidismo\ncongênito\né a principal causa evitável de deficiência\nmental, com ocorrência de 1 a cada 3000 ou 4000\n\nrecém-nascidos, aproximadamente. II. O hipotireoidismo adquirido tem início insidioso, podendo\nocorrer em qualquer fase da vida. III. Na\nfaixa etária pediátrica, a doença de Graves responde por\nmais de 90% dos casos de hipertireoidismo. É mais prevalente no sexo feminino e sua incidência\ntem pico entre 11 e 15 anos. Pode-se afirmar que:","options":{"A":"Todos os itens estão certos.","B":"Apenas os itens I e II estão certos.","C":"Apenas os itens I e III estão certos.","D":"Apenas os itens II e III estão certos.","E":"Apenas o item II está certo."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-214154","number":"214154","sourceNumber":"214154","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Algumas sindromes genéticas estão associadas a neoplasias, de forma que a Sindrome\nNeuroendocrina Multipla tipo 2 (MEN-2) está associada a mutação ativadora do proto-oncogene\nRET. As principais manifestações clínicas desta sindorme incluem:","options":{"A":"hiperparatireoidismo primário, tumor carcinoide produtor de somatostaina e feocromocitoma.","B":"feocromocitoma, hipertireoidismo e hiperpartiroidismo pirmário.","C":"feocromocitoma, tumor carcinoide produror de somatostatina e hiperparatireoidismo primário.","D":"hiperparatireoidismo primário, feocromocitoma e carcinoma medular de tireoide."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-205585","number":"205585","sourceNumber":"205585","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre as características clínicas das Síndromes de\nNeoplasias Endócrinas Múltiplas:","options":{"A":"A Síndrome NEM2A está associada à feocromocitoma e hiperparatiroidismo.","B":"A Síndrome NEM2B associa-se a neuromas mucosas e anormalidades esqueléticas.","C":"A Síndrome NEM2B tem padrão de herança autossômico dominante e são causadas por\nmutações no proto-oncogene RET no cromossomo 10.","D":"A anormalidade endócrina mais comum é a NEM2."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-205648","number":"205648","sourceNumber":"205648","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Medicamento que NÃO aumenta a prolactina é:","options":{"A":"Levodopa.","B":"Metildopa.","C":"Metoclopramida.","D":"Sulpirida."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-178793","number":"178793","sourceNumber":"178793","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Qual a manifestação mais comum da síndrome de Cushing?","options":{"A":"Obesidade centrípeta.","B":"Hipertensão.","C":"Fadiga e Fraqueza.","D":"Edema.","E":"Estrias violáceas."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-173543","number":"173543","sourceNumber":"173543","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 27 anos procura assistência médica por causa de palpitações, sudorese e\ntremores de extremidades há 72 horas. Apresenta retração palpebral, sem proptose. A tireoide é\naumentada de volume difusamente e dolorosa à palpação, sem eritema. FC = 116 bpm. PA =\n160x70 mmHg. Exames laboratoriais: TSH = 0,03 (VR 0,4-4,0 mUI/L); T4 total = 18 (VR 6 a 12\nmcg/dL); T4 livre = 3,9 (VR 0,7 a 1,8 ng/dL); T3 = 280 (VR 70 a 180 ng/dL). TRAb = 1,0 (VR < 1,75\n\nUI/mL). Nesse caso, o paciente deve","options":{"A":"iniciar antibioticoterapia de imediato e realizar US cervical para drenar os prováveis abscessos\ntireoidianos.","B":"apresentar VSH, tireoglobulina e proteína C reativa elevados e espera-se uma captação de iodo\nradioativo em 24 horas inferior a 5%.","C":"inicar droga antitireoidiana imediatamente, por se tratar de doença de Graves.","D":"estar em uso de hormônio tireoidiano exógeno, o que pode ser confirmado com a dosagem da\ntireoglobulina elevada."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-174113","number":"174113","sourceNumber":"174113","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Nas situações de diagnóstico do hipotireoidismo e do hipertireoidismo primários, a\ndosagem sérica do TSH é o teste mais confiável.\nPorém, em determinadas situações, essa\ndosagem pode apresentar algumas limitações na avaliação da função tireoidiana. Dessa forma:","options":{"A":"Níveis séricos diminuídos de hormônios tireoidianos são acompanhados de concentrações\nelevadas de TSH nos usuários de biotina em altas\ndoses, sem correlacionar com doença clínica.","B":"Pacientes com hipotireoidismo sem adesão ao tratamento e que fazem uso adequado de\nlevotiroxina semanas antes da coleta de sangue\npodem apresentar valores séricos baixos de TSH e\naltos de hormônios tireoidianos.","C":"Pacientes com disfunção tireoidiana crônica e grave podem apresentar o TSH ainda alterado,\napesar da normalização dos níveis séricos\ndos hormônios tireoidianos.","D":"Medicações como dopamina e glicocorticoides têm ação estimuladora na secreção do TSH,\npodendo mimetizar o hipertireoidismo primário."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-185110","number":"185110","sourceNumber":"185110","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Sobre a síndrome de Cushing não iatrogênica, verifica-se o seguinte:","options":{"A":"As principais causas são os tumores de hipófise ou a secreção ectópica de ACTH.","B":"Apesar do cortisol matinal elevado, o cortisol na urina de 24h está reduzido.","C":"O teste com doses baixas de dexametasona não suprime o cortisol e é útil para o diagnóstico.","D":"Obesidade, alteração menstrual, hirsutismo, hipotensão e edema são comuns em mulheres."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-185127","number":"185127","sourceNumber":"185127","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"A respeito dos efeitos da amiodarona sobre a tireoide, sabe-se que:","options":{"A":"a ação da amiodarona sobre a tireoide se dá tanto pelo excesso de iodo quanto pela inflamação\n(tireoidite).","B":"a maioria dos pacientes desenvolve hipotireoidismo ao longo do tratamento.","C":"mesmo em doses mais baixas de amiodarona, a incidência de distúrbios da tireoide é alta.","D":"o hipertireoidismo é a manifestação clínica mais comum e normalmente requer suspensão da\nmedicação."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-186481","number":"186481","sourceNumber":"186481","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"M.T.N., 36 anos, sexo feminino, casada, procura atendimento referindo episódios\nrecorrentes de palpitação, tremor de\nextremidades, insônia e perda ponderal. Nega uso de\nmedicamentos. Refere ter tido um parto normal há 4 meses. Nega outras comorbidades. Ao exame:\ntireoide discretamente aumentada de tamanho à palpação, sem nódulos, ausência de exoftalmia,\ndiscreto tremor de extremidades. Exames laboratoriais: TSH: 0,01 Ul/ml (valor de referência: 0,3 a\n4,2 mUl/ml), T4 livre: 1,9 ng/dl (valores de referência: 0,7 a 1,8 ng/dl), anticorpo antirreceptor\nde\nTSH (TRAB): 0,3 Ul/L (valor de referência: < 1,75 Ul/L). Captação do iodo radioativo mostra uma\nglândula com baixa captação de iodo. Diante do caso, marque a alternativa correta:","options":{"A":"O tratamento deve ser feito com propilitiouracil.","B":"A paciente tem um quadro clínico típico de doença de Graves.","C":"Nesses casos, geralmente o anticorpo antitireoperoxidase (anti-TPO) é positivo.","D":"O tratamento deve ser feito com iodo radioativo."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-186495","number":"186495","sourceNumber":"186495","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"O tratamento de hipotireoidismo subclínico ainda é assunto controverso. Aceita- se\ncomo indicações para o tratamento EXCETO:","options":{"A":"TSH (hormônio estimulador da tireoide) maior que 10 UI/L.","B":"Anticorpo anti-peroxidase positivo.","C":"Se gravidez.","D":"Insônia."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-187569","number":"187569","sourceNumber":"187569","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente submetida a tireoidectomia total por bócio volumoso evoluiu, no primeiro\npós-operatório, com quadro de parestesia peri-oral com sinal de Chvostek presente e espasmos\nmusculares. A causa provável e tratamento indicado para o quadro clínico apresentado são a","options":{"A":"hipocalcemia secundária a tireoidectomia e reposição com levotiroxina.","B":"hipocalcemia secundária a paratireoidectomia inadvertida e reposição com levotiroxina e cálcio\noral domiciliar.","C":"hipocalcemia secundária a paratireoidectomia inadvertida e reposição imediata de cálcio\nendovenoso.","D":"hipocalcemia secundária a tireoidectomia e reposição oral de cálcio e levotiroxina."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-187613","number":"187613","sourceNumber":"187613","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 60 anos, sexo feminino, foi submetida a tireoidectomia total por bócio\nmergulhante volumoso e cirurgia tecnicamente difícil. Após extubação paciente evoluiu com franca\ninsuficiência respiratória sendo necessária ventilação sem resposta e nova intubação com achado\nde paresia de prega vocal unilateral. Neste caso a provável causa é lesão de nervo.","options":{"A":"laríngeo inferior.","B":"laríngeo recorrente unilateral,","C":"vago.","D":"vago e laríngeo superior."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-187606","number":"187606","sourceNumber":"187606","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente adulto jovem, com diagnóstico prévio de hipertensão primária procurou\natendimento médico devido à queixa de\ntaquicardia, cefaleia e sudorese. Tendo em vista não ter\nmelhorado com o anti-hipertensivo prescrito no posto de saúde, insistiu em nova consulta médica\nonde foi realizada ultrassonografia com achado de tumoração em adrenal esquerda. Na suspeita de\nfeocromocitoma a conduta é","options":{"A":"suspender medicações e pesquisa de metanefrinas e catecolaminas na urina, tomografia de\nabdome.","B":"suspender medicações e pesquisa de metanefrinas e catecolaminas no soro, ressonância\nmagnética de abdome.","C":"manter medicações e solicitar pré operatório e tomografia de abdome.","D":"manter medicações e pesquisa de metanefrinas e catecolaminas no soro, ressonância\nmagnética de abdome."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-157027","number":"157027","sourceNumber":"157027","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 25 anos com irregularidade mestrual e prolactina sérica de 80 ng/ml NÃO\nnecessita inicialmente de qual medida?","options":{"A":"Pesquisa de adenoma hipofisário por ressonância nuclear magnética.","B":"Repetir o exame.","C":"Pesquisar causa medicamentosa.","D":"Solicitar TSH."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-158486","number":"158486","sourceNumber":"158486","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente masculino 35 anos, apresenta perda de peso, intolerância ao calor,\npalpitações, tremores e defecação excessiva há 6\nmeses, e há dois meses notou aumento volume\ndo pescoço e olhos discretamente ?saltados?. Qual o possível diagnóstico para este paciente?","options":{"A":"Síndrome de Cushing.","B":"Insuficiência adrenal.","C":"Doença de Graves.","D":"Feocromocitoma."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-150195","number":"150195","sourceNumber":"150195","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo masculino foi submetido a TC de crânio devido a cefaleia, sendo\nsugerido imagem em região hipofisária. Realizada\nRM de hipófise que evidenciou lesão de 0,5 cm à\ndireita da hipófise, sem extensão extra-hipofisária. Durante avaliação com endocrinologista, o\npaciente encontrava-se assintomático, com exame físico normal, sem antecedentes pessoais\npatológicos e sem uso de medicações. De acordo com as recomendações da Endocrino Society, o\nseguimento do paciente deverá ser feito com:","options":{"A":"Realização de campimetria visual manual ou computadorizada ao diagnóstico.","B":"Avaliação clínica e laboratorial de hiperfunção e hipofunção hipofisária ao diagnóstico.","C":"Realização de RMN de hipófise de seis em seis meses.","D":"Realização de avaliação da função hipofisária de seis em seis meses."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-150745","number":"150745","sourceNumber":"150745","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Para o tratamento da tireotoxicose por tireoidite granulomatosa subaguda, é mais\nindicada a seguinte opção terapêutica:","options":{"A":"Metimazol.","B":"Propiltiouracila.","C":"Propranolol.","D":"Ablação com iodo radioativo."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-156470","number":"156470","sourceNumber":"156470","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"Na acromegalia existe deficiência do hormônio GH.","B":"No Diabetes Insipido existe secreção aumentada do hormônio antidiurético (ADH).","C":"Puberdade precoce é definida como surgimento dos caracteres sexuais secundários em idade\ninferior a 12 anos.","D":"No hipopituitarismo com deficiência de gonadotrofinas pode levar a oligomenorreia e\ninfertilidade."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-156483","number":"156483","sourceNumber":"156483","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"A doença de Basedow-Graves é decorrente da secreção diminuída de T3 e T4.","B":"A tireoidite de Hashimoto cursa com hipertireoidismo.","C":"O hiperparatireoidismo predomina em homens na infância.","D":"Os nódulos tireoidianos ocorrem mais frequentemente em idosos e indivíduos que vivem em\náreas com deficiência de iodo."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-156497","number":"156497","sourceNumber":"156497","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Marque a afirmativa correta:","options":{"A":"Na doença de Addison a produção de glicocorticoides esta aumentada.","B":"O hiperaldosteronismo primário é condição clínica caracterizada por produção excessiva de\naldosterona pelo córtex suprarrenal.","C":"A Doença de Behcet está associada a tumor maligno da suprarrenal.","D":"Na hemocromatose o ferro corporal esta diminuído."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-157024","number":"157024","sourceNumber":"157024","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um recém-nascido de 10 dias é atendido com quadro de icterícia. A mãe relata que ele\npermaneceu internado na maternidade durante 5 dias por ter apresentado hipoglicemia e icterícia.\nO peso e o comprimento ao nascer são 3.000 g e 49 cm, respectivamente. Ao exame físico,\nmostrou-se ativo, ictérico, com tônus adequado, micropênis e testículos tópicos. Assinale a\nalternativa correta, que apresenta o diagnóstico mais provável.","options":{"A":"Síndrome de Noonan.","B":"Hipotireoidismo congênito.","C":"Hipopituitarismo.","D":"Síndrome de Silver-Russe."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-157030","number":"157030","sourceNumber":"157030","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Um recém-nascido com 2 semanas de vida, mamando exclusivamente ao seio materno,\napresenta perda de peso, recusa alimentar, vômitos, desidratação com sódio = 120 mEq/L e\npotássio = 6,5 mEq/L, além de glicemia de 40 mg/dL. Qual é o diagnóstico mais provável?","options":{"A":"Filho de mãe diabética.","B":"Ingestão insuficiente de leite.","C":"Hiperplasia adrenal congênita.","D":"Estenose hipertrófica do piloro."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-150258","number":"150258","sourceNumber":"150258","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Recém-nascido submetido ao teste do pezinho, com 24 horas de vida, é levado à\nprimeira consulta pediátrica com o exame cujo\nresultado apresenta o seguinte valor: TSH 15 ?U/ml\n(valor de referência < 10 ?U/ml). Neste caso, a conduta deve ser:","options":{"A":"tratar o hipotireoidismo.","B":"repetir a coleta do TSH.","C":"dosar a tireoglobulina.","D":"realizar USG cervical."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-127094","number":"127094","sourceNumber":"127094","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Com relação às condutas no perioperatório de tireoidectomia em paciente com\ndiagnóstico de hipertireoidismo, assinale a afirmativa incorreta.","options":{"A":"Manter o uso de soluções iodadas por via oral no pré-operatório, pode reduzir o fluxo sanguíneo,\na friabilidade e o sangramento da tireoide no\nperioperatorio.","B":"Está contraindicado o uso de iodo por via oral no pré-operatório de tireoidectomia em paciente\ncom bócio nodular tóxico.","C":"Na presença de tireotoxicose, é necessário administrar drogas antitireoidianas,\nbetabloqueadores e glicocorticoides antes da tireoidectomia.","D":"Soluções iodadas e tionamida devem ser mantidas por, pelo menos, 5 dias após a\ntireoidectomia."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-136569","number":"136569","sourceNumber":"136569","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Existe a hipótese de que o carcinoma papilífero possa se transformar em qual dos tipos\nde carcinomas citados abaixo?","options":{"A":"Medular.","B":"Linfocítico.","C":"Hürtle.","D":"Anaplásico."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-127097","number":"127097","sourceNumber":"127097","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Todos os sinais e sintomas a seguir são compatíveis com hipertireoidismo, exceto:","options":{"A":"Menorragia.","B":"Ansiedade.","C":"Mixedema pré-tibial.","D":"Diarreia."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-128006","number":"128006","sourceNumber":"128006","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Dentre os achados clínicos abaixo, serão encontrados com maior probalidade num\npaciente que apresenta altos títulos de anticorpo antirreceptor de tireotrofina:","options":{"A":"Pele seca e macroglossia","B":"Obstipação e hipertensão diastólica","C":"Hipertensão sistólica e insônia","D":"Depressão e derrame pericárdico"},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-127675","number":"127675","sourceNumber":"127675","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente de 37 anos apresenta bócio difuso discreto, elevação de T4 livre, supressão\nde TSH e captação de radioiodo elevada na 2ª\nhora, mas normal da 24ª hora. Considerando o caso\nclínico:","options":{"A":"A tireotoxicose por tireoidite é o diagnóstico mais provável.","B":"O uso de antitireoidiano por 18 a 24 meses quase sempre leva à cura.","C":"O anticorpo para o receptor de TSH geralmente está elevado nessa doença.","D":"A contaminação por iodo deve ser descartada."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-138241","number":"138241","sourceNumber":"138241","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino teve diagnóstico de tiroidite de Hashimoto aos 20 anos,\nquando foram detectados TSH = 20 mUI/L,\nanti-TPO e anti-Tg positivos. Durante a vida da paciente\nserá necessário adequar a dose de L-tiroxina para valores de TSH considerados ideias para cada\nperíodo. Qual valor de TSH está adequadamente correlacionado com o estágio de vida?","options":{"A":"Gravidez, primeiro trimestre - TSH <2,5 mUI/L.","B":"Gravidez, segundo trimestre - TSH <3,0 mUI/L.","C":"Adulta jovem - TSH entre 0,5-2,5 mUI/L.","D":"Idosa - TSH <2,5 mUI/L."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-129852","number":"129852","sourceNumber":"129852","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Constitui uma característica indicativa de necessidade de punção de nódulo tireoidiano\npara exame citológico:","options":{"A":"Tamanho > 1,0 cm.","B":"Presença de calcificações grosseiras.","C":"Avaliação com Doppler mostrando fluxo periférico maior que o central.","D":"Captação de iodo aumentada na cintilografia de tireoide."},"answer":"A","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-127351","number":"127351","sourceNumber":"127351","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Quanto ao tratamento de arritmias cardíacas, eventualmente indicamos antiarrítmicos\nvia oral. Qual dos listados abaixo interage\nfortemente com a disfunção tireoidiana?","options":{"A":"Propafenona.","B":"Amiodarona.","C":"Propranolol.","D":"Digoxina."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-138635","number":"138635","sourceNumber":"138635","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Em relação ao diagnóstico do câncer de tireoide, marque a alternativa correta.","options":{"A":"Os nódulos frios não são associados à malignidade, devido ao baixo metabolismo apresentado\npor estes.","B":"A tomografia cervical é um dos exames de melhor qualidade para avaliação dos nódulos\ntiroidianos, devido à sua atual capacidade de visibilização destes nódulos.","C":"A ressonância nuclear magnética demonstrou ser um excelente exame de avaliação\n\npré-operatória devido à ausência de necessidade de uso de contraste iodado, como no caso da\ntomografia.","D":"A punção aspirativa por agulha fina é o método diagnóstico mais simples para se\ndiagnosticar neoplasia de tireoide."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-112360","number":"112360","sourceNumber":"112360","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente do sexo feminino, de 40 anos, traz Ultrassonografia (US) de tireoide\nmostrando nódulo de 20 mm em lobo direito,\nhipoecoico, com margens regulares e calcificações\ngrosseiras no seu interior, sem qualquer outra alteração no parênquima tireoidiano. Provas de\nfunção tireoidiana normais. Solicitada punção aspirativa com agulha fina guiada por US do nódulo\nde lobo direito, cujo resultado citológico foi: ?Bethesda I ? Amostra não diagnóstica?.\n\nQual conduta deve ser indicada para a paciente?","options":{"A":"Realizar tireoidectomia.","B":"Repetir a punção aspirativa com agulha fina, guiada por US dentro de 3-6 meses.","C":"Solicitar cintilografia com radioiodo.","D":"Seguir com US de tireoide."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-111407","number":"111407","sourceNumber":"111407","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Qual tratamento é uma opção indicada na Doença de Plummer?","options":{"A":"Uso prolongado de drogas anti-convulsivantes","B":"Embolização arterial","C":"Vagotomia seletiva","D":"Tireoidectomia","E":"Dilatação uretral"},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-101157","number":"101157","sourceNumber":"101157","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 27 anos, assintomática, descobriu nódulo na região cervical. Foi submetida à\nultrassonografia de tireoide, que evidenciou nódulo localizado no terço médio do lobo esquerdo. Era\núnico, sólido, heterogêneo, predominantemente hipoecogênico, com microcalcificações e\ncalcificações grosseiras, bem delimitado por fino halo hipoecogênico, medindo 2,3 x 1,8 x 1,5 cm.\n\nPara esta paciente, a conduta adequada é:","options":{"A":"Iniciar terapia de supressão com levotiroxina, com o objetivo de reduzir o tamanho do nódulo\ntireoidiano e minimizar o risco de malignização.","B":"Solicitar controle ultrassonográfico de tireoide em seis meses para avaliar a evolução do nódulo\ne redefinir a conduta.","C":"Indicar tireoidectomia total pelo alto risco de malignidade, dadas as características do nódulo.","D":"Solicitar Punção Aspirativa por Agulha Fina (PAAF), guiada por ultrassonografia, do nódulo\ntireoidiano."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-106729","number":"106729","sourceNumber":"106729","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Paciente feminina, 34 anos de idade, procura assistência médica em função de\nnervosismo e choro frequentes, ?coração\ndisparado?, não tolera calor e tem sudorese aumentada.\nAo exame físico, apresenta frequência cardíaca de 102 bpm, pressão arterial 130 x 90 mmHg, pele\nquente e úmida, discreto espessamento da pele nas regiões tibiais. Mediante o caso clínico\ndescrito, escolha a alternativa correta acerca da principal hipótese diagnóstica e medidas\ncomplementares.","options":{"A":"Hiperparatiroidismo, dosar hormônios tireoidianos e iniciar levotiroxina.","B":"Síndrome do pânico, iniciar sertralina e encaminhar paciente para suporte de psicanálise.","C":"Feocromocitoma e solicitar tomografia de abdome.","D":"Hipertiroidismo, dosar hormônios tireoidianos e solicitar ultrassonografia de tireoide."},"answer":"D","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-111397","number":"111397","sourceNumber":"111397","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Após tireoidectomia total para tratamento de câncer de tireoide, Paula apresentou\ndisfonia com dificuldade de emitir sons agudos.\nO que ocorreu?","options":{"A":"Lesão do nervo laríngeo superior interno.","B":"Lesão do nervo laríngeo superior externo.","C":"Lesão do nervo laríngeo recorrente superior.","D":"Lesão do nervo laríngeo recorrente interno.","E":"Lesão do nervo laríngeo recorrente externo."},"answer":"B","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-110242","number":"110242","sourceNumber":"110242","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Mulher de 63 anos procura atendimento na unidade básica de saúde com queixa de\nastenia, inapetência, irritabilidade e sonolência excessiva há 3 meses. É hipertensa em uso regular\nde enalapril, sem outras comorbidades. Na investigação do quadro, apresentou TSH 6,5 mg/L (\nreferência 0,5 - 5,0 ), T4 livre 0,9 mg/L ( referência 0,8 - 1,8 ) e anti-TPO positivo. Em relação\nao\nquadro tireoideano, a conduta deve ser:","options":{"A":"Repetir TSH e T4 livre em dois meses para confirmar o diagnóstico.","B":"Solicitar cintilografia de tireoide e iniciar levotiroxina se não houver hipercaptação.","C":"Iniciar levotiroxina independentemente de exames adicionais.","D":"Solicitar ultrassonografia de tireoide e iniciar levotiroxina se não houver nódulos."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-endocrinologia-end-1-78153","number":"78153","sourceNumber":"78153","collectionBlock":"medcurso:medcurso-endocrinologia-end-1","collectionLabel":"Medcurso · END 1","documentBlock":"","area":"Endocrinologia","specialty":"Endocrinologia","topic":"END 1","subtopic":"","stem":"Qual a melhor opção para rastreio de síndrome de Cushing?","options":{"A":"ACTH plasmático (2 dosagens) e ressonância magnética de hipófise.","B":"Cortisol urinário livre (3 amostras) e ACTH plasmático.","C":"Cortisol urinário livre (3 amostras) ou cortisol salivar às 23 horas (3 amostras) ou teste de\nsupressão com 1 mg de dexametasona.","D":"Cortisol urinário livre (3 amostras) e teste da supressão com 8 mg de dexametasona."},"answer":"C","source":"Endocrinologia/END 1/END 1.txt","sourceLabel":"Medcurso · END 1","images":[],"optionImages":{},"commentImages":[],"tags":["Endocrinologia","END 1","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
